/* 平成30年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h30.committeeSessions.push(...[{"id":"h30-20180122-6","meetingId":"h30-cm01","date":"2018年1月22日","dateIso":"2018-01-22","committee":"区民委員会","time":"午後 １時００分～午後 ２時４３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"荏原第四区民集会所の４月からの利用","agenda":"荏原第四区民集会所の４月からの利用","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"無事、改修工事が終わったということで、幾つか要望として挙がっていた、トイレの改修、プロジェクターやスクリーン、マイクについてはどのように改善されたのかをお伺いしたいと思います。いずれにしても、今後また新しい仕様になった区民集会所になりますので、住民から様々な要望が寄せられるかと思いますけれども、それについても真摯に対応していただきたいと思います、その点についてもお伺いします。","respondent":"伊崎地域活動課長","answer":"マイクにつきましては持ち運びができますので、いずれの集会室でもお使いいただけることになります。今回、４月にオープンいたしますので、また再開をしましてから、ご利用者の方の声もお聞きしながら改善できるところは改善していきたいと考えております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"順次、改修工事が進んでいるので、地域センターごとによって形も規模も違うので、一定いろいろ条件はあるとは思うのですけれども、今後もこういう条件が合えば、カラオケが使用できる防音設備を進めていく方向があるのか、どういうお考えなのか。その辺をお伺いしたいと思います。","respondent":"伊崎地域活動課長","answer":"他の区民集会所につきましては、まだ大規模な改修計画が具体的ではございませんので、今ここではっきりと申し上げるのは難しいですが、同じように地域の方のご要望を聞きながら、あとは立地や施設など、いろいろな状況もありますので。","voiceIndex":7,"id":"exchange-002"}]},{"id":"topic-02","title":"交流都市地方物産展の開催","agenda":"交流都市地方物産展の開催","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"前回、実施をされて、まちの元気につながる取組みがどう進み、地方創生への協力・貢献にどのような効果があったのか、区の評価を伺いたいと思います。３００万円という予算を使っていますので、このあり方はどうなのかという思いは、正直、持っていますので、効果についてお伺いしたいと思います。","respondent":"伊崎地域活動課長","answer":"それを通じて、お買い求めになった方も、その市町村に興味を持っていただけたと考えています。先ほどご報告しそびれたのですが、こちらの経費につきましては、東京都からの観光まちづくり推進支援事業補助金という補助金で１２５万円ほどの補助をいただく予定となっております。","voiceIndex":13,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"もちろん自治体間が交流をしたり、それぞれの自治体の魅力を東京で紹介するということ自体は大事な役割はあるとは思いつつも、こういうあり方はどうなのだろうというのがひっかかっている部分があるので、出店自治体からどういうご意見・ご要望がというのを最後に伺いたいと思います。","respondent":"伊崎地域活動課長","answer":"先ほども申し上げましたが、なかなか都会の品川区の皆様が集まるところで、物品を売ってＰＲができる機会が少ないということで、大変感謝をされてあります。千葉県物産展はかなり売上げも上がったということで、そういった点でも感謝をいただいているところです。","voiceIndex":15,"id":"exchange-004"}]},{"id":"topic-03","title":"「品川区サイバーセキュリティに関する協定」の締結","agenda":"「品川区サイバーセキュリティに関する協定」の締結","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"社会的にも決して許されないサイバー犯罪、攻撃も含めて、それに対応していくことは、そういう必要がある社会になってきたと感じるのですけれども、お伺いしたいのは、都内で初ということもありますが、区内中小企業の被害の実態や状況です。今回、協定締結に至った動機、その実態について伺いたいと思います。","respondent":"菅生活安全担当課長","answer":"そうしたことで、東京都を中心として、先ほどもお話ししましたTcyssというネットワーク、こちらは平成２８年にできておりますけれども、こういういろいろな関係機関が連携しながら、中小企業をサポートしていこうというのが当初の考えです。","voiceIndex":24,"id":"exchange-005"}]},{"id":"topic-04","title":"目黒サービスコーナーの開設および運営","agenda":"目黒サービスコーナーの開設および運営","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"その上で伺いたいのですけれども、効率的な運営とありますけれども、年間で幾ら効率的になるのか、何が効率的になるのか、その点を伺いたいと思います。私は、区の職員の窓口対応も、丁寧に日々、業務をされていると思うのですけれども、それにも勝るというのは何を指しているのか、その点も伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"多言語対応ということで、どうすれば外国人のお客様にもスムーズなご案内ができるかということで、英語を話せるスタッフの配置に努めますとか、外国語の案内ボードを作成するとか、そういう区ではなかなかアイデアが思い浮かばない部分を民間企業にお願いするものです。","voiceIndex":30,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問","question":"単にコストではなく、事務の流れとのご説明がありましたが、つまりはコスト減にはならないということなのか、その点を伺いたいと思います。その意味でも、事務の流れはむしろ複雑化し、ひいては住民サービスの向上にはつながっていかないと思いますけれども、この点についてはいかがでしょうか。","respondent":"提坂戸籍住民課長","answer":"受付、作成をして、最終的に交付をする事業者の方、検認をする職員、疑義があったときに対応する区の職員、それぞれ時間の短縮に努めて、お客様をなるべく待たせないような方法を大井町サービスコーナーでは努めてありますけれども。","voiceIndex":32,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問","question":"今のご説明でも、コスト減についても、また事務の流れについても、一層、複雑化するだけであって、私はこの業務を民間事業者に委託するというのはやはりやめるべきだと思います。最後に、個人情報について、関連して１点伺いたいのですけれども、４月２１日の区民委員会の際に、情報漏えいの問題が報告されて、私が原因について質問したところ、失念したというご答弁がありました。","respondent":"提坂戸籍住民課長","answer":"４月にご報告した漏えいの件につきましては、正式なＤＶ支援が出ていない方について、情報が漏れてしまったですけれども、住民票上、夫と妻が同一世帯の方で、そこら辺の認識を職員が失念してしまって。","voiceIndex":34,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"民間委託になった場合、窓口で受け付けた民間の職員と、その書類の報告に基づいて交付をする区の職員、こういう形になるわけです。ですので、今回の情報漏えいをどのように教訓化し、そして、それがこの業務の民間事業者への委託で、仕組み上、なぜ防げるとなるのか、そこをご説明いただきたいと思います。","respondent":"提坂戸籍住民課長","answer":"今回の教訓を踏まえまして、サービスコーナーと本庁舎と各地域センターでも、しっかりと個人情報の保護に努めてまいりたいと思います。","voiceIndex":36,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問","question":"疑義が生じた、その判断は民間事業者の窓口ということでよいのか、そこで疑義が判断できなければスルーしてしまう仕組み上の盲点がそこにあるのではないか、この２点を最後に伺いたいと思います。改めて、こうした民間事業者への委託は、私はやめるべきだと思います。","respondent":"提坂戸籍住民課長","answer":"それは区の窓口でも、区の職員が最初、一義的に窓口対応をするわけですけれども、その画面のメッセージを見た場合、自分で判断できなければ、ほかの職員に代わってよく確認しているということなので、状況的には全く同じことでございまして。","voiceIndex":38,"id":"exchange-010"},{"speaker":"藤原委員","kind":"確認","question":"本人確認は免許証とかパスポートでするということですが、窓口に行って、免許証を提出すると、こういう丸い、あれは光なのですか、免許証を置いて調べます。私はパスポートで本人確認したことはないですから、目視ではなくて機械等でやる方法というのはあるのでしょうか。","respondent":"提坂戸籍住民課長","answer":"それは民間委託でも直営でも同じことですけれども、その辺はしっかりと今後も確認をしてまいりたいと思います。","voiceIndex":40,"id":"exchange-011"},{"speaker":"藤原委員","kind":"確認","question":"そういうふうに実例が出た以上は、今、マイナンバーカードというお話も出ましたが、免許証だけはやる、パスポートとマイナンバーカードは目視でというのはどうしてかと私は思うのです、免許証はやるわけですから。その辺は、行政ですから、しっかりきちんとやっていかないと、また問題意識を持って対応していかないといけないと思うのです。行政ですから。その辺についてはいかがですか。","respondent":"提坂戸籍住民課長","answer":"その辺は十分に、個別によく確認させていただきたいと考えております。","voiceIndex":42,"id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"そういうテクニックが、半分ぐらいこうやると透かしのような効果が出てくるという、そういう事実があるのは知らなかったもので、こういう質問をしてしまったのです。そうしましたら、民であっても官であっても、対面でやる職員の方は大体わかっているわけですね。パスポートは半分にして、そうすると透かしみたいになるということは、職員の皆さんはわかっているということですね。","respondent":"提坂戸籍住民課長","answer":"十分、職員は認識しているはずですけれども、再認識してもらうためにも、もう一回周知徹底を図ってまいります。","voiceIndex":44,"id":"exchange-013"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"簡易型総合評価方式により決定ということで、１月末には事業者が決定されるスケジュールですけれども、先ほどご説明の取扱業務の中で、住民票の発行とか印鑑証明書以外にも、全部メモし切れなかったのですけれども、建築関係の申請書とか、いろいろやることがあるみたいなのですが、そういったスキルを持った事業者を選定する上で、この簡易型総合評価方式での事業者選定に際し。","respondent":"提坂戸籍住民課長","answer":"簡易型総合評価方式について簡単にご説明いたしますけれども、価格のみの競争になじまないものについて、事業の執行体制ですとか、過去の実績等、価格以外の要素を含めたものを総合的に評価して受託者を決定する方式によって、受託者の選定を行うものです。","voiceIndex":46,"id":"exchange-014"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"今回この総合評価方式で決定していくにあたって、こういうサービスコーナーの事務取扱いで、結構たくさんの事業者があるというお話もあったのですが、どういう類の事業者、ほかのところでも経験をされているようなところがやはり多いのかというところと、沿革というか、どういった形の事業者がこういうところに応募してきたのかということの説明をできる範囲でしていただければと思います。","respondent":"提坂戸籍住民課長","answer":"今回も複数社、指名をさせていただいているのですけれども、沿革というのはそれぞれでございまして、もともと区役所における戸籍のタイプ打ちの受託を行っているとか、区の業務とは直接関係ございませんが、パスポート、旅券関係の事業を行っているとか。","voiceIndex":48,"id":"exchange-015"}]},{"id":"topic-05","title":"「第２８回 伝統の技と味／しながわ展」の開催","agenda":"「第２８回 伝統の技と味／しながわ展」の開催","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"予算なのですけれども、会場等使用料が入っているのですが、１１５万７,０００円は、使用料という点で、どこからこういう数字が出てくるのでしょうか。別個に会場設営経費が入っていて、私もしながわ展に行きましたけれども、会場はいろいろ設営があるのはわかっているのですが、まず使用料についてお伺いしたいのと、使用料と設営で２８０万円ぐらいかかる、この辺についても教えていただけますか。","respondent":"山崎商業・ものづくり課長","answer":"会場使用料と、そうしたことをお願いする委託料という性格のものがここに入ってあります。","voiceIndex":54,"id":"exchange-016"},{"speaker":"藤原委員","kind":"質問","question":"細かくてすみませんけれども、入口に枠をとか、それは設営経費ではないのですか。それも使用料なのですか。使用料というのは使用料ですよね、きゅりあん７階。設営料は設営料で、使用料に１１５万７,０００円もかかっているわけです。","respondent":"山崎商業・ものづくり課長","answer":"もともと組み上げるものは、区の備品として、中小企業センターの倉庫にありますので、そういったものを運送屋が運んで、きゅりあんに届けるというところで運搬委託をかけているのと、それから。","voiceIndex":56,"id":"exchange-017"},{"speaker":"藤原委員","kind":"質問","question":"今までいろいろやっている施策の中で、イベントでも、こういう行事でも、会場使用料とかが出てくるではないですか。見ていて、百何万円というのはあまりないですよね。だから、使用料は使用料でいいのです。だから、これだけ使用料という形で出るのがどうしてですかというのを伺っているのですけれども、課長の答弁でそれが全部入っていると言い切られてしまうと、そうなのですかとしか言えないんですが。","respondent":"山崎商業・ものづくり課長","answer":"るる説明申し上げたのは、会場等使用料の部分で、会場設営経費と実演等委託料、これは伝統工芸の方々にお支払いするものが１６０万円と、その下の１００万円弱という内容になっています。","voiceIndex":60,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"一方で、保存会の方々も、世代継承というのでしょうか、次の若手を育てていくにもいろいろご苦労があるというお話も伺っておりますけれども、この「技と味／しながわ展」をもっと盛り上げていくにはどんなことが課題になっているのか、工夫が必要なのか、保存会の方からはどういうご要望があるのか、お伺いしたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"課題と申しますのは、１００年を超える伝統を守り続けているという意味では、長い間、同じものを愛着を持ってつくり続けているという継続性と、それから今の時代にマッチした周知・ＰＲは何だろうというところで、保存会の方々と区でも、そこが一番の課題かと思っています。","voiceIndex":62,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"今、ＰＲグッズの話もありましたけれども、年に１回のこの企画を通じて、そういう視点でさらに盛り上がっていけるような、また、地域の方々とともに来訪者の方々にも触れたり接したり購入していただけたり、そういう方向でぜひとも進めていただきたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"申し訳ございません、先ほどの答弁、会場等使用料の説明が伝わらなかった点で、きゅりあんのイベントホールの利用料と、それから、いろいろな備品をレンタルしているレンタル料で、そこはハードのものですので、ご理解を賜りたいと思います。","voiceIndex":64,"id":"exchange-020"}]},{"id":"topic-06","title":"「事業承継フォーラムおよび永年継続事業所表彰式」の開催","agenda":"「事業承継フォーラムおよび永年継続事業所表彰式」の開催","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"あわせて今、事業承継事業が品川区でも始まっておりますが、その取組みの状況について少しご報告いただきたいと思います。ご相談だったり、実際の成立の件数であったり、どういう規模で今は進んでいるのか。まだ始まって間もない事業ではありますけれども、現状について伺いたいのと、こういう機会を通じて、多くの方にそういう事業の周知が広がったらいいと思いますが、現状を伺いたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"今、るるお話ししましたようなことで、事業承継はこれからの産業の活力を生む上ですごく重要な内容の仕事だと考えておりますので、一定、継続性を持ちながら、工夫を持って続けていく必要があるという形で捉えてあります。","voiceIndex":70,"id":"exchange-021"},{"speaker":"塚本副委員長","kind":"質問","question":"今のお話だと、それだけではなくて、事業を後継される方がいるのだけれどもうまく承継できない。きちんと承継がされなくて、商売が傾く。そういうところを支援していこうというところもあるのかと思ったのですけれども、この事業のフォーカスしている狙いというのは、そういうことでよろしいのでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"ただ、同様のアンケートで一番高かったものについては、やはり事業の将来性とか後継者の育成とか、そちらのほうが課題のポイントとしては高いという数字もいただいておりますので、全く打つ手がない状態ではないというところを切り口にして。","voiceIndex":72,"id":"exchange-022"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"お伺いしたいのは、黒字で事業的に回っているのだけれども、それでも後継者が出てこない、任せる人が見当たらないというのは、どういう実態なのでしょうか。いくらでもいるのではないかと思ったりもするのですけれども、どういう事業にそういう、黒字なのに後継者が出てこないところがあるのかを教えていただきたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"全て汎用的にデータを取得したという意味ではありませんが、いろいろ経営者の方に直接お聞きするのは、区内の中小企業の規模でいいますと、やはり２０人を下回るような小規模事業所がかなりの比率で存在している、現状はそういう状況です。","voiceIndex":74,"id":"exchange-023"},{"speaker":"塚本副委員長","kind":"質問","question":"そうしますと、いわゆる公募で、一般にやりたい人ということで募るのは、なかなかそぐわないところなのか。そういうところで、いわゆる後継者をどのように見つけていくか、指名していくかというところでの、現段階での展開なりを教えていただければと思います。","respondent":"山崎商業・ものづくり課長","answer":"それは会社１つのものではなくて、区内産業の活力のためにも継続をすることが区としても必要ですと、社会性のあるお仕事をされているというところをセミナーなどで訴えまして、少人数職場ですけれども、いわゆる家族ではありませんが。","voiceIndex":76,"id":"exchange-024"}]},{"id":"topic-07","title":"「ウーマンズビジネスグランプリ２０１８」の開催","agenda":"「ウーマンズビジネスグランプリ２０１８」の開催","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"今日は課長から２つ説明がありましたけれども、そういう意味においての都市型観光という意味合いも私はあると思っているので、産業の振興という意味の課としての考えはどうかということと、もしよければ、文化観光の課長も、都市型観光という意味において、こういう施策をどう活用していくか、お考えがあるならば教えていただければ幸いです。","respondent":"山崎商業・ものづくり課長、鈴木文化観光課長","answer":"そういう意味では、ウーマンズもそうですけれども、いろいろな事業を起こす上で、先進的な、先駆的な、あるいは刺激的なものがあって、起業家の皆さんが集まってくるようなことというのは、ある意味、観光視点にも資するような。ただ、都市型観光の特徴の１つに、地域の取組みで継続をして、区外から、特定の方ではなくて、広く楽しんでいただくというところがありますので、いろいろなウーマンズビジネスグランプリや品川情報クラスターフェアも。","voiceIndex":85,"id":"exchange-025"}]},{"id":"topic-08","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"スクエア荏原のほうだけ伺いたいのですけれども、事情はよくわかりました。ただ、１２月という意味では、年末ではありますけれども、年度途中であると思うのですが、もともとの契約がどうだったのか。そこから見て、やむを得ないという判断に至った経過について、もう少しご説明いただきたいと思います。例えばこういうところも障害のある方の就労の場、訓練の場、そういう視点というのは持てないものなのか。","respondent":"鈴木文化観光課長","answer":"それから２点目の、中小企業センターの例のように、例えば障害のある方の就労の場ですが、当初、あそこを純粋な喫茶として運営するときは、その案も考えたのですが、先ほど申し上げましたように、今回は観光の案内や情報発信、地域のコミュニティ。","voiceIndex":94,"id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2800#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":29099,"voices":97}},{"id":"h30-20180122-7","meetingId":"h30-cm01","date":"2018年1月22日","dateIso":"2018-01-22","committee":"厚生委員会","time":"午後 １時００分～午後 ３時５２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を48件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"品川区立発達障害者支援施設 就労支援事業の変更","agenda":"品川区立発達障害者支援施設 就労支援事業の変更","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"具体的なところで何点か教えていただきたいと思うのですけれども、ぷらーすはげんきが請け負っていたかと思うのですが、委託されている事業者がどこかということの確認をお願いしたいと思います。それからもう１つ、発達障害の方で、こういう形で支援が必要な方がどれぐらいいらっしゃるのか、区としてつかんでいる人数とかがありましたら教えてください。","respondent":"中山障害者福祉課長","answer":"就労継続支援Ａ型とＢ型の需要についてなのですけれども、当初１０名１０名にしたというところは、例えば発達障害で引きこもりの方などが、リクトという相談事業から少しずつ外出ができるようになり、Ｂ型に通い、そしてある程度。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうしますと、就労継続支援Ａ型は、現在３人から２人になったということで、こういう方向になるということも踏まえてなのかもしれませんけれども、それほどたくさんの人数ではないということでずっと来ていたのでしょうか。もう１つ、成人期支援事業リクトは相談事業ということなのですけれども、相談の実績はどれくらいなのかという点についてもお聞かせください。","respondent":"中山障害者福祉課長","answer":"就労継続支援Ａ型の今までの推移です。今年度については３人スタートだったのですが、平成２７年、平成２８年は９人でスタートしておりますし、平成２６年は７人でということで、必ずしもずっと少ない人数だったわけではありません。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで最後に、ぷらーすの体制は、職員が９人ですか。職員はどういう資格の方がどういう形で仕事をされているかという、その体制だけ、教えていただきたいと思います。","respondent":"中山障害者福祉課長","answer":"就労継続支援Ａ型とＢ型は１０人に対して１人、それからそれにサービス管理責任者とかという基準があるのですけれども、実際リクトには、それ以外にたしか３人職員がいて、そちらは臨床心理士なども配置しております。","voiceIndex":9,"id":"exchange-003"},{"speaker":"石田（ち）副委員長","kind":"確認","question":"就労継続支援Ａ型のエヴリィが廃止されるということなのですけれども、Ａ型のエヴリィではどんな作業がされていたのかの確認と、あとリクトは、今７０人登録とあったのですけれども、登録定員はあるのでしょうか。そこだけお願いします。","respondent":"中山障害者福祉課長","answer":"就労継続支援Ａ型の作業内容ですが、パソコンを活用したというところで、スキャニングをして、その資料の台帳を整理するというような仕事を主に、それからあとは文章を起こす作業、テープ起こし、こうしたような作業もやっているところです。","voiceIndex":12,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"平成２６年から約４年間で、先ほどのご説明でも循環型で一般就労のほうにというところだったのですけれども、ここを通して一般就労に移った方がどれくらいいらっしゃるのかということだけ、お聞かせください。","respondent":"中山障害者福祉課長","answer":"全部で、就労継続支援Ａ型から４人、Ｂ型から６人の方が一般就労に移られております。","voiceIndex":15,"id":"exchange-005"},{"speaker":"若林委員","kind":"質問","question":"就労継続支援Ａ型が廃止ということで、変更の理由というところに、本来、Ａ型は雇用の確保ということが主目的であると。ただ、この間、約４年間やってきたところの目的は、一般就労へのステップをつなぐことを目的にしてきたと。区としてもそういうふうに判断をしていると捉えてよろしいのですか。","respondent":"中山障害者福祉課長","answer":"発達障害の方は、すぐにも就労できそうな方から、２０年間引きこもっていてなかなか外に出ることも難しいような方まで幅広いので、有期限のサービスというよりは、Ｂ型で相談も受けながら、生活リズムを整えるというのでしょうか、作業の能力がないわけではなく。","voiceIndex":18,"id":"exchange-006"}]},{"id":"topic-02","title":"（仮称）品川区立障害児者総合支援施設開設に向けての進捗状況","agenda":"（仮称）品川区立障害児者総合支援施設開設に向けての進捗状況","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回の総合支援施設は４つの法人が一緒に運営することになるのに対して、定期的に運営会議を開催しと書かれているのですけれども、定期的にというのはどれくらいなのか、前のところで１カ月に一、二回とかと書かれていたところもあるのですが、そういう形でずっとやり続けてこられているのか、そして、どういう中身で、現在、課題はあるのかというあたりもお聞かせいただきたいと思います。","respondent":"飛田障害者施策推進担当課長","answer":"今後の地域への説明会の件ですが、平成２９年３月に利用者向け、また、施設、団体等、関係者向けに行ったところですが、今後はまたこの施設ができてから、実習生の受け入れ等もありますので、港特別支援学校や城南特別支援学校の現在高校１年生、２年生の保護者。","voiceIndex":24,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうことでの説明会なのでしょうか。というのも、私、グローがもっと責任というか、もっとたくさんの事業をやるのかなと思っていたら、相談支援だけがグローという形になっているので、改めてこういうふうになるのかという思いがしたのですけれども、委員会でどの事業をどこが受け持つというのを報告しているというのがわかるところがあったら教えていただきたいのが１つです。","respondent":"飛田障害者施策推進担当課長","answer":"例えば２階の就労継続支援Ｂ型と訪問系サービスに愛成会と書いてありますけれども、訪問系はゆうゆうが北海道で実績があるということも活かして、今、そういうところも協議しています。","voiceIndex":26,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"建物も中の事業にしても、総合ですから、かなり大きな施設になっていくことになると思うのですけれども、法人もまだこれが確定ではないということであれば、大体これぐらいの事業をやるとしたら、この総合支援施設で職員としてはイメージとして何人ぐらいになるというところがわかったら、教えていただきたいと思います。","respondent":"飛田障害者施策推進担当課長","answer":"現在、品川児童学園自体で職員は、常勤もいれば非常勤もいるのですけれども、たしか３２人います。ここでは生活介護や短期入所等、レストランカフェとか、そういういろいろなサービスが入っています。ですので、１００人近くにはなるのではないかなと考えています。","voiceIndex":28,"id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点では、この施設の情報を各障害者団体の皆さんにもしっかりとご説明いただいて、ご意見をお聞かせいただきながら、要望も取り入れられるところはぜひ取り入れるような形で、３月上旬には各団体への説明会もされるというところですので、ぜひ団体の皆さんのご意見やご要望にもお応えいただけるような形で進めていただきたいと思うのですけれども、最後にその点だけ、お願いします。","respondent":"飛田障害者施策推進担当課長","answer":"今のところ、３月上旬には、先ほど申し上げましたけれども、特別支援学校の保護者、当事者、各団体の方にはお知らせしまして、一緒に利用するわけですから、より利用しやすい施設、また、皆さん期待されているのを重々感じておりますので。","voiceIndex":30,"id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"確認","question":"今後のスケジュールの件で確認なのですけれども、私もこの近くを通るときに見ているのですが、開設、完成は間に合うのですか。専門家ではないからわからないのですけれども、建築状況を見ていて、２月の完成はどうなのかなと。その辺、まず１点、教えてください。","respondent":"飛田障害者施策推進担当課長","answer":"今、建築のほうで、基礎をやっているというところです。今、私が聞いているところでは、平成３１年２月竣工を目指して、設計業者と施工業者、いろいろと協議しながら進めていると聞いております。","voiceIndex":32,"id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"私が勘違いしていたら申し訳ないのですが、一番最初の関係で、指定管理候補者である共同事業体フリーユニティーという言葉、これは最初からあったのでしょうか。私の感覚では、４つの事業者が指定管理を受けるのかなと思っていたのですが、最初からこの１つのものになっていたのでしょうか。そこを教えてください。","respondent":"飛田障害者施策推進担当課長","answer":"フリーユニティーという名称は、４つの共同事業体、４つのところが一緒になってプロポーザルをして、共同事業体フリーユニティーというところでこちらに出てきたということです。あくまでも４つの法人の共同体の名称となります。","voiceIndex":34,"id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問","question":"その共同体というのは、１つの法人を、別法人をつくっているわけではなく、４つがまとまってやっていると。品川の指定管理で今までそういう形がずっとあるのでしょうか。そこら辺が私の知識にないので。","respondent":"飛田障害者施策推進担当課長","answer":"あくまでもこのフリーユニティーというのは共同事業体の名称でありまして、それぞれ４法人、社会福祉法人３つと一般社団法人１つというところで取りまとまっております。指定管理のところでは、今、他の部署ともどのようにやっていくかというところの調整中になります。","voiceIndex":36,"id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"意見","question":"要するに、共同事業体というのは１つの法人にはなっていないわけですよね。１つになっていないところ、その中に４つ入っているものと指定管理というケースがあるのか、それでいいのかなというのが、ちょっとわからなかったので。","respondent":"飛田障害者施策推進担当課長","answer":"現在、共同事業体ということでは、図書館の運営もやっていると聞いております。今回、こちらはあくまでも共同事業体としてということではなく、各法人、４つの法人のまとまりがフリーユニティーということで、ただ名称がついているということになっております。","voiceIndex":38,"id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問","question":"共同事業体で、ここ１つであれば、それは違うと思うのだけれども、そこら辺が区としてどうなのかなと。今までなかった部分が入ってくるわけですよね。私は、最初、４つばらばらに指定管理をするのかといろいろな説明会に行ったときもそう思っていたのですけれども、契約が４つがまとまった１つのものと、というときに本当にさっき言った法人格のないもので対応し切れるのかどうか。","respondent":"飛田障害者施策推進担当課長、川島健康課長","answer":"委員がおっしゃるとおり、今までそういう４つの法人、各指定管理、また、同じ建物というものは、なかったところです。ですので、本当にどういうふうにやっていけばいいのか、実は非常に悩んでいるところです。今のやりとりのお答えになるかどうかというのはあるのですが、健康センターが、住友不動産エスフォルタ、それからＮＴＴファシリティーズ、住友不動産の共同事業体という形で指定管理をしていただいているという状況があります。","voiceIndex":42,"id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"確認","question":"共同事業体でできるという答えが、実際にあるのだからそれでいくのかなと思うのですけれども、さっきの説明にもあったかと思うのですが、４つの法人の中の人数の問題とか経理上の問題というのも相当複雑になるのではないかなというところなので、区として指導していかなくてはいけない部分、そこら辺をぜひうまく進めてくださいということで、もう１回、確認だけお願いします。","respondent":"中山障害者福祉課長","answer":"指定管理の結び方というところでは、今まさに共同事業体と結ぶほうがいいのか、それとも個別にある法人と結ぶほうがいいのか、どういったやり方があるかについて、今、検討を進めているところです。","voiceIndex":45,"id":"exchange-016"},{"speaker":"浅野委員","kind":"質問・要望","question":"今回、この資料も読ませていただいたのですけれども、進捗状況の中で４行目に「２法人が開設前より事業を開始し、区内における事業基盤の整備を図っている」とあるのですが、具体的に事業基盤の整備という部分についてどのようなことをこれまでやってきたのか、教えていただきたいと思うのです。お願いいたします。","respondent":"飛田障害者施策推進担当課長","answer":"それぞれ品川から遠く離れた事業所ですので、まず品川区のやり方とか、ほかの事業所との連携、そういうところを一緒にやりながら、どのように進めていくかというところを今まさに模索しながら、こちらに書かせていただきましたけれども、各施設の連携等。","voiceIndex":48,"id":"exchange-017"},{"speaker":"浅野委員","kind":"質問・要望","question":"大体イメージはつかめたのですけれども、事業基盤の整備、いつまでかかるのかなというのを教えていただきたいと思うのですが、４法人ということですので、それぞれうまくまとめていかなければならないという手順も必要だと思いますけれども、どのような形でまとめて、きちんとした形にしていくのか、概要で結構ですので教えてください。","respondent":"飛田障害者施策推進担当課長","answer":"開設まで１年ありますので、まずその１年をめどにして基盤をまとめ、それをまた新しく入ってくる２法人、そこも同じ施設に入りますので、そこでまた連携しながら、今まで培った基盤を整備したところを次の法人にも伝えるというふうに考えております。","voiceIndex":50,"id":"exchange-018"},{"speaker":"若林委員","kind":"質問・要望","question":"なおかつ、それは安定的と言えますと。そこら辺を対比しながらお聞かせいただきたいのが１つです。それから、グローに期待している、特に計画相談、相談件数については、ここまではしっかりやってほしいという、数値的なものがあるのか、区内にわずか４カ所しかないということもあるのかもしれないですけれども、区としてはグローにはどういうふうにお願いしているのか、端的にお願いしたいと思います。","respondent":"飛田障害者施策推進担当課長","answer":"グローが新しく仲間入りしまして、今まで相談というのは２つのところと、あと１つの精神というところでしたけれども、こういうときどうしようというところでいろいろな新たな発想、また、滋賀県ではこういうふうにやっているというところも聞きながら。","voiceIndex":53,"id":"exchange-019"},{"speaker":"若林委員","kind":"質問・要望","question":"ただ単にまとめるということにはとどまらないのだろうなと。それはきっと指定管理をするときの何か協定の内容であるとか、そもそも総合支援施設の理念であるとか、また、区民にこういう理念で１つ１つの事業を進めていくという、そういう夢と希望を与えられるようなものを当然期待されると思いますので、そこら辺について、非常に雑駁な質問になりますけれども、ご答弁いただければと思います。","respondent":"飛田障害者施策推進担当課長","answer":"そういうところでグローの力を発揮しながら、あとの３つの法人も一緒に力を合わせて行っていければなと考えております。","voiceIndex":55,"id":"exchange-020"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"先ほど運営会議を月に２回やられていると。それで、２０１６年のときの議事録を読んでも、１つ１つ課題についてもチェックして解決に向けてやっているという答弁があるのですけれども、今、人材確保とか指定管理というところもあったのですが、現時点での課題があれば、伺いたいなと思います。","respondent":"飛田障害者施策推進担当課長","answer":"ですので、そういうところを１つ１つ解決できるように、しっかりグローが中心となってやっていただけるように進めているところです。課題というのは、一番はやはり人材確保、それと質の向上というところになります。","voiceIndex":58,"id":"exchange-021"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"本当に大きな、新たな、そして期待も大きい施設になってくるので、人材確保というのはすごく要になってくるなと思いますので、ぜひ丁寧に進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-022"}]},{"id":"topic-03","title":"品川区第二期データヘルス計画","agenda":"品川区第二期データヘルス計画","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回、第二期データヘルス計画ということで、第一期が平成２８年３月につくられて、これは２年間という計画になっていたと思うのですけれども、第一期が２年間で今回６年間となったのはどういう理由からなのかということをお聞かせいただきたいのと、今回、健診率を上げるためなど、さまざまな取り組みが本当に旺盛に盛り込まれていると思うのですけれども。","respondent":"三ッ橋国保医療年金課長","answer":"実は、今、委員ご指摘のように非常に似ている部分がございまして、今回、同じようなものについては整合性をとろうと中で考えまして、例えば被保険者数についてどのように考えていくか、こちらの実施計画につきましては高齢者の医療の確保に関する法律に基づき計画し。","voiceIndex":65,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"いざ受けたいなと思ったときにそれをなくしてしまったりした場合、前はクリニックのほうでいつでもどうぞという感じで、なくしても区民健診は受けられる形になっていたと思うのですけれども、国保のところでは、用紙をなくした場合、クリニックに問診票とかが置いてあって、なくしてもその場で受けたいと言ったら受けられる仕組みになっているのかという確認もお願いしたいと思います。","respondent":"三ッ橋国保医療年金課長","answer":"ページ数は今調整中なので何とも申し上げられませんが、少なくとも国保基本健康診査等実施計画が５０ページ程度で、データヘルス計画が３０ページ程度かなと思いますので、全体で１００ページには満たないと８０ページ前後かなと思います。","voiceIndex":67,"id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"用紙をなくしたときなのですけれども、クリニックが用紙を持っていて、そこで問診票とか何かを書いて１回、受診したとするではないですか。そういう場合は返してもらいますよ、１回しか受けられないので、２回受けた場合は１回分は自費になりますよというところにサインをすれば、クリニックでも受けられる仕組みになっているというふうにも聞いたのですけれども、そういうふうにはなっていないのでしょうか。","respondent":"三ッ橋国保医療年金課長","answer":"先生方のウエイトといいますか、大変さと、また、こちらの国保全体の受診率向上というものが非常に難しい部分がございまして、全体の医師会の先生方としては、受診率向上に関してはもちろん了解は得ているのですけれども。","voiceIndex":69,"id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"受診券を忘れた、家に置いてきてしまったけれども、今日ぜひ受けたいという人について、クリニックに誰もが使用できる受診券が置いてあって、それで受けられるという仕組みにはなっていないということなのですか。区民健診のときはそういうのができたと思うのですね。","respondent":"三ッ橋国保医療年金課長","answer":"かかりつけ医の先生方ももちろん、データヘルス策定委員会の中でも受診率の向上は本当に健康寿命の延伸の部分で非常に大事だと思ってくださっていますので、やはり受診率向上に関しては、なるべく先生方の手をわずらわせないような方法をとっていきたいなと思っています。","voiceIndex":71,"id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"意見","question":"目標の健康寿命の延伸と医療費の適正化ということに向けて、受診の勧奨をよろしくお願いしたい中で、これから先、検討してもらいたいなというのが、受診率向上対策の(2)です。言われる可能性が高いと思います。健康課なら十分わかると思うのですが、地域的にないところがあるのですよね。だから、そこら辺も先々考えておいてください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":74,"id":"exchange-027"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"地域別にちゃんと出ているものなのだと感心してしまったのと、あと、受診しやすい体制を構築するというのはどういうことなのかなというのと、やっぱりこれだけ調査したり作成するのは大変だろうなと思うのですけれども、これは区独自で作成されているのか、どこか調査なんかは委託されたのか、伺いたいと思います。","respondent":"三ッ橋国保医療年金課長","answer":"モデル実施の部分ですが、地域別のデータにつきましては、健診の状況を地域別にはかってあります。区独自かどうかという部分ですが、データにつきましては業者に委託しておりまして、詳細な分析をしていただいており、事務局といたしましては、区が事務局となっております。","voiceIndex":76,"id":"exchange-028"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"受診しやすい体制というのは、受けていない方には引き続き通知をとおっしゃっていたのですけれども、それなのか、もうちょっと違った形があるのかというのと、あと、委託先はどこなのかというのを伺えたらと思います。","respondent":"三ッ橋国保医療年金課長","answer":"より多くの対象者が受診しやすい体制ということでございまして、できる限り考えてはいるのですけれども、受診勧奨につきまして、例えば全然受診していない方にこういうお知らせをしていきましょうとか、２年、３年受診していない方にはこのように工夫しましょうと。","voiceIndex":78,"id":"exchange-029"},{"speaker":"若林委員","kind":"質問","question":"後で読もうと思って、質疑の中であったので、右のページの、今、副委員長からあったところなのですけれども、平成３０年度一、二カ所モデル実施で、受診率が低い地域を対象に集団健診。これは何で低いところを２つ選ぶのですか。違いましたか。国の目標も当然あるのですよという力強さがないと、最初からそういう計画なのかと、いきなりそういうふうになってしまうので、そこのところはどうなのですか。","respondent":"三ッ橋国保医療年金課長","answer":"実施計画の部分にも関係してくるのですけれども、例えば国は６０％目指しますよ、だけれども、地方自治体によっては４５％程度でいいですよという考え方があります。区といたしましても、やはり受診率の向上につきましては、低い部分を底上げしていきたいという部分があります。","voiceIndex":81,"id":"exchange-030"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"障害者福祉が本当に複雑で、いろいろ読んでも隅々までわかるところまではなかなかいかないという思いがしているので、教えていただきたい点が何点かあるのですけれども、１つは、相談のところなのですが、品川区が基幹相談支援センターという役割を持つということなのですけれども、これは品川区の障害者福祉課の中に基幹相談支援センターという部署があって。","respondent":"中山障害者福祉課長","answer":"一方で、４つの拠点相談支援センターも、この間、相談の数もかなり増えてきていますし、そういう意味では、どういうものから地域と連携して役割を担っていただくかというのは整理しないといけないとは思っているのですけれども、抱え込むのではなく、連携の仕組みをつくることで。","voiceIndex":87,"id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私も、ここのところ、お話を伺いにいったりもしたのですけれども、かなり件数を抱えて、１人１００件とか、そういう形で抱えて、大変な状況というのも伺ったのですが、グローの相談が何件とか、計画相談が何件というのは、先ほどの総合支援施設の開設に向けての進捗状況のご報告の中にも平成２９年度から始まった実績が書かれていたのですけれども、それ以外のところで。","respondent":"中山障害者福祉課長","answer":"一般相談の件数というところでは、心身障害者福祉会館が、平成２８年度が６,４３８件、福栄会が１万５,３１６件、タイムが５,９９６件となっています。そこでの体制というところですが、心身障害者福祉会館では５人の常勤職員が対応しております。","voiceIndex":89,"id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで、なおかつそこの補助金がなくて、そこが支援費だけで回していく、経営的にも大変だとなると、民間のところに計画相談が回っていくという仕組みをつくるのがすごく大変なような気がするのですけれども、そこら辺はどう考えられているのかということと、もう１つ、障害児の相談支援なのですが、今も全ての方の計画相談がまだまだできていないという状況があると思うのですけれども。","respondent":"中山障害者福祉課長","answer":"ただ、もちろんずっと区で持っていくというつもりはありませんので、平成３１年目指して、どういう形で児の相談を受けていくか、その中で、ケアプランについては、放課後等デイサービスを開設している民間事業所なんかとも相談しながら。","voiceIndex":91,"id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"地域割りもしているのですが、介護でもそうなのですけれども、介護保険も誰でも自由に、事業所もケアマネジャーも選ぶことができるという仕組みになっています。私も荏原地域に住んでいまして、ぜひここは具体的に区として方針を持って対策を立てていただきたいなと思っているのですけれども、そこら辺の具体的な見通しというのはどう考えられているのかについてもお聞かせください。","respondent":"中山障害者福祉課長","answer":"それで、こういうような形で書かせていただいたところです。それから、荏原地区につくっていくには区が方針を持ってもっと積極的にというようなお話だと思います。は認識するところからスタートだなと思っています。","voiceIndex":93,"id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ああいう形で、ぜひ土地を区が取得して、プロポーザルで事業所を公募するとか、高齢者福祉のほうはさまざまな事業所がいろいろな地域からどんどん入るような形に今なっていると思うので、障害者福祉のほうでもそういう形で、土地を確保して、そして無償提供するというようなことで公募すれば、多分応募してくれる社会福祉法人があるのではないかなという思いがするのですけれども、今回。","respondent":"中山障害者福祉課長","answer":"荏原地区の話になります。グループホーム金子山のところはちょうどそういう土地の情報がありまして、あのとき、ミドリホームでしたか、グループホームが１個なくなってしまうということもありまして、急ぎ、補正もお願いして対応したところです。","voiceIndex":95,"id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だけど、自分で大もとのところはとりあえずはどこでも選ぶことができるのですよというのはまずお知らせして、合わない人が品川区と相談して初めてそこではないところに変われるというのではなくて、もともとは選べますよ、だけど選ぶところがないのであれば、地域割りをしているので、ここはどうですかという形にするのが基本なのではないかなと思うのですけれども、その点も最後。","respondent":"中山障害者福祉課長","answer":"相談のところですけれども、やはり基本的にケアプランの相談というところではどこの事業所でも対応できるような仕組みをつくっていきたいと思っています。","voiceIndex":97,"id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうすると、サポート２４なのですけれども、今、要項を見ているのですが、知的障害者８０人で精神障害者５０人という登録定員になっているのですけれども、実際の登録者がこれくらいいらっしゃるのかということと、登録した人は２４時間体制で相談ができるという体制になっているのでしょうか。その中でされている取り組みとか何かあったら、教えていただけたらと思います。","respondent":"中山障害者福祉課長","answer":"サポート２４になりますが、現在、登録者数ですけれども、平成２９年度は、知的障害者生活サポートは４０人の方が登録されています。精神障害者のほうが３６人の方が登録されています。","voiceIndex":99,"id":"exchange-037"},{"speaker":"大倉委員","kind":"質問・要望","question":"今後の見通しも、先ほどのお話の中では、まず認識するところからスタートというところで、認識するというのは、ないよということを認識するのか、その辺の認識とはどういう認識なのか、教えてほしいのと、情報収集ということもおっしゃっていたのですが、その情報収集というのはどういうことなのか、教えてください。","respondent":"中山障害者福祉課長","answer":"例えば入所施設なんかは品川区全体でこれぐらいあればいいだろうとなると思います。この中で、就労継続支援のところは自力通所ということになっていますので、障害のある方が自分で通うことを考えると、この事業についてはやはり地域ごとにあったほうがいいと認識しています。","voiceIndex":102,"id":"exchange-038"},{"speaker":"大倉委員","kind":"質問・要望","question":"土地や賃貸という部分でもしっかりと情報を集めながら、民間企業と連携しながらやってはいるけれども、なかなか今できていないという状況で、その辺の課題というか、現状、どうしてなかなかそううまくいかないかというところの区の考えと、今後、土地の取得というだけではなくて、しっかりと民間企業とさまざま連携していきながらつくっていくというのは大事なことだと思うので、最後。","respondent":"中山障害者福祉課長","answer":"グループホームですとか就労継続支援Ｂ型というのは、まさにそういう考えからいくと、民間活力をうまく活用しながら、必要な支援が何なのかというのをご相談の中で考えられればと考えていますので、そうした方向で荏原地域への開設を目指していきたいと考えています。","voiceIndex":104,"id":"exchange-039"},{"speaker":"若林委員","kind":"質問・要望","question":"それで、そこに関連して、まとまった数を指定特定相談支援事業所にプランとか支給決定のお手伝いをしてもらいたい、区だけでは手が回らないからそこにやってもらいたいのだけれども、資格者を１人置かなければいけないということで、まとまった数にならないと渡せないというのか、まとまった数にして渡す、そうしないと効率的に指定特定相談支援事業所が成り立たないのだという構造もあって、そうすると。","respondent":"中山障害者福祉課長","answer":"すみません、私の説明もちょっとわかりにくかったと思います。支給決定までの流れということですが、最初にご相談があって、そのご相談からどういったサービスが必要かということの見当がつくわけです。","voiceIndex":107,"id":"exchange-040"},{"speaker":"若林委員","kind":"意見","question":"まだ私も完璧に理解できていないと思いますけれども、いずれにしても、数字でいきますと、私の同僚議員からも以前から指摘があったところで、このプロセスの中で要するに一般相談、基本相談があって、いわゆる給付のところにいくのに、最後は今は計画案があって、支給決定をして、計画の案がとれると。計画の案から支給決定、計画の案が外れるところは、３ステップ、何週間、何カ月ぐらい今かかっていますか。","respondent":"中山障害者福祉課長","answer":"実際に、要するに介護給付をお出しするときというのは医師の判定も必要なので、医師の診断書もいただくことを考えると、最低でも１カ月ぐらいはかかると思っています。","voiceIndex":109,"id":"exchange-041"},{"speaker":"若林委員","kind":"質問・要望","question":"引き続き、もう１点聞きたいのが、個別の問題になりますけれども、ケアマネジメント、８０項目の調査というところで、同行援護だけ、スポットを当てて、毎年、いわゆる視覚に障害のある方から、団体としても、個別に、どうしても時間的に、ちゃんと今こういうルールにのっとってやっていらっしゃるのだけれども、どうしても少ない、それから、これは認めてくれない。","respondent":"中山障害者福祉課長","answer":"そのところについては、相談支援センターとも話をしながら、実際に１級、２級という級だけではない、特に見え方の違いというのはありますので、そうしたところは共通理解を持つようにしておりますし、あとやはり個別性のところに着目をすることになるので。","voiceIndex":111,"id":"exchange-042"},{"speaker":"若林委員","kind":"質問・要望","question":"ただ、どうしてもそういう声が絶えないというのか、例えば同じ人からとか、同じような傾向性だとか、これはお互いに相談ごと、支給決定なので、決まりは決まりがあって、それをお伝えしながら、また当事者の方も自分の生活状況をお伝えしながらというやりとりをやっていらっしゃると思うのですけれども、最終的にどこかで、そうですよね、要望が１００％通る、全部頂戴、わかりましたといったら。","respondent":"中山障害者福祉課長","answer":"同行援護の研修なんかも行っているのですけれども、区内で同行援護の事業者がすごくたくさんあるというわけでもないので、一方でそういう社会資源としての同行援護者も増やしながら、社会参加というのはすごく大事なことだと考えていますので、お声を大事にしながら。","voiceIndex":113,"id":"exchange-043"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"利用されている人の数ではないですよね。すみません、区外を利用されている方の人数もわかれば、それぞれ教えていただきたいのですが、就労継続支援のＢ型だったりグループホームなんかは、２３区で見てもやはり整備率が少ないと思うので、そういったところでは、区内で生活し続けたいけどなかなかできないという状況もあると思うのですけれども、区外利用者の部分を伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"就労継続支援Ｂ型ですけれども、例えば遠くのグループホームに行かれていて、そこの近所のＢ型を使われている方とかもいらっしゃるので、区内にお住まいになっていて、なおかつ近隣の区外の就労継続支援Ｂ型を使われている方というのが、現在。","voiceIndex":115,"id":"exchange-044"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"そういったところでは、荏原地域でもっと増えれば、さらに増えるし、ほかの地域でもいいのですけれども、以前、課長から各地域に点在させて利用しやすい、小さな規模でも点在させていきたいというお話もあったので、ぜひさらに品川で住み続けていく、生活していく、地域でしていくということを進めるためにも、ここを増やしていくべきだと私も思うのですが、増設を進めていくというところでは、この間。","respondent":"中山障害者福祉課長","answer":"ただ、実際の公共施設の活用というところになると、障害者施策だけではなくて、区の行政課題全体を見て、やっぱり優先順位とかがあると思いますので、そうした中で決まっていくのかなと考えていますので、私は私の立場で、事業者側と話をしながら。","voiceIndex":117,"id":"exchange-045"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"それと、荏原東と西と地域を分けてあるのですけれども、すみません、私、あまり地域割りというのを、品川、大崎、大井・八潮とか荏原というふうにはあったけれども、東と西で分けるという見方というのは、今までも障害者福祉のところではしていたものなのでしょうか。","respondent":"中山障害者福祉課長","answer":"荏原東、西というのは、より地域に点在したほうがいいだろうということで、荏原の地域も広いので、戸越・中延のほうと、あと旗の台・小山のほうと分けて考えてみればいいのかなという形で、今回このようにさせていただいています。","voiceIndex":119,"id":"exchange-046"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"一番初めの基幹相談支援センターのところなのですけれども、先ほど専門的なところを求められてということで、人数が１２人と言われたのですが、１２人の方の資格を教えていただきたいのと、それから障害児の相談支援というのは、今、品川区の中でやっているのですけれども、それはこの１２人とはまた別に、専門で相談支援をやる職員がいるのかということをお聞きしたいのですが、それであれば。","respondent":"中山障害者福祉課長","answer":"先ほど基幹相談支援センター、１２人と申しましたのは、相談系の係全員の人数になります。この人数で基幹相談支援センターの業務だけをやっているわけではなく、福祉事務所であったり品川区としての役割も担っています。","voiceIndex":122,"id":"exchange-047"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、障害児の相談支援事業は、非常勤の心理の方が１人だけでやっているというところなのでしょうか。障害児の相談支援事業の体制、資格と人数を教えてください。","respondent":"中山障害者福祉課長","answer":"これも障害児の相談支援だけをやっているわけではないです。専任でやっているのは先ほどの心理の非常勤ですが、ほかに療育支援担当というのがおりまして、社会福祉士と保育士の資格を持つ職員２人、合計３人で、現在、児の相談支援のところを担っております。","voiceIndex":124,"id":"exchange-048"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3496#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":48655,"voices":133}},{"id":"h30-20180122-8","meetingId":"h30-cm01","date":"2018年1月22日","dateIso":"2018-01-22","committee":"建設委員会","time":"午後 １時００分～午後 ３時３７分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を66件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２９年陳情第１５号、東五反田一丁目全域を放置自転車禁止区域に指定することを求める陳情","agenda":"平成２９年陳情第１５号、東五反田一丁目全域を放置自転車禁止区域に指定することを求める陳情","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"地元町会の役員の方とも話したこともあるそうですけれども、昔はもっと禁止区域が狭かったのですが、それを一定広げてもらったけれども、今度は禁止区域の境目で放置自転車が増えてしまったという話も伺ったそうで、１から１０番地、１０番の地区は今指定されていないところですけれども、これは放置の実態は現状では余りないそうなのですが。","respondent":"桑波田交通安全担当課長","answer":"外れた場所につきましては、皆さまの要望等、電話や区民の声等いただいておりますので、そういったところへ個別に区の職員が行きまして警告文を貼りつけて撤去するような対応をとっているところです。","voiceIndex":11,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"わかりました。大体禁止区域の撤去の頻度というのですか、どれくらいなのかというのと、それとあと区域外のところのそういった対応というのをどれぐらいの頻度で行っていらっしゃるのか。これ仮に１丁目全域指定された場合というのは、駅に至近とは言えない住宅地でも撤去対象になると思うのですけれども、そのことでどのような影響が出るのか伺いたいと思います。","respondent":"桑波田交通安全担当課長","answer":"それ以外の区域につきましては、それぞれ陳情を受けまして、対応としましては１月から１２月までで５４６件の陳情を受けまして、５１６台の撤去を実施しているという状況です。","voiceIndex":13,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"わかりました。ちょっと幾つかお伺いしたいのですけれども、現状の台数というのは先ほど伺ったのですが、難しいという話はありますけれども、放置されていた２０台の自転車というのは、通勤者なのか居住者のものなのか、全然わからないのですか。大体感触としてどのような種類のものなのか、捉えていらっしゃればお話していただきたいと思います。２つ目です。それをお伺いします。","respondent":"桑波田交通安全担当課長","answer":"やはり区のほうも動態調査等をしまして、日曜日とか平日ではない日も見たりしましたけれども、そのときでも置いてあるような自転車もありましたので、やはりそこで働いている方ですとかそういった方も考えられますので。","voiceIndex":17,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後２点なのですが、禁止区域を拡大してきたということですが、大体いつぐらいにどういう経緯で拡大してきたというのがわかれば教えていただきたいのが１つと、あと周辺の駐輪場の数という点で条例の紹介とかもありましたけれども、充足しているのでしょうか。伺いたいと思います。","respondent":"桑波田交通安全担当課長","answer":"駐輪場周辺の状況ですけれども、区営の駐輪場につきましては４８６台の駐輪スペースがありまして、あと民営が７７台ほど実施しております。","voiceIndex":19,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"わかりました。駐輪場のところはやはり足りていないということですので、区もそうですが、ＪＲという大きな公共的な企業もあるので、しかもＪＲを使う方がかなり利用されているということがありますので、そういった民間への附置も含めて増設をぜひ進めていただきたいなと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"ご説明ありがとうございました。現在放置自転車が三、四台というふうに減ったという状況をお伝えいただきましたが、ちょっと私も現地を見てみました。様子を伺いながら現地を見てみたところ、私の印象ではちょっとまだ自転車があるなという印象だったのです。放置禁止区域を広げてということですけれども、要はこの放置自転車をなくしてほしいということが一番のご要望なのだろうなと受けとめています。","respondent":"桑波田交通安全担当課長","answer":"この陳情書に記載のあります一丁目１８番付近、その周りも警告文などを貼りつけております。周りに残っているところは撤去忘れということだと思いますので、今朝また朝一番でそういった場所も見てもらって撤去を完了したということで実施しております。","voiceIndex":22,"id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"ありがとうございました。では、今区の駐輪場が赤で示されていますけれども、今後この地域で駐輪場が拡大をされるめどというのが何か検討されているところがあるのか。駅前には今ホテルが建設をされているということで、そういう動きもありますけれども、そこのホテルに対しての駐輪場の確保の要望ですとか、今後駐輪場がつくれるかどうかというところの見通しをお聞かせいただきたいと思います。","respondent":"桑波田交通安全担当課長","answer":"今工事中でありますけれども、東口のほうでアトレ等が、これは平成３２年の完成予定と聞いておりますが、こちらのほうで６１台使えるような駐輪場を設置するという方向で進んでいるところです。","voiceIndex":24,"id":"exchange-007"},{"speaker":"新妻委員","kind":"確認","question":"わかりました。最後に、やはりちょっとまだ残っているという印象がありました。今朝も撤去をしていただいたということでしたけれども、例えば持ち主があらわれるというか、ちょっとそこに時間を見計らって行っていただいて、直接お話をしていただくというようなこともお願いができるのかどうか。そこまで区としてやっていただけるのかどうかというところを確認をしたいのですけれども、いかがでしょうか。","respondent":"桑波田交通安全担当課長","answer":"持ち主がいつ来るかわからないようなそういう状況がありますが、時間を変えながらそういったふうに添付していくような対策はとれるです。","voiceIndex":26,"id":"exchange-008"},{"speaker":"西本委員","kind":"確認","question":"ちょっと確認をさせてください。下手をすると、地下駐輪場とかというのも必要になってくる可能性もあるし、利便性も含めて考えると、やはり地域全体の中での位置づけというものをしっかりと提示をしていく中での議論を進めていかないと問題解決にならないのではないかなと思うのですが、その辺は何か動きがあれば教えてほしいのです。","respondent":"桑波田交通安全担当課長","answer":"夜営業しているようなところもありますし、そういった状況になっております。町会のほう、こちらも以前西口のほうと駐輪場の設置等も検討しましていろいろ話し合い等もあったのですが、なかなか折り合いがつかなくて駐輪場の設置までには至らなかったというような状況もあります。","voiceIndex":28,"id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"ただ、ではそこに何のために自転車があるのか。となると、どこまで責任を持ってもらうのですかという話です。駅もそうです。駅ですから駅を利用されているのだから、ＪＲ、都営も走っていますよね。区が一生懸命やってもそれは全然解決の糸口にはならなくて、そこは事業者も区も含めての協力体制を仰ぐということは必要になってくるのではないかと思うのですが、その辺の動きはいかがですか。","respondent":"桑波田交通安全担当課長","answer":"まちの方とこの問題に関してとりわけお話等、会議の場を持ったりしたところはないのですけれども、やはりこういった声が上がっているということであれば、商店街でありますとかまちの方、あといろいろ月に一遍なのですけれども、警察のほうと合同パトロール。","voiceIndex":30,"id":"exchange-010"},{"speaker":"大沢委員","kind":"質問","question":"今の続きなのですけれども、東五反田一丁目１８番付近ということなのですが、周辺の東五反田二丁目、大崎五丁目、西五反田ということで、ほかの地域における同種同様な立地条件のところというのは、こういうような苦情なり話は出ているのですか。","respondent":"桑波田交通安全担当課長","answer":"ほかの駅につきましてはこういった区域外の要望等がございましたら、やはり個別に対応させていただいているですが、駅周辺でということでやっているところは特に大きなところ、武蔵小山はそういった声はありますけれども、それ以外は特にございません。","voiceIndex":32,"id":"exchange-011"},{"speaker":"大沢委員","kind":"意見","question":"個別に対応ということで、この条例は、「公共の場所で」「区長は」ということで第１条に書いてありますけれども、地域の合意のもとでこういう駐輪対策あるいは禁止区域が定められるということで条例の趣旨がなっていると思うのですけれども、この場合陳情される方、ピンポイントで来ているわけですが、ここら辺の地域意思とこの方の意思というのは乖離があるのか、それとも地域の方たちの意思とこの方。","respondent":"桑波田交通安全担当課長","answer":"今までいただいた声の中では、やはり駅に直近に近いところ、通勤するのに自転車があって邪魔になる、車が通れない、こういった本当に近いところ、そういったところの声もありますし、そういったところを放置禁止区域に指定しておりますので。","voiceIndex":34,"id":"exchange-012"},{"speaker":"大沢委員","kind":"質問","question":"この資料の中の写真を見せていただくと、やはり今課長がおっしゃったように、支障がないように写真のほうからは推察できるのです。そうなると、この陳情者個人で、陳情ですから賛同者がいないということは、この方個人の意思のもとにこの陳情が出されてきている。それのゆえに地域意思ではないということですよね。それはどうなのでしょう。","respondent":"桑波田交通安全担当課長","answer":"この陳情者の方の住所、住んでいらっしゃるマンションの目の前の道路を言われている状況にあります。ですから、裏取りはしていないのですけれども、やはりそういった自分の目の前の景観に対する思いみたいなものもあるのではないかと推測されます。","voiceIndex":36,"id":"exchange-013"},{"speaker":"筒井委員","kind":"質問","question":"地域の指定なのですけれども、陳情者は一丁目全域と述べておりますけれども、番地ごとに部分的な範囲の拡大というのはできるのかということをまずお聞きします。","respondent":"桑波田交通安全担当課長","answer":"番地といいますか通りですとか道路に関して指定をかけしています。どっちにしろ番地と絡んできますので、番地等で指定してきた、全域ではなく個別でも指定してきた経緯はあります。","voiceIndex":38,"id":"exchange-014"},{"speaker":"筒井委員","kind":"質問","question":"陳情者は、「通勤・通学のために日常的に使っており」というふうに述べておりますけれども、今課長からご答弁あったとおり飲食店や郵便局を利用される方もいらっしゃるということなのですが、割合というのは大体どの程度把握がされているのでしょうか。","respondent":"桑波田交通安全担当課長","answer":"さらに残っている部分は、そこまで調査はしておりませんけれども、やはり近隣でお住まいの方ですとかお店の利用者、こういったものが残っているような状況にあると考えております。","voiceIndex":40,"id":"exchange-015"},{"speaker":"筒井委員","kind":"質問","question":"となると、残っている放置自転車、つまり飲食店と郵便局で利用されている方だと思われるのですが、時間的にはやはり放置する時間というのは短いというふうには区としては理解されているのですか。","respondent":"桑波田交通安全担当課長","answer":"やはりお昼の時間帯に食事をしている方が駐輪している場合もありますし、また朝から夕方になっても置いてある場合もそれぞれあります。短い時間のものもありますし、長い時間夕方までとめているような状況の自転車もあるです。","voiceIndex":42,"id":"exchange-016"},{"speaker":"筒井委員","kind":"質問・要望","question":"なかなか区としては放置禁止区域の指定というのが難しいというようにお考えかなと思うのですけれども、ただ、やはり放置されているという事実はありますし、また景観上の問題というのもかなり大きいと思いますので、引き続き飲食店のオーナーの方とか郵便局の方とかにもご協力いただいて、適宜適切なご協力というのを引き続きお願いをぜひやっていただきたいと考えております。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-017"},{"speaker":"いながわ副委員長","kind":"意見","question":"今あちらこちらで再開発もあり、いろいろ住宅も建ち、指定されたときの背景とは全く、もちろんそこに自転車がどれぐらい放置されているかされてないかという議論もあろうかと思いますけれども、今回五反田の陳情なのですけれども、一回放置禁止区域というのを全体を見直していかないと、おそらく大崎も大きく変わっている、大井町もこれから大きく。","respondent":"桑波田交通安全担当課長","answer":"駅によっていろいろなつくりも違いますし、通りもあったり建物に囲まれているようなところもありますので、それぞれによって違うところもあるのですけれども、やはりまちの環境の変化ですとかそういった開発等によって環境が変わってくるのであれば。","voiceIndex":45,"id":"exchange-018"},{"speaker":"いながわ副委員長","kind":"質問","question":"こんな道路のこの交差点から先が、ではこのぎりぎりのところに置いておいた自転車はどうなってしまうのですかという話もあれば、もっと言うのだったら、東五反田一丁目の次の横の丁目との間はどうするのだという話にもなってくるので、そこはしっかり調査をかけて、今回は先ほど来お話がありましたけれども、こういう陳情が上がってきたからその場所で調査をして、あ、自転車が置いてありますね。","respondent":"桑波田交通安全担当課長","answer":"放置禁止区域について、一部の地域だけを指定した場合、今お話のあったとおり、またその隣に置いてしまう、放置禁止区域から外れたところに、外へ外へとまた逃げていくような状況もありますので、やはりそういったところも勘案しながら。","voiceIndex":47,"id":"exchange-019"},{"speaker":"安藤委員","kind":"意見","question":"まちづくり全体の中でというほかの委員からの話もありまして、そういったこともありますので、継続が望ましいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":52,"id":"exchange-020"},{"speaker":"西本委員","kind":"意見","question":"継続ですが、先ほども申し上げたように、ここだけではないと思うのです。同じような問題、品川区全体にかかわっている問題なので、もう少し広げてしっかり議論する場も必要なのかなと非常に感じましたので、継続的に議論してまいりたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":54,"id":"exchange-021"},{"speaker":"筒井委員","kind":"質問・要望","question":"区としてもぜひとも再調査をしていただきたいのと、あとまたここの地域の状況を見守りたいということで、継続でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-022"}]},{"id":"topic-02","title":"平成３０年２月都営住宅入居者募集","agenda":"平成３０年２月都営住宅入居者募集","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"毎月募集ということでお話がありましたが、毎月募集実施の目的や背景をどのように区としては把握していらっしゃるのでしょうか、伺いたいと思います。それと、毎月募集がこれからあるということになると思うのですが、区民への周知という点ではどのようになされるのかお伺いします。","respondent":"長尾住宅課長","answer":"毎月募集の趣旨についてですが、東京都から聞いているところですと、子育て世帯の入居機会を多様化するというところを主眼として、こちらの毎月募集を開始したと伺っております。","voiceIndex":60,"id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"周知に関してはなるべく多様な機会を捉えて区としても周知に努めていただきたいという要望です。それと内容について幾つか伺いたいのですけれども、今回の募集に品川区の住宅が入っているのか教えてください。それとなぜ比較的低倍率の住戸が募集の対象なのでしょうか。これも伺います。若者単身者が募集から除かれているという理由はなぜなのでしょうか、お伺いします。","respondent":"長尾住宅課長","answer":"ただ、東京都から聞いている話ではないのですが、今までの募集の状況を見てみますと、定期募集につきましては一般的な都営住宅に比べると倍率が低かった部分がありましたので。募集されている住戸につきましても、２人以上の世帯向けという住戸しか掲載はされておりませんでした。","voiceIndex":62,"id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"比較的低倍率の住戸がなぜ募集対象なのか。ひいては、自立や世帯の形成や少子化克服、社会の持続可能性を担保するということのためにも、そういった状況を改善していく必要があるのではないかということで、単身若者への住宅政策も考える必要があると思うのですけれども、ちょっと関連して区の見解をお伺いしたいというのが２点目です。","respondent":"長尾住宅課長","answer":"民間の住宅の中にもワンルームマンションは一定程度、単身者用の住宅というのもありますので、そちらのほうを使っていただくという形になると考えております。","voiceIndex":65,"id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"私が伺ったのは、高齢者であれば単身の方でも都営住宅に応募できますけれども、若者ですと単身ですと全く一切ないのですが、先ほど言ったような状況の中で、若者の単身者への住宅政策を考える必要があると思うのですけれどもいかがでしょうかと伺ったので、区の考えをお聞かせいただきたい。","respondent":"長尾住宅課長","answer":"若者単身者向けというところですけれども、現時点の都営住宅の制度の中では確かにございません。民間の住宅ストックとしては一方で一定程度あると考えておりますので、そちらを活用いただくというところがまずは前提になるかと思います。","voiceIndex":67,"id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういった認識をぜひ今後ちょっと持っていただきたいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-027"},{"speaker":"西本委員","kind":"質問","question":"すみません、この毎月募集ということに関して、区ではないので東京都の事業ですから答えにくいかとは思うのですけれども、ご存知でしたら教えてほしいのですが。ということは、最低でも５０はあいていますよという話ではないですか。しかも５０戸というのも出ているので、ということは既にあいていますよと。多分そこら辺はどういうからくりになっているのかなと思うのですが、いかがでしょうか。","respondent":"長尾住宅課長","answer":"都営住宅の公募の中に入ってくるものとしては、現状であいているものだけではなくあきの見込みというものも含まれているようですので、今までの都営住宅の運営上このぐらいはあくだろうという見込みも立てながら都営住宅としては公募をかけているのだと推測されます。","voiceIndex":70,"id":"exchange-028"},{"speaker":"西本委員","kind":"質問","question":"ただ、結局見込みで多分５０戸必ず、５０世帯入れますよということなのか、順番待ちで優先順位を待ちながらも５０戸の枠があるのです。だけれども、入れるのはもしかしたら４月になるかもしれないし、６月になるかもしれないしというような。だから、とにかく５０戸の中に入れば何とか１年の間に入れるかもねという程度で、まちの方に聞かれたら話をすればいいのか、その辺のニュアンスはいかがですか。","respondent":"長尾住宅課長","answer":"こちらにつきましては、抽選で当選された方はエントリーをしておいていただくことになりまして、当たった、当選された住戸が使えるような、ご案内できるような段階になれば、住宅供給公社から申請者へご連絡が行くということになりますので。","voiceIndex":72,"id":"exchange-029"}]},{"id":"topic-03","title":"（仮）品川区環境基本計画の素案について（パブリックコメントの実施）","agenda":"（仮）品川区環境基本計画の素案について（パブリックコメントの実施）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"ですから、２０１３年を基準にするというのは私はちょっとどうなのかなという思いがあるのです。基準年について都と国に合わせたというのがありましたけれども、環境基本計画の基本方針のところで、「地球温暖化対策の推進に関する法律に基づき」とありますが、これは２０１３年を基準にすると法律に書いてあることなのでしょうか。伺いたいと思います。率直に伺いたいと思います。","respondent":"小林環境課長","answer":"パリ協定につきましては、もちろんパリ協定を日本も批准しておりますので、もちろん国と区がそれに向かって取り組んでいかなければいけないということは十分に承知していますので。","voiceIndex":78,"id":"exchange-030"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり基準が示されているということですけれども、ぜひ自治体としての積極性も発揮していただいて、２０１３年にこだわらずもっと、例えば京都議定書の場合は９０年比なわけですから、積極的な目標を掲げていただきたいと思いますが、例えば基準年についても品川区は２０１３年以前に設定するとか、そういったことをやるべきだと思いますがいかがでしょうか。","respondent":"小林環境課長","answer":"他の自治体との比較等々も見ながら計画の進捗を確認していきたいということもありますので、２０１３年比というところについては変わりないと考えているところです。","voiceIndex":80,"id":"exchange-031"},{"speaker":"安藤委員","kind":"質問","question":"冊子のほうの１７ページとかに書いていますね。そういった意味で、今のご説明ですとちょっとわからないところもあるのですが、結局ではこの業務部門の目標値というのは絶対量を減らしていくということでよろしいですよね。そういった予測というのは立てていらっしゃるのか伺いたいと思います。","respondent":"小林環境課長","answer":"中小の建物につきましては、今回重点プロジェクトでもお示ししましたとおり、重点プロジェクト１ですが、特に中小事業者向けの例えば省エネ診断等々を実施した上で対策をとっていただくような仕組みづくりを今後環境課としても検討していきたいと考えておりまして。","voiceIndex":82,"id":"exchange-032"},{"speaker":"安藤委員","kind":"質問","question":"全体量を減らしていきたいということで、それはぜひ。ここら辺がちょっと私は非常に疑問なのでお伺いしました。減らす目標を掲げるのはいいのですが、それを担保するためのそういった計測、再開発ビルから排出されるＣＯ２の算出、そして公表する仕組み、総排出量を抑える計画というのはやはり私は大きな部門であるからこそ独自に必要だと思うのですけれども、いかがでしょうか。","respondent":"小林環境課長","answer":"先ほど申し上げましたとおり、一定規模の建物につきましては、省エネ法の中でしっかりと報告義務がなされているところですので、区として新たに何か監視していく必要があるかというところにつきましては、現在のところ考えているところではございません。","voiceIndex":84,"id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"それとあわせまして、同時にやはり自然エネルギーの普及というのがかなり決定的だと思いますけれども、昨今、ちょっとこの重点プロジェクトですとかあるいは基本目標のところでやはり位置づけが非常に弱いのではないかと思うのですが、やはりしっかり目標を持ってこれを普及していくというところを柱に、重点プロジェクトなのか、基本目標に入れるのか。","respondent":"小林環境課長","answer":"続きまして、自然エネルギーですが、先ほどご説明しましたとおり、重点プロジェクトの中でも例えば１１１ページの中の例２にありますように、そういったところで自然エネルギーについての活用事例等々も今回打ち出したところです。","voiceIndex":86,"id":"exchange-034"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは意見です。今関心がないかというとすごく高い面だと思いますので、そういった意味で、説明会をやることでこの計画自体を周知することにもなると思うのです。議論を巻き起こすことにもなると思いますので、ぜひ積極的にこれはパブコメとあわせて説明会の設定などをやっていただきたいと思いますが、これも要望にします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"幾つかお願いいたします。温室効果ガス削減目標なのですが、２０１３年を基準にということで、今２０１７年度はどこまで来ているのでしょうかというのを教えてください。そこのマークがありますよね。このマークがバッテン印に見えるのは私だけでしょうか。もうちょっとかわいいというか何というのでしょうか……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-036"},{"speaker":"西本委員","kind":"質問・要望","question":"環境対策をやるときに、本当の自分の身になって、一番わかりやすいのは先ほども言ったように電気代がこれだけ安くなるよとかというのがわかってくると、あ、これをやることによって最終的に省エネになる、使用削減になるというふうに身近に感じられるようなＰＤＣＡサイクルというのが提示できないものなのかなというのを、今後の課題なのかもしれませんけれども。","respondent":"小林環境課長","answer":"大きく４つご質問いただいたところです。削減目標のところで２０１７年の状況ですが、品川区の温室効果ガスの排出量が特別区協議会、こちらから毎年データ供給されるものです。家庭に対して助成等を行っているところですが、１つは１１９ページにありますように照明器具をＬＥＤに交換するようなことをまず行動指針としてお示しした上で。","voiceIndex":90,"id":"exchange-037"},{"speaker":"西本委員","kind":"質問・要望","question":"ちなみに、初めの２０１５年度ということで削減傾向はどのぐらい削減されているかという数字がわかったら教えてください。もうちょっと工夫していただきたいなと思いますので、これは要望としてお願いしたいと思います。ちょっと数字がわかれば教えてください。２０１５年。","respondent":"小林環境課長","answer":"ここの中で平成７年から平成２６年までの推移をお示ししている部分ですが、２０１５年でいきますと平成２６年になろうかと思うのですが、この段階で２,２３２という数字がありますので、徐々に減少傾向にあるというふうに考えられるところかと考えております。","voiceIndex":93,"id":"exchange-038"},{"speaker":"西本委員","kind":"質問","question":"確かに平成２６年は下がっていますけれども、２２年からがーんと上がって、２４年、２５年まで上がっているのです、傾向的には。ここら辺の分析はされているのでしょうか。本当に数字として示すことが可能なのですか。多分環境が大分変っているのだと思います。それの全体の品川区の状況、エネルギーの必要性等を含めて考察はどこまで進んでいますかということが非常に気になるのですが、いかがですか。","respondent":"小林環境課長","answer":"品川区内でいきますと、先ほど説明がありましたように、新しい建物がどんどん更新されていくことによって、やはり特に使用量という観点からいきますと削減傾向にあるのはやはりありますので。","voiceIndex":95,"id":"exchange-039"},{"speaker":"西本委員","kind":"質問","question":"ちょっとまだ少し納得いっていないのですけれども、目標数値というのはもうきっちりとされているのですよね。それで区民の目標数値というのもきっちり出されているのです。今のお話だけだと、ちょっとこれ本当に４０％ってやるのって、そこまで見通しが立てられたような計画になっているのですかとちょっと不安になってしまうのですが、その辺見直しとか今後の検討とかどういうふうにされていくのでしょうか。","respondent":"小林環境課長","answer":"４０％の設定ですが、１つは品川区だけでもちろん取り組むことではなく、国や都、区がそれぞれ連携し合いながらそれぞれの施策を進めていくことが一番重要かと考えています。","voiceIndex":97,"id":"exchange-040"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、１６、１７ページのような状況だけではだめで、もちろん人口推移なんかも絶対に必要になってくると思うのです。世帯数がどうなっていくとかというのも出てくるだろうし、本当にいろいろなファクターを含めながらの何％となってくるので、もしかしたら４０％行ってしまうかもしれないのですかね、そういういろいろな要素を見ながら考えていくと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-041"},{"speaker":"筒井委員","kind":"質問・要望","question":"そしてこの計画では反映されないのかということをまず一点お聞きをいたします。計画でどのように記述されていくのかということをお聞きします。これが２点目。最後３点目なのですけれども、３６ページの生活環境のところで、大気汚染とか水質汚濁については過去のデータが載っておりますけれども、騒音については過去のデータは載せられないのでしょうか。以上、大きく３点お聞きします。","respondent":"小林環境課長","answer":"騒音につきましては、一応環境課のほうでも年に１回道路からの騒音、車が発生する音に関しての測定については行っているところですが、これにつきましては一定同じ場所で測定しているというところではございませんで。","voiceIndex":100,"id":"exchange-042"},{"speaker":"筒井委員","kind":"質問・要望","question":"学びと体験の機会において区から区民に対しては啓発活動を行っていくということなのですけれども、やはりセミナーとかわざわざ行かれない区民というのもかなり多数いらっしゃると思いますので、広報紙とかで積極的、定期的に啓発というのを打っていかないと、なかなか区民の環境に対する意識というのは高まらないのかなと思いますので、広報しながわでの広報を積極的にお願いしたいのですけれども。","respondent":"小林環境課長","answer":"１１７ページの重点プロジェクトに記載させていただきましたが、例えばアプリを活用した情報発信の活性化というのも今後検討を進めていきたいと考えておりまして、それらを使って、例えばセミナーに行けなかった方に対する受け皿等々を進めていければと考えているところです。","voiceIndex":102,"id":"exchange-043"}]},{"id":"topic-04","title":"環境表彰式・環境講演会","agenda":"環境表彰式・環境講演会","exchanges":[{"speaker":"西本委員","kind":"質問","question":"環境表彰式ということで、いろいろ受賞された方がいらっしゃるのですが、副賞が何かあるのでしょうか。何かいただけるのですかということですが、それをちょっと教えてください。そことの協力体制も組めるのではないかと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-044"},{"speaker":"西本委員","kind":"質問・要望","question":"ちょっとそこら辺を、具体的にできているものがあれば教えていただきたいなと思いますが、いかがでしょうか。","respondent":"小林環境課長","answer":"表彰式の副賞ですが、当日受賞された方につきましてはトロフィーの贈呈があるです。それと、フードドライブの件ですが、お話がございましたとおり、基本的には区内で集めたものを区内でやはり消費するのが一番きれいな形かと我々も認識しているところがあります。","voiceIndex":110,"id":"exchange-045"},{"speaker":"西本委員","kind":"質問・要望","question":"トロフィーということなのですが、トロフィーですか。何かちょっと……。もうちょっとあってもいいかなと思いましたが。わかりました。これも子ども食堂の運営主体によってはいろいろと要望があるかと思うので、そこはうまく協力しながらやっていただきたいと考えていますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":112,"id":"exchange-046"},{"speaker":"新妻委員","kind":"質問・要望","question":"フードドライブについて、１点ちょっと教えていただきたいと思います。品川区で初めてのフードドライブが開催されるということで、私も食品ロス削減を推進しているひとりとしてはいい試みで、成功に導いていただきたいなと考えています。１つが周知です。","respondent":"小林環境課長","answer":"２点ございました。周知の件ですが、確かに現在は今回環境講演会をするという一貫の中でフードドライブという事業を行う関係もございまして、それをあわせて今周知をしています。","voiceIndex":113,"id":"exchange-047"},{"speaker":"いながわ副委員長","kind":"確認","question":"裏面の第二部の表彰の環境活動報告ということで、報告が東洋製罐、宮前フラワーズですとかある中で、長谷工コーポレーションというのは、これは管理組合を指しているのですか。どういうあれなのだろう。受賞してないですよね、長谷工コーポレーションは。確認だけ。","respondent":"溝口公園課長","answer":"今回、表面の資料をご覧いただきますと、長谷工コーポレーションなのですけれども、みどりの顕彰の中で緑化大賞を受賞したオーベルグランディオ品川勝島の施工業者として、緑化の取組みとして私どものほうで表彰しておりまして。","voiceIndex":115,"id":"exchange-048"},{"speaker":"いながわ副委員長","kind":"質問","question":"みどりの顕彰はこの３マンションを代表して長谷工さんという認識でいいわけですか。なぜ管理組合が、地域でも結構町会でも幅広く、五百何団体ある中で頑張っているところがあるけれども、管理組合がすごくあるというのは何か、管理組合というと多分ストックヤードがあって、そこに資源を分別して入れるというのは通常の流れのような気もしないでもないのですが、どうしてこんな管理組合が多いのか。","respondent":"工藤品川区清掃事務所長","answer":"その中で管理組合が４２８団体で登録されているというところがございまして、そういった構成比の部分でもかなり多くなってありますので、結果的にこのような形になったです。","voiceIndex":117,"id":"exchange-049"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"構成比は管理組合が多いのはわかるのですけれども、管理組合で集めるというのはストックヤードがあってやるやり方もあるし、何というんでしょう、地域で高齢者クラブがやっているとかというところでなかなか集める場所もないところで、本当にでも大切だからとやっている団体もあるということだけは忘れないで評価の対象にしていただきたい。当たり前のような気がするので、ストックヤードがあるわけですから。","respondent":"工藤品川区清掃事務所長","answer":"今お話ありましたように、そういった小さな団体でも継続して行われているとかそういった部分につきましては、当然この表彰の対象にも入れるような規定もありますので、そういったところもしっかり見ていきたいと考えています。","voiceIndex":119,"id":"exchange-050"},{"speaker":"大沢委員","kind":"質問・要望","question":"フードイベントをやるわけですけれども、ここのところでやはり不特定多数から集めるというので、何かこれをやる中で事故が起こるとも限らない。危機管理上の何か今指針というか、そういうものが区のほうで対策を立てているのであれば、お答えいただきたい。","respondent":"小林環境課長","answer":"フードドライブに対しての安全性ですが、まず集めるときにお名前と住所等個人情報は基本的には伺う予定で今進めております。集める場所につきましても必ず職員を配置した上で誰もいないということがないような対策をしっかりとっていくというところで今考えているところです。","voiceIndex":121,"id":"exchange-051"},{"speaker":"大沢委員","kind":"確認","question":"中身の問題ですけれども、必ずしも中身の安全性が、外見ですから確認できるわけではないのですけれども、万が一食に関して事故が起きた場合、これは責任の所在はどこがどう負っていくのか、提供者が出すのかあるいは区が一歩入っているので区が負うのか、そこら辺の指針、方向性がありましたら教えてください。","respondent":"小林環境課長","answer":"もちろんそこの中で穴が開いているとか検視をした上で、小さな穴があいている、そういったものにつきましては、中身をしっかり見た上で全く問題がないものだけを基本的にはお届けするというところで考えているところです。","voiceIndex":123,"id":"exchange-052"},{"speaker":"大沢委員","kind":"質問","question":"缶は穴があかないのだけれども、これはどうですか。","respondent":"小林環境課長","answer":"缶についてですが、基本的には多分目視の調査になるかと思います。缶をある程度揺らした上で液体が垂れてこないか、そういったところもしっかりと見ていきたいと考えています。","voiceIndex":125,"id":"exchange-053"},{"speaker":"大沢委員","kind":"質問","question":"責任の所在についてはどのような方針を持っているのか教えてください。","respondent":"小林環境課長","answer":"責任についてですが、もちろんお渡しする上では責任については十分とるというか、しっかりと担保した上でお渡しするというふうに考えているところです。","voiceIndex":127,"id":"exchange-054"},{"speaker":"大沢委員","kind":"質問","question":"提供する方も善意で出すわけですから、これが何かあったときにこの事業に水を差す部分があるので、そこのところをやはり事業を行う主体である品川区が何らかのかかわり合いはもちろん持つでしょうけれども、そこのところをどのように考えているのですか。","respondent":"小林環境課長","answer":"今回集めたものにつきましては、まず社協を通じて子ども食堂にお渡しすることになりますので、まずは社協とその辺は調整した上で考えていければと考えております。は社協に届けるというのが区の役割だと思っているところです。","voiceIndex":129,"id":"exchange-055"},{"speaker":"大沢委員","kind":"質問・要望","question":"さまざま今いろいろな部分で善意が善意でなくなる場合もありますので、そこのところ、せっかく善意で皆さんが事業を行うわけですから、善意が善意で済むような形をとっていただきたいと思います。","respondent":"小林環境課長","answer":"１点、先ほどちょっと答弁漏れというかご説明の中で不足がございました。受賞者に対してトロフィーという話がございましたが、正確に言えば賞状とトロフィーと副賞が贈呈される。","voiceIndex":131,"id":"exchange-056"}]},{"id":"topic-05","title":"平成２９年度 区内一斉防災訓練および各地区総合防災訓練の実施結果等","agenda":"平成２９年度 区内一斉防災訓練および各地区総合防災訓練の実施結果等","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"例えば、このアンケートの中の課題というところでも、「町会の方だけでなく広く一般の若い人たちが参加できるよう工夫すべき」という意見や、あと、「いざというときに役に立つ訓練にしたいです」とか、「毎年同じなので多少内容を入れかえてほしい」などの意見が出て、そこに課題も一つ見えているのかなと思うのですけれども、先ほどこれらを来年の取組みに生かしていきたいという話もありましたが。","respondent":"古巻防災課長","answer":"それからもう一点、本部訓練のほうの課題ですけれども、こちらも一定一通りのことを進んでおりますけれども、やはり今年やったような２日目以降のことですとか、またマニュアルをつくったのだけれども検証が十分できていないところ。","voiceIndex":137,"id":"exchange-057"},{"speaker":"安藤委員","kind":"質問","question":"啓発等を進めていきたいということでしたけれども、やはりちょっともう少し若い方々、防災意識が決してないというわけではないと思うのですが、そういう人たちの気持ちやライフスタイルにかみ合った参加しやすい訓練というのですか、参加したくなるような訓練というのですか、そういったもう一工夫さらにレベルアップしていく必要があるのかなと思うのですけれども。","respondent":"古巻防災課長","answer":"若い方に対するアピールについては、今具体的にというとなかなか効果的な方法というのがまだ暗中模索なところ、試行錯誤なところがありますので、課題として認識は十分いたしておりますので、今後もこのあたり十分に研究してまいりたいと考えております。","voiceIndex":139,"id":"exchange-058"},{"speaker":"横山委員","kind":"質問","question":"区内一斉防災訓練の、今回土曜日ということで日付が設定されていました。個別の部分はちょっとわからないかと思うのですけれども、教えていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":141,"id":"exchange-059"},{"speaker":"西本委員","kind":"質問","question":"１点だけお願いします。大崎中学校の関連の中に、避難部屋割り当てシミュレーションと。これはどのようなものでしょうか。","respondent":"古巻防災課長","answer":"避難部屋割り当てシミュレーション、いわゆる避難所に充てる部屋の割り当てを実際の避難者に応じてやっているということで認識をしております。","voiceIndex":144,"id":"exchange-060"},{"speaker":"西本委員","kind":"質問・要望","question":"私、毎回要望しているものと似ているのかどうかわからないのですが、結局、発災時には避難所はいろいろな方がいらっしゃると思うのです。なので、そのときの部屋割りをどうしていくのか。その訓練と部屋割り等々、だから１日目、２日目というのは、やはりやり方が変わってくると思うのです、避難所のやり方、あり方も含めて。それをぜひ取り組んでいただきたいという思いがあるのですが、それはいかがですか。","respondent":"古巻防災課長","answer":"そういった考え方の周知啓発につきましても、避難所マニュアル等の充実でありますとかそういった中で十分進めていきたいと考えております。","voiceIndex":146,"id":"exchange-061"},{"speaker":"西本委員","kind":"質問・要望","question":"大崎中のこの件、ちょっと具体的に知りたいなというのがあるので、何か情報があったら教えてほしいのですが、今でなくて結構です。ぜひこのシミュレーションについては研究していただきたい。なので、そこの違いが皆さん誰でもできるようにしておかないと、避難所に対する、避難所訓練にはならないと思うので、そこをまず研究していただきたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":148,"id":"exchange-062"}]},{"id":"topic-06","title":"行政視察報告書","agenda":"行政視察報告書","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"これは周知の仕方はどうしているのか、このチラシですね、とあと実際全面改修はいつぐらいの時期を予定しているのかと２点お伺いします。","respondent":"多並道路課長","answer":"周囲の皆様にはビラを配る予定としております。今後の計画としましては、今年度概略設計しておりますので、来年度それを踏まえ詳細設計を行い、平成３１年度から段階的に工事を行っていく予定と現在では考えているところです。","voiceIndex":155,"id":"exchange-063"},{"speaker":"西本委員","kind":"質問・要望","question":"ここはちょっとした川みたいなものがあったりいろいろありました、あそこだと思うのですけれども、非常に子どもたちが遊んだりとかして暑い夏なんかは非常に涼んだりとかしているところなのです。なので、そういうのも全部入れて、いろいろ要望とかも入れて改築、整備という形の理解でよろしいですか。","respondent":"多並道路課長","answer":"委員のご指摘のとおり、そういうのも踏まえて概略設計ということで地元の皆さんにご説明をして、ご意見をお伺いしながら来年度それを踏まえて詳細設計ということで、時間をとりながら設計を行っているという趣旨です。","voiceIndex":157,"id":"exchange-064"},{"speaker":"新妻委員","kind":"質問・要望","question":"この品川区にかかわる部分で、例えばしながわ水族館の営業ですとか、あとそれ以外でも具体的な対応をされたところがありましたら教えていただきたいと思います。","respondent":"溝口公園課長","answer":"水族館については鳥類ということでペンギンを屋外で飼っておりますが、もう既に発表されたときにあわせてすぐ室内に入れるとともに、外部からの水も含めて遮断できるような飼育体制を整えているというところで対応済みという形で対応しているものです。","voiceIndex":165,"id":"exchange-065"},{"speaker":"新妻委員","kind":"質問","question":"品川区ではありませんけれども、東京都の野鳥の森公園が大井ふ頭中央海浜公園の先のほうですね、あると思うのですが、そこの対応はどうなっているのですか。","respondent":"小林環境課長","answer":"この１７日を受けまして、１８日に庁内会議を開催したところです。情報共有を行って、また何か死んだ鳥等を見つけた場合は速やかに環境課に連絡頂けるような周知活動を今行っているところです。","voiceIndex":167,"id":"exchange-066"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4222#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":48536,"voices":170}},{"id":"h30-20180122-9","meetingId":"h30-cm01","date":"2018年1月22日","dateIso":"2018-01-22","committee":"文教委員会","time":"午後 １時００分～午後 ４時０９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成３０年度新入学の学校選択希望申請理由調査結果","agenda":"平成３０年度新入学の学校選択希望申請理由調査結果","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"私は、小学校で生活する中で、魅力を感じなくなるというか、あまり小学校と変わらないというふうに感じてくるのかと考えているのですけれども、区の考えを伺いたいと思います。この棒グラフと円グラフの見方といいますか、別々で出している意味といいましょうか、そこを教えていただければと思います。","respondent":"有馬学務課長","answer":"そのことによって、例えばこの「学校の教育活動に魅力がある」というのが、全体でいくと約半数、５０.６％がこの項目に回答しているのだということで、円グラフではわからない部分がこれで浮き彫りになっているものというふうに捉えております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"グラフのほうからいきますと、全体の中での複数回答の割合ということで、円グラフだと見えにくくなるような気がするので伺ったのです。わかりました。そうすると、なかなか大変な状況だと思うのですけれども、この状況をどう捉えていらっしゃるのか、選択しても入学できないというような状況になっているわけですけれども、その辺のお考えを伺いたいと思います。","respondent":"有馬学務課長","answer":"確かに、１１月の抽選日の結果のところは、この枠の数字できちんと押さえてやっておりますので、かなりそういう数字が出ています。","voiceIndex":7,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"平成３０年度の抽選の結果からみて、昨年度よりどういった状況になっているのか、入れない子どもが増えそうか減りそうかということはわかりますでしょうか。","respondent":"有馬学務課長","answer":"昨年の小学校で言えば８５％が最終的に入れたところの数字を今年度どうなるか、そこは今、繰り上げを順次行っているところですので、まだこうなりますというような明確な回答はできかねますけれども、それに近づけるかどうかというのは見ていきたいと考えています。","voiceIndex":9,"id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"とりわけ去年の秋に学事制度審議会の中間のまとめが出て、そこで地域からはいろいろと選択制があるがために、町会の皆さんを中心に、いろいろなご意見を持っておられるということが、去年の学事制度審議会の議論の中でも出ていたのだなということを思ったのですけれども、そういう中で検討されて、やはり選択の規模を小学校のほうは小さくするというふうな結論が。","respondent":"有馬学務課長","answer":"３ページ目のアンケートの棒グラフの結果をどう捉えているかということですけれども、まず、「学校の教育活動に魅力がある」というのが一番で、「学校が近く通学しやすい」ということも両方加味しているということで、近くていい学校を探しているのではないかという。","voiceIndex":11,"id":"exchange-004"},{"speaker":"南委員","kind":"確認","question":"わかりました。２５％程度、選択されるのが３割ぐらいというふうに聞いていたけれども、それほど大きく違う数字ではないけれども、２５％から３０％程度が選択を希望されるという認識でいればいいということでいいのかどうか、そこを後で確認をしたいと思います。３割ぐらいかといつも思っていたので、改めて確認したいと思います。学校選択制をやめた自治体が幾つかありますね。","respondent":"大関教育総合支援センター長、有馬学務課長","answer":"前半にご質問いただいた、なぜ学校選択制を維持する必要があるのかという部分に対して、お答えしたいと思いますが、やはり教員が黙っていても。教室数の不足とか教室の確保に対応する部分ですけれども、就学人口の動態は、今、０歳から６歳という人口が、住基上わかりますので。","voiceIndex":13,"id":"exchange-005"},{"speaker":"南委員","kind":"質問","question":"私は、切磋琢磨という、その言葉は否定しないけれども、現場の実態と乖離し過ぎているのではないかと思うので、あまりここばかりやっていてもあれだから、最後に１点だけ、この切磋琢磨の教育委員会の思いと現場の思いがすごく大きくずれていると私は思うので、その辺をどういうふうに考えるかというところだけ伺って終わりにしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-006"},{"speaker":"松永委員","kind":"質問","question":"もし漏れた方からご意見等がありましたら、例えばもうちょっとこうして欲しいというようなご意見がありましたら、お聞きしたいのですけれども、いかがでしょうか。これは答えられる範囲でいいのですが、抽選の仕方はどのような形で行われるのか。例えば、くじ引きで当たりか、それとも番号を引いて、その番号が順位になっているのか、どのような形で第２位の方の抽選が行われているのかお伺いします。","respondent":"有馬学務課長","answer":"ただし、よくあるのが、出し忘れてしまって、翌週に希望申請を出された方がどうにかなりませんかみたいなお話は来るのですけれども、それはもうルールで、１０月いっぱい、消印有効の方を対象にしておりますので。","voiceIndex":19,"id":"exchange-007"},{"speaker":"松永委員","kind":"質問","question":"先ほど、教室の確保はできているということなのですが、例えば、家庭科室とか図書室とか、どういったところを普通教室に変えるなど工夫をされているのでしょうか。先ほど言っていた抽選漏れをされた方から何かご意見があったのかどうかお答えいただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-008"},{"speaker":"渡部委員","kind":"質問","question":"報告事項と関係ないことなのですが、発言を認めてもらえれば。教育委員会、子ども未来部の皆さん、天気が大雪になってきましたけれども、とらなければいけない対応は大丈夫ですか。","respondent":"大関教育総合支援センター長、高山子ども育成課長、佐藤保育課長","answer":"警報が出た場合には、すぐに休校、７時の段階で休校というルールも決まっておりますので、現時点ではルールどおり行う予定です。私どもは、児童センター、それからすまいるスクールを所管しておりますので、そちらの対応を報告します。公立保育園に関しましても、今、両課長から説明があったのですが、朝一番の段階で回覧で全保育園に必要な対応をするようにということをお伝えしております。","voiceIndex":25,"id":"exchange-009"},{"speaker":"こんの委員","kind":"質問","question":"学校選択制のほうですけれども、今後の学校運営に生かしていくということで、このアンケートを毎年されているということですが、１つは、このアンケートの内容は、毎年同じ内容なのでしょうか。もしくは、その年その年に応じて増やしている項目だとか、変えている項目があるのでしょうかというのが１つです。","respondent":"有馬学務課長","answer":"アンケートですけれども、学校選択制を始めたころ、平成１５年とか平成２０年ごろについては、保護者全員にアンケートをとっていたという時代もありましたけれども、平成２５年のときに兄弟枠を設けたり、変更したときに今の形に変えておりまして。","voiceIndex":32,"id":"exchange-010"},{"speaker":"こんの委員","kind":"質問","question":"3)番と8)番の設問は、これは魅力がある、ないのことなので、運営上、魅力があるとすれば、そうなのだなとなるのでしょうけれども、個別具体的な設問はなかなか難しいかもしれませんが、学校運営に生かしていくという観点でいくと、設問をもう少し学校運営、いわゆる選んでもらえる学校運営が主目的の選択制であるならば、そうした設問が必要なのではないかと思うのですが。","respondent":"有馬学務課長","answer":"実際にどういう活動なのかというところを内部でも、ここは少し曖昧とは言いませんけれども、もう少し細かく見る必要もあるということを検討はしているのですけれども、いろいろな魅力を感じているところがあるでしょうから、それを列挙してしまうのがいいのか。","voiceIndex":34,"id":"exchange-011"},{"speaker":"こんの委員","kind":"質問","question":"今、課長がおっしゃったとおりだと思います。ですが、平成２５年から変わらずそのままの状態を見て運営に毎年生かしていくというよりも、少しずつその中の項目として、５年に１回なのか、３年に１回なのか、項目を変えてみるとかしながら、運営に生かせる評価の部分という項目をつけるというのも１つあるのかなと思いましたので、お聞きしてみました。","respondent":"有馬学務課長","answer":"それは学校がいろいろＰＲをされて、平成２７年ぐらいから上位１位を占めるようになったというようなことですので、１つはそういう傾向が今は出ていることから、あえて今は項目を変えずに継続しているという状況があります。","voiceIndex":36,"id":"exchange-012"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"先日も活躍した部活の話を伺いましたけれども、そうすると、顧問の先生の問題が出てくると思うので、これは東京都が人事をやると思うのですが、学校の特色で部活やさまざまな芸術活動などをやられているところの顧問や、指導されている先生の継続といいますか、異動しないという意味ではなくて、見られるような方の配置をぜひ東京都のほうに強く要望していただけると。","respondent":"品川庶務課長、大関教育総合支援センター長、有馬学務課長","answer":"和式トイレだと子どもたちは使えないというような事情もありますので、１年生から和式トイレの使い方等は説明をしているのですけれども。あわせまして、これまでも従来より品川の場合には合同部活動であったり。あるいは、すまいるスクールで使っていたところを１年生の教室にして。","voiceIndex":39,"id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"今のご質問の中で、私もさっき質問したときに、そこまでご答弁がなかったので、関連して伺いたいのですけれども、幾つかの学校名を挙げて教室の不足が見込まれるとか、多目的室を普通教室に変えたとか、そういうご答弁があったのですが、品川の小・中学校、中学校も別の意味であるのではないかと思うのですけれども、どこの学校がどういう状況にあるか。","respondent":"有馬学務課長、大関教育総合支援センター長","answer":"先ほどの浜川小学校の事例は本当に極端な場合であって、いざとなったらそういうふうな対応もしていくというようなことで、基本的には学区の子はしっかり受け入れるという責務があるので、そういったことも学校と協議しながら。新聞報道等でも出ておりますように、現在、週に２日、そして土日のどちらかはきちんと部活動の休みの日を設けようとか、あるいは。","voiceIndex":44,"id":"exchange-014"},{"speaker":"のだて委員","kind":"質問","question":"旗台小学校では学級閉鎖が相当多くなっているのですけれども、これは蔓延してしまったというか、感染をとめられなかったのかという感じがするのですが、もうおさまったと考えていいのかということと、どういった対応をされてきたのか伺いたいと思います。保育園のほうも昨年から４倍になったというところで、この原因についてはどう考えていらっしゃるか伺いたいと思います。","respondent":"有馬学務課長、佐藤保育課長","answer":"旗台小学校ですけれども、１２月５日、３年１組で、その後、１日おきに、２年生、３年生と広がり、その後も、翌週ですけれども６年生までということで、改めてインフルエンザの感染性の強さというか。保育園の実績数が昨年の４倍です。保育園でのインフルエンザの流行傾向は、１２月、１月、２月という３カ月ぐらいに分かれて行われておりますが、一定、１２月にピークが来たというふうにはある程度見込んでおるところです。","voiceIndex":53,"id":"exchange-015"},{"speaker":"鈴木（博）副委員長","kind":"確認","question":"１２月に１回流行ったのですけれども、年末年始で集団保育は停止するので、一時、流行が衰えるのですが、本格的に流行り出しているのが先週ぐらいからで、今週と来週ぐらいが多分ピークになります。今、保育園によっては、インフルエンザの検査をして陰性なのを確認してから子どもを寄こしてくださいとかと指導しているところが、私立の保育園である。ということで、一言いかがですか。","respondent":"有馬学務課長、佐藤保育課長","answer":"兄弟のところは大変気にはなっていたのですけれども、今のご意見を参考に、胸を張って学校にも、きちんとした対応さえとれば発症することはやむを得ないという部分も理解できましたし、兄弟の部分もわかりましたので。委員ご指摘の趣旨を踏まえまして、区で定めている保健マニュアル等も適切な状態にして、各園に周知を努めてまいります。よろしくお願いします。","voiceIndex":56,"id":"exchange-016"},{"speaker":"鈴木（博）副委員長","kind":"質問","question":"一言だけ。新型インフルエンザの流行のときに、インフルエンザは２ｍ以上離れれば移らないというマニュアルが出ているので、２ｍ以内で咳とか鼻とかを浴びた場合に移るので、基本的に感染予防に関しては、マスクをすることと、手洗いすることと、あと２ｍ以内にできるだけ近づけないということに関してご指導をしっかりお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-017"},{"speaker":"高橋（し）委員","kind":"質問","question":"今、学校と保育園の話だったのですけれども、児童センターを利用されている保護者の方で、いろいろな小学校から児童センターに来るので、自分の子どもが通っている小学校ではまだ流行がないけれども、隣の小学校で流行っているのではないかとか、そういうことを知らないで、知ったから行かないという意味ではないのですけれども、そういう何々小学校で今、学級閉鎖がこうだというのは。","respondent":"有馬学務課長、高山子ども育成課長","answer":"もう１つ、教育総合支援センターも含めて、その３課には、毎日、その都度、情報提供をしているということで対応しております。基本的には、学級閉鎖があったクラスについては、すまいるスクールは禁止ということになっておりますので、そういった部分はしっかりと情報共有しています。","voiceIndex":61,"id":"exchange-018"},{"speaker":"高橋（し）委員","kind":"質問","question":"児童センターに遊びに行った小学生が、隣の小学校でこうなっているとか、そういうのがわかるのでしょうかということです。","respondent":"高山子ども育成課長","answer":"児童センターを利用する児童一人一人にそういう状況を伝えているかというと、そこまでの対応はとっておりませんが、館長としても、基本的に児童センターを利用するお子さんは結構固定化していますので、それぞれの学校においてインフルエンザが流行っているなどといったことは。","voiceIndex":64,"id":"exchange-019"},{"speaker":"高橋（し）委員","kind":"意見","question":"そういうことで、利用されている方や保護者の方に、具体的に何年何組が学級閉鎖というところは、いろいろ情報の面があるのかもしれませんが、今、学級閉鎖ですということは何らかの形で、掲示なり何なりして周知できる形がいいのではないかと思うのですが、検討をお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":66,"id":"exchange-020"},{"speaker":"こんの委員","kind":"質問・要望","question":"参考までにお伺いしたいと思います。先ほど、今年度は１９校３２学級が学級・学年閉鎖をしているという数字で、昨年に比べると増えているというところですが、近年では、やっぱり年によって増える、減る、こういう状況なのか、その傾向を教えていただきたいのと、それから学校もそうですし、幼稚園、保育園でもその辺の傾向はどのような状況なのか、まず教えてください。","respondent":"有馬学務課長、佐藤保育課長","answer":"今年も冬休みが明けてから、２週目に入って、今日も午前中、かなり電話を受けていますので、また今週、来週で増えるのかなというふうに見ているところです。保育園、幼稚園に関しまして、学務課長が答弁したとおり、昨年は一昨年よりも多かったというふうな認識です。今年度に関しましては、先ほどご答弁したとおり、保育園に関してはちょっと前倒し、幼稚園に関しては例年どおりの発生数です。","voiceIndex":68,"id":"exchange-021"},{"speaker":"こんの委員","kind":"質問","question":"先ほども予防についてのお話が副委員長のほうからもありましたけれども、こうしたうがい、手洗いの励行はさることながら、いわゆる予防接種との関係、蔓延しないようにするための予防接種との関係はどんなふうに学校としては捉えているか、予防接種をしているお子さんが何人かという把握などは、これは調査されていないと思うのですけれども。","respondent":"有馬学務課長、佐藤保育課長","answer":"インフルエンザの予防接種については、予防接種をどこでやるかというのは保健所の所管になると思うので、なかなか難しいところなのですけれども、基本的には、小学生のインフルエンザの予防接種は。保育園に関しましても予防接種は任意接種というところで、区として受けてくださいという話はしていないところですが、区といたしましては、早めの受診、マスク、手洗いの励行、あと。","voiceIndex":71,"id":"exchange-022"},{"speaker":"こんの委員","kind":"質問","question":"所管が違うので、ここで参考までの質問は終わりにしたいと思うのですが、やはり予防接種というのは大事なところなのかなと、今お話を聞いていて思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-023"}]},{"id":"topic-02","title":"ぷりすくーる西五反田の今後","agenda":"ぷりすくーる西五反田の今後","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"認可保育園などぷりすくーる西五反田の現状から認定こども園に変わると、子どもや保護者への影響はどういったところが変わってくるのか伺いたいと思います。利用料などが変更になってくるとか、時間も変更になるのかということです。事業内訳の中で、地域子育て支援センターと書いてあります。こちらも継続されるのかということをお聞きしたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"ぷりすくーる西五反田は、設立当時より、保育から幼児教育まで一貫して対応していく理念のもとに進めてまいりました。これまでの取り組みについては、保護者より好評である旨の評価を得てきたところです。","voiceIndex":79,"id":"exchange-024"},{"speaker":"のだて委員","kind":"質問","question":"資料の下のところで、公私連携幼保連携型認定こども園の説明があるのですけれども、この中で区から必要な設備の貸付とか譲渡、いろいろ協力を得てやっていくというところが公私連携ということなのかと思っているのですが、今回の場合はどうなっていくのかということをお聞きしたいのですけれども、何を貸し付けて、何を譲渡するのかというところで、公私連携がどういうことになるのか伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"特に幼児教育部門は、ほぼ幼稚園に近い時間帯プラス前後預ける時間とか、そういうような形で分かれておりますので、認定こども園になったからといって、特にその辺が大きく変わるものとは認識しておりません。","voiceIndex":81,"id":"exchange-025"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、今の既に保育園と幼児教育部門とで生活リズムが違う中で問題点は特に出てきていないということでよろしいのでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"現場のほうから伺っている段階では、そのようなことで特に問題等は聞いておりません。","voiceIndex":83,"id":"exchange-026"},{"speaker":"南委員","kind":"確認","question":"今現在、公立の保育園のところで、当初３園だったのが４園、認定こども園になっているというふうに思っているのですけれども、先ほど、のだて委員から、幼稚園部門の子どもと保育園部門でのいろいろな生活の違いに関する質問があったのですが、幼稚園だから当然お昼過ぎ、一定の時間にお迎えに来る、そういうグループの子どもがいる一方で。","respondent":"吉田保育施設調整担当課長","answer":"公私連携のところですけれども、認定こども園法の第３４条に規定がありまして、公私連携型、自治体における保育の実施に対する需要の状況等に照らし適当であると認めるときは。","voiceIndex":85,"id":"exchange-027"},{"speaker":"南委員","kind":"質問・要望","question":"今のぷりすくーる西五反田の土地と建物との関係で、これから今度新しく設備される公私連携のこども園はどういうふうになっていくのかは、これからも詳しく検討していくということなのですけれども、大まかに今のところがどうなっているのかだけ最後に教えていただきたい。","respondent":"吉田保育施設調整担当課長、佐藤保育課長","answer":"現状のままではそのまま進めていけないところがありますので、必要な環境の整備が出てまいります。その辺を整備した後、認定こども園化を目指していくという形になります。平成３０年にその辺を検討してまいります。もう一方ではぷりすくーる西五反田はＮＰＯ法人がやっていますので、法人格がないというところで、今の形態の施設だと、この３つがあるということです。","voiceIndex":87,"id":"exchange-028"},{"speaker":"南委員","kind":"意見","question":"品川区で公私連携の今回やるところは、ぷりすくーるのそういう形を変えていくというところだから、それはわかるのですけれども、いろいろな種類があるということについての区の考え方はどうなのかを知りたいと思っています。","respondent":"佐藤保育課長","answer":"幼保一体施設というのは、品川区が国に先駆けて設置した施設で、一番古くて平成１４年からで、今、法改正の経過期間のところもありまして、この幼保一体施設に関しまして、対外的にも説明が認定こども園であったり、幼保一体施設であったり、わかりにくい部分がありますが。","voiceIndex":90,"id":"exchange-029"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今、ほかの委員の方がおっしゃっていたのですが、一体施設が何種類かあるということなのですけれども、今回、ぷりすくーるにおいて、公私連携幼保連携型が１つあって、今お話があったような既存のものがあって、さらに新しく、今、八潮の民営化するところも一体にするというところで、そちらはどこがというのは置いておいて、幼保一体というか、認定こども園に対して品川区ではこういう幼保。","respondent":"佐藤保育課長、吉田保育施設調整担当課長","answer":"先ほどの答弁と重なりますけれども、保育教諭という大きな課題がありましたので、我々保育課といたしましては、これまで定員弾力化とか、待機児童のほうに注力してまいりましたが。社会福祉法人への支援ということですけれども、大きくは、実際に社会福祉法人化したときの土地とかの貸付の支援とか、あと、品川区として就学前教育を強く推進していくということも踏まえて、その色を出す関係の理事の選任だとかを。","voiceIndex":93,"id":"exchange-030"},{"speaker":"高橋（し）委員","kind":"質問","question":"先ほど、保育課長から、移行期間が終わってしまうという話しがありました。先の話になってしまいますが、社会福祉法人化し、公私連携幼保連携型とした後に引き続き、その引き続きという話がいいのかどうかわかりませんが、１つの候補としてというのでしょうか、そういった体制を整えていくという大きな流れになるでしょうか。","respondent":"佐藤保育課長、吉田保育施設調整担当課長","answer":"前半のご質問ですけれども、まず幼保一体施設の今後のあり方につきましては、保育課が主体として検討してまいります。この条文をもとに、検討するなかで社会福祉法人化を進めていくことを来年度検討してまいります。","voiceIndex":96,"id":"exchange-031"},{"speaker":"高橋（し）委員","kind":"質問","question":"社会福祉法人化するのに、今お話があった第３４条で貸し付けて、それで、そうなったから社会福祉法人化できるという考え方でいいですか。","respondent":"吉田保育施設調整担当課長","answer":"正確に言いますと、第３４条の最初のところで、この団体がそれに値するという形で、公私連携法人を指定しまして、そこと協定を結ぶ形になります。そこが協定を結んだ後、必要であれば施設等の整備のために土地等を貸し出すというような順番になっております。","voiceIndex":99,"id":"exchange-032"},{"speaker":"高橋（し）委員","kind":"質問","question":"その協定を結ぶときは、まだＮＰＯ法人ですか。ＮＰＯ法人と協定を結んで、ＮＰＯ法人に資産を貸し付けて、貸し付けてもらえたからＮＰＯ法人が社会福祉法人化できるということではないですよね。","respondent":"吉田保育施設調整担当課長","answer":"申し訳ございません。具体的には、ＮＰＯ法人から社会福祉法人をつくりまして、社会福祉法人を公私連携法人ということに指定するという形で、そのときに協定を結びながら資産の貸し付けを行うという、このような順番で考えております。","voiceIndex":101,"id":"exchange-033"},{"speaker":"高橋（し）委員","kind":"質問","question":"ＮＰＯ法人が社会福祉法人化するときの支援をしていくということとなると、財産を持っていたり、いろいろな要件が必要なのですけれども、そういうことに関して区が積極的にというか、携わっていくという考え方でいいですか。","respondent":"吉田保育施設調整担当課長","answer":"委員のおっしゃられるとおりで、そのとおりです。","voiceIndex":103,"id":"exchange-034"},{"speaker":"南委員","kind":"質問","question":"今のご質問の関係で、私も最初に聞いたときに、今現在のぷりすくーる西五反田、ＮＰＯ子育て品川が持っている資産が、今使っている土地と建物はどこに帰属するものなのかを聞いたつもりなのだけれども、そこのご答弁がなくて環境整備が必要だとちょっと飛んでしまった答弁だったのですけれども、改めて今の関係ではっきりさせておきたいと思ったので再質問になりますが、今の状況はどうなっているのか。","respondent":"吉田保育施設調整担当課長","answer":"現在のぷりすくーるは区立ですので、区の資産です。","voiceIndex":106,"id":"exchange-035"},{"speaker":"南委員","kind":"意見","question":"そうしたら、必要な設備の貸し付けのところで、土地、建物の無償貸与を、貸し付けをするというふうなことで検討していくということになったのだけれども、今はＮＰＯ法人にそこも貸し付けているということで、新しく認定こども園ができるに当たって、社会福祉法人を設立して、そこに同じように貸し付けをしていくという、整理すると、こういう考え方でいいのか。","respondent":"吉田保育施設調整担当課長","answer":"順序としては、今のところはそのように考えております。","voiceIndex":110,"id":"exchange-036"},{"speaker":"高橋（し）委員","kind":"質問","question":"質問をしていいですか。今日、私立高校の推薦入試が行なわれていると思うのですけれども、生徒たちが帰ってこられているわけですね。それから、明日、都立高校の推薦の出願なのですけれども、１回集まってから出願させるか、個別に行っていると思いますが、その辺は、ぜひ事故などがないように対応をお願いいたします。","respondent":"大関教育総合支援センター長","answer":"出願関係は、休校になっても学校の教員は出勤しておりますので対応はできますので、個別に対応をすることになろうかと思います。授業はお休みの子との進度の差がないように行わないというのが休校の考え方です。","voiceIndex":116,"id":"exchange-037"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"鈴木（博）副委員長","kind":"質問","question":"目標なのですけれども、妊産婦と子育て保護者が、助言、相談の場をつくると書いてあるのが１番で、切れ目のない支援の仕組みを構築が２番に書いてあって、産前・産後の一時預かり、ニーズが高い事業の拡充を図るに３番と書いてあるのですが、そもそもネウボラの意味から言ったら、１番がメインで、２番と３番は１番から派生する項目だと思うのですけれども、その辺はこれを３つ並べてもいいのでしょうか。","respondent":"高山子ども育成課長","answer":"同時に、全国的にネウボラ事業を立ち上げる先進都市に学ぶにつけ、例えば、居場所づくりでありますとか、あるいは、産後の家事育児支援サービス、あるいは、育児パッケージのような、品川区と同様ですけれども。","voiceIndex":122,"id":"exchange-038"},{"speaker":"鈴木（博）副委員長","kind":"質問","question":"だから、うちの患者に聞いても知らない人が結構いる。だから、そもそもネウボラというのは何かという名前を認知させるということも大事だと思うのですが、例えば、「しながわパパママ応援アプリ」で、ネウボラについて宣伝はされているのでしょうか。そちらへ頼むのですよね。例えば、これを１回、ネウボラ経由にしたらどうかと思うのですけれども、その辺の見解はいかがでしょうか。","respondent":"高山子ども育成課長","answer":"当然、相談の中に直接的な拡充支援が必要ということであれば、その相談の対応の中身の中で、区の事業をご紹介するなどといった取り組みはしていますので、そういう意味では、両方の手法を併用するような形がこれについては適当ではないかというふうに考えております。","voiceIndex":124,"id":"exchange-039"},{"speaker":"鈴木（博）副委員長","kind":"質問","question":"わかりました。だから、人数的に足りているのかどうかというのは非常に心もとないのですが、それを増強する計画はあるのでしょうか。その点をお願いします。","respondent":"高山子ども育成課長","answer":"そういった相談員によって浅い深いという部分が若干出てまいります。それは否めないかというふうに考えております。ご質問の２点目と３点目は関連いたしますので１つでお答えしますが、現在は５館で対応しています。","voiceIndex":126,"id":"exchange-040"},{"speaker":"こんの委員","kind":"確認","question":"考え方を１つ伺いたいのですが、産後の家事育児支援の利用の対象ですけれども、出産した方で生後６カ月になるまでの乳児を育児している方、基本的なところの確認ですが、生後６カ月までとしたのはどういう意味なのかというところをまずお願いします。","respondent":"高山子ども育成課長","answer":"生後６カ月といたしましたのは、ネウボラの相談事業を構築するに当たって、アンケート調査をしたりとか、あるいは児童センターの中での個別の親子のひろばの中での聞き取りなどもする中で、出産直後の限られた時期ではあるのだけれども。","voiceIndex":128,"id":"exchange-041"},{"speaker":"こんの委員","kind":"確認","question":"わかりました。そのときに、１つは、多胎児に対しては、これは生後６カ月、１人に対して１時間という、利用時間のこともあわせて聞きますけれども、多胎児の場合は、１人に対してなのか、２人なので倍の利用ができるのかというところを確認したいのと、それから、私は１歳児ぐらいまでが厳しいというふうに見るのが妥当ではないかと思いますが、そのことについてお願いします。","respondent":"高山子ども育成課長","answer":"そして２点目の１歳児までの期間の延長ということに関しましては、いろいろなものがあるかと思いますので、やはりこれもママがとりやすい産後の３カ月とか、そういった時期がやはり全体的で見れば一番体がきつくて。","voiceIndex":130,"id":"exchange-042"},{"speaker":"こんの委員","kind":"質問","question":"確かにお母さんの体が育児をするに当たっては非常に大事なところなので、体調の回復を見たときには、生後６カ月までの間が一番きついだろうというのも理解はするのですが、いわゆる上のお子さんがいて、２人目のお子さんが、では、果たして生後６カ月で体が回復して上のお子さんも一緒に見ながら、そこはどうなのか、いろいろなご家庭のスタイルがあると思うので、ぜひそこら辺について、子育てといっても。","respondent":"高山子ども育成課長","answer":"ただ、兄弟関係について、もっとやさしい子育てをというそのご指摘はごもっともだと感じておりますので、そういった兄弟支援については、今後も検討してまいりたいと考えております。","voiceIndex":132,"id":"exchange-043"},{"speaker":"のだて委員","kind":"確認","question":"家事育児支援のところで、これはどういった事業者がやられているのかお伺いできればと思います。あわせて、助成は１,０００円ですけれども、利用料としては幾らぐらいになるのかも伺えればと思います。やはり今、品川でも年少人口が増えている中で、相談体制が十分なのかというところを確認できればと思います。","respondent":"高山子ども育成課長","answer":"質問を３点いただきました。１点目の産後の家事育児支援事業にどのような事業者がというところですが、実は、事業者につきましては、１つの株式会社と、あとは個人事業主ということになります。","voiceIndex":135,"id":"exchange-044"},{"speaker":"のだて委員","kind":"質問・要望","question":"品川の場合、妊産婦ネウボラ相談員と子育てネウボラ相談員がおり、産後どこまで担当されるかわからないのですけれども、両者の間で切れ目が生じてきてしまうのかというふうに思っているのですけれども、もともとのネウボラは、１人の方にずっとしていくというところで、気軽に相談できたりということで採用されてきていると思うのですけれども、そういった中で新たに子育てネウボラ相談員になったとき。","respondent":"高山子ども育成課長","answer":"それから２点目の１カ所に対して１人の相談員という体制がどうなのかという点につきましては、基本的には、確かに相談件数が伸びていることは大変順調な手応えを感じているところではありますが、日常的に児童センターで実施しております子育てひろばは。","voiceIndex":137,"id":"exchange-045"},{"speaker":"のだて委員","kind":"質問","question":"相談員の方が非常勤になっていることで、今年度は同じ方がやるということですけれども、なかなか言いにくいとは思うのですけれども、相談員の方から常勤になりたいと、そういった声はないのでしょうか。","respondent":"高山子ども育成課長","answer":"皆さん、来年度の雇用についてはいかがですかというようなお問い合わせの中にも、特にそういった勤務条件が合わないからというようなことでの続けられない理由などは、特におっしゃる方はいらっしゃいませんので。","voiceIndex":139,"id":"exchange-046"},{"speaker":"南委員","kind":"質問・要望","question":"私も、先ほど、こんの委員もおっしゃったけれども、自分が子育てしていたときに、産休をとって出産して、やっぱり核家族ですから、今と違って男性のイクメンという認識はなくて、男は外に出て働き、女は家庭で子どもが生まれたら育児に専念するみたいな、そういう感覚が自分自身にもあって、一生懸命育てるというところで、夜中に起きて授乳しなくてはいけない、２時間おきぐらいにお世話しなくてはいけない。","respondent":"高山子ども育成課長","answer":"出産後のサポートプランについては、希望制ということで、それでもまだ品川区も含めまして、いろいろなサービスがあって、なかなか取捨選択が難しいというような話もある中で、例えばこのサービスはどうですかというようなことを相談員が。","voiceIndex":141,"id":"exchange-047"},{"speaker":"南委員","kind":"質問・要望","question":"需要が高いというところからも、基本的に５館では非常に少ないのではないかと思っているのですけれども、だから、できるだけ実績も見ながら、早いうちにもう少し拡大できるようにしてほしいという思いで質問いたしました。ぜひその辺を受けとめた上で、対応もしていただきたいというふうなことが思いとしてありますので、この辺にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":143,"id":"exchange-048"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"先ほど、保健師でサポートプランをやって、その後、それが希望者になると言ったのですけれども、その切れ目のないというのは、ネットワークでうまくできているというのはあるのですが、ここの切れ目というのでしょうか、その辺の情報の共有というのでしょうか、この図の中にも継続的に云々とあるので、そのあたりのことを、いろいろ先ほどの話ではないですけれども、個人的な情報の件があるので。","respondent":"高山子ども育成課長","answer":"これにつきましては、実際いろいろと検討を行う中、組織としていろいろ課題として受けとめていたのですが、実際にどのような連携を図っているかと申しますと、例えば児童センターの側におけます子育てネウボラ相談員が、例えば支援が必要であったり、あるいは。","voiceIndex":144,"id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4932#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":56226,"voices":151}},{"id":"h30-20180122-5","meetingId":"h30-cm01","date":"2018年1月22日","dateIso":"2018-01-22","committee":"総務委員会","time":"午後 １時００分～午後 ３時１７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"住宅宿泊事業法の施行","agenda":"住宅宿泊事業法の施行","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"区民委員会では民泊の視察に行ってきたという話をちらっと聞いているので、ぜひいろいろな意見を聞いていただきたいと思っていますが、まず一番最初に、この国の定めた住宅宿泊事業法について、この法についての品川区の考え方、受けとめ方を伺いたいと思います。どういった方々からどういった意見を聞いていくのか。より広く聞いていただきたいと思うので、その辺をもう少し詳しく教えてください。","respondent":"柏原企画調整課長","answer":"法律に対する捉え方といいますか考え方の部分です。国のほうとしますと、先ほどの国のほうの資料にありますように、背景・必要性ということで、民泊サービスが日本にも普及していることで、やはり多様化する宿泊ニーズといったことへの対応が必要だというところがあります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"それは当然だと思うのです。区としては、これを受けとめて積極的に進めていくという考えなのかどうか、そこを伺いたい。先ほどマンションの規約のところ、今年の３月１５日から届出の受付が始まるというところにおいては、マンションとかあと共同住宅で、規約のところにこの住宅宿泊事業法のこの中身を受け入れていくのか、受け入れていかないのか、しっかりと規約の中に明記すべきであるという形です。","respondent":"柏原企画調整課長","answer":"先ほどのご答弁と重なる部分がありますけれども、法律の趣旨というところは先ほどお話ししたとおりでございまして、一定程度そこは理解をしながらですが、住んでいる方々の安心・安全とか、安心して住み続けられるといったところを配慮しながら。","voiceIndex":7,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"だから、やはり大もとのところが本当に区民の安心・安全をきちんと確保できるのかどうか。特に、先ほどいろいろご意見は聞いてくださっているということですけれども、住んでいらっしゃる住民の方も本当に住民合意、あときちんと中身が説明されて、区民の隅々にまでやはりこの中身が理解されないといけないと思っているのですが、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"そういった考え方も含めて、今、いろいろなところからご意見を伺いながら、実情に合った形で検討していきたいです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"これは、法が６月に施行されますよね。これは条例がつくられないと、条例なしで区民の皆様を守ることはできないのか。条例化をするということは規制緩和を認めていくことになっていくと思うのですけれども、その辺をお伺いしたいのと、あと、今後の進め方、スケジュール的なもの教えてください。","respondent":"柏原企画調整課長","answer":"６月には法律が施行になりますので、そういった形でその施行に向けて準備を進めるということになります。","voiceIndex":11,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"提案","question":"ちょっと今回の報告の１枚ぺらの中身からすると、一体何が言いたいのかなという、条例化の考え方は口頭でしたけれども、何か報告の仕方がすごく曖昧であると、区の姿勢はどうなのだろうとはっきりしない提案であると私は思ったので、スケジュールも当然お伺いしたのですが、よりよいものをつくるのであれば、より広く区民・議会においても議論する時間を確保してほしいと私は思いました。これは意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":13,"id":"exchange-005"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"この条例を制定してからのことも含めて、ぜひその辺をまずお知らせいただきたい。我々も実際民泊をやっている業者にお話を聞かせてもらいましたけれども、彼らは彼らなりの思いもあって、それこそやり方等詳しく知っている方たちなので、やはりその辺も区の条例制定にいい効果をもたらしてもらえるようなヒアリングをしてもらいたいと思いますが、その点について、２点お伺いいたします。","respondent":"柏原企画調整課長","answer":"今いろいろなところのいわゆる事業者に対するヒアリング等々というところで、民泊の事業者というところですけれども、現在どのような形のヒアリングがいいのかというのはあるのですが、いろいろなところの事業者からの意見を聞きたいということで、事業者といいますか。","voiceIndex":14,"id":"exchange-006"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"例えばあそこの部屋が騒がしいのだけれども何とかしてくれないかとかいうトラブルは、割と深夜帯に起こることが想定される中で、例えば先ほどの役割の中で届出の受付とおっしゃっていましたけれども、そういった苦情の窓口とかいうのは、これは区のほうで設置をされるのかというのと、設置をされた場合に、ある程度深夜帯のことを想定した際に。","respondent":"柏原企画調整課長","answer":"苦情として今の段階で話が多いのは、やはり夜間の騒音であったりとか、ごみの問題とかいった話は既に出てきているところでありますので、清掃事務所であったりとか、それから環境の部門であったりとか、あと、旅館業にかかわる部分ですので保健所といったところが。","voiceIndex":16,"id":"exchange-007"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"文教地区においては、いわゆる例えば半径何メートル以内のところに関しては、学校や保育園等を事前の周知の対象にするだったり、届出事業者の確認は受付の時にしっかりやっていただきたいのと、いわゆる事業者の公表についても台東区は今ルール化をしようとしています。集合住宅に関しては、何らかの標識の義務化。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-008"},{"speaker":"吉田委員","kind":"質問","question":"最初に、これは言葉の整理みたいな感じなのですけれども、届出が必要となっていますが、これは届出制と理解していいのでしょうか。許可とか認可が必要ということではなく、届出ればもう認められてしまうということなのか。いろいろ監督義務とかありますけれども、それがちゃんときちんと実施されない場合のペナルティになるのか、それとも取り消しとか何かそういうことがあるのか、その辺をまず１つ伺います。","respondent":"柏原企画調整課長","answer":"そういったつくりになるので、旅館業法のほうの規制というところにつながるというつくりになっているものです。","voiceIndex":19,"id":"exchange-009"},{"speaker":"吉田委員","kind":"質問","question":"その旅館業法をちゃんと調べていなくて申し訳ないのですけれども、そうしますとこの届出に必要な内容がきちんと実施されなかった場合は、旅館業法のほうの規制で、例えば民泊が続けられなくなるとか、そういうふうに理解してよいということでしょうか。","respondent":"柏原企画調整課長","answer":"おっしゃっていただいたとおりでございまして、旅館業法の規制の範囲、罰則規定もありますけれども、そういった事業ができなくなるというのは、そちらの法規制のほうで規制がかかるというものです。","voiceIndex":21,"id":"exchange-010"},{"speaker":"吉田委員","kind":"質問・要望","question":"それは１点了解いたしました。もう一点、質問として伺いたいのは、先ほどいろいろな方たちから意見聴取を行っているということで、それはぜひもっと繰り返し進めていただきたいと思うのですけれども、今ここで出されているレベルの民泊の事業をこういう条例をつくって始めます。品川区の場合は会期中以外の委員会もこのように開かれるわけですから、そういう場を活用していただきたかったと考えています。","respondent":"柏原企画調整課長","answer":"後段のほうのお話につきましては、条例ということで定めようとしていますけれども、区の考え方をお示しして、それでこういった議会というところで本会議、それから付託されるであろう委員会等々、ちゃんと議会としての議論、審議をしていただく場面があると思ってありますので。","voiceIndex":23,"id":"exchange-011"},{"speaker":"吉田委員","kind":"確認","question":"そうですね。そうなると、これは条例のほうが優先されると考えてよろしいのでしょうか。法令上は３月１５日から受付開始になっておりますけれども、先ほどスケジュールの話もありましたけれども、そのスケジュールの確認をさせてください。","respondent":"柏原企画調整課長","answer":"その辺の届出の関係の部分のところにつきましては、法令なのか条例なのかというよりは、ここで物事が３月１５日から受付が始まっているところに関して、どのような対応といいますか、条例をつくるのも含めて対応がよろしいのかというところも含めて。","voiceIndex":25,"id":"exchange-012"},{"speaker":"吉田委員","kind":"意見","question":"では最後、そうしたら、あと意見です。法令上３月１５日だからといって、もし３月１５日に受付を開始してしまうと、極端な話、この条例が決まる前の受付になってしまうわけですよね。それはやはり避けるべきではないかと思います。やはり区としての条例を決めるのであれば、それにのっとった受付がその後開始されるべきではないかと思います。これは意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":27,"id":"exchange-013"},{"speaker":"須貝委員","kind":"質問・要望","question":"やはり、じゃあ、安ければいいのかと。ですから品川区のほうに要望したいのは、私はできるだけやはり厳しい条例をつくっていただいて、例えば苦情とか何かも品川区に来てしまうわけですよね。そういうことがほとんど起きないように、そして地域の住民から不満やそういう問題提起されないような条例を、私はつくっていただきたいと思います。意見だけ申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-014"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"それで、ちょっと伺いたいのですけれども、いわゆる民泊には幾つかの形があって、さっき言った特区の形もあれば、この民泊振興の形もあれば、いわゆるその旅館業法に基づく簡易宿所のような形での民泊というものもあると思います。要するに法的にいわゆる旅館業法上の民泊がこれから増えるという見込みなのか、その辺について何か情報があれば教えていただきたいのが１点です。","respondent":"柏原企画調整課長","answer":"聞いている範囲の中でも、特に簡易宿所の届出が極端に増えているという話は、今の段階では聞いてはいないのですけれども、ただ、旅館業法のほうが、この新法の部分よりも、特に設備面といったところでは規制といいますか決まり事が多いものですから。","voiceIndex":29,"id":"exchange-015"},{"speaker":"あくつ副委員長","kind":"確認","question":"ちなみに私が住んでいるところはまだやっていないのですけれども、先ほど１,６００の管理組合に通知を出されたというお話がありましたが、これは本当に間違いないのかどうか確認で、住宅課なのかどうかわかりませんけれども、いわゆる担当課からこれはもう本当に出されているのかということが１つ。","respondent":"柏原企画調整課長","answer":"出したのは直近だと聞いておりまして、１月に入って、まだ先週とかそういう時期だと聞いています。国土交通省で出している基準であるとか、そのガイドライン的なものを添付しながら、周知、お知らせしていると聞いています。","voiceIndex":31,"id":"exchange-016"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"先ほどもありましたけれども、もしこれに反するようなことをした場合に、やはりさっき旅館業法の改正で、３万円の罰金だったのが１００万円まで引き上げたというような話を見たのですけれども、それを無視した場合、１００万円の罰金を無視するかどうかわかりませんけれども、先ほど強制力というお話もありましたが、あと、夜間にどうやってそれを取り締まるのだという話もありましたけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-017"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"例えば利用者に対して銭湯のタオルの引換券配布とか、あと商店街の多言語マップとか、様々な形で今取り組んでいると思うのですけれども、今、意見聴取をしているという中で、品川区商店街連合会とか浴場組合だとか、そういう意見もこれから様々取り込んでいくと思うのですけれども、今現段階でどのように、これからこの地域活性化のために情報提供も含めてやっていくのかどうか。","respondent":"柏原企画調整課長","answer":"それからあと、いろいろお話を聞く中で、例えば商店街連合会のほうではいろいろなことを考えたいというような話も聞いておりますので、そういったところのご意見、このようなことをやりたいとかいうお話を考えているようですので、そういったことを聞きながら。","voiceIndex":34,"id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"３点お伺いしますが、１点目、地域の問題なのですけれども、旅館業法の中では、学校教育法とか児童福祉法、そして社会教育法などに対して配慮が書かれているのですが、例えば学校、児童施設、社会教育施設といったところへの配慮について、地域について区の考え方がある程度あったら教えていただきたいのが１点です。だから家主不在型のところを、情報連携でどう問題点を解決するのかというのが２つ目です。","respondent":"柏原企画調整課長","answer":"一番最初の学校等といったところへの配慮といいますか考え方と、それから３番目のご質問、事前の説明であったりという部分につきましては、その手法、やり方の部分になってまいりますので、それにつきましてはこの制度を考える中で併せて検討していきたいというものです。","voiceIndex":36,"id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"地域の問題とか、あと説明の問題、本当にいろいろな方の意見をしっかり聞いて、ここのところは本当に丁寧にやっていただきたいし、事業者の責務というのも明らかにすべきであると思っています。家主不在型はすごく問題が大きいと思うのです。これは住民の方にとってメリットはなく、デメリットばかりであると思うので、私たちはやはりこの家主不在型というのは認めないでいただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-020"}]},{"id":"topic-02","title":"デジタルサイネージ（電子掲示板）の設置について","agenda":"デジタルサイネージ（電子掲示板）の設置について","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"幾つか質問しようと思ったのですが、見せてもらって、見てわかったことがかなりあったのですが、１つ、多言語対応ということで、文字の切り替えですよね。音声的な説明というのは考えていないのですか。それが１つです。タッチをするのは住民の方ですよね。そこが削られるというようなことはないのかどうか、お聞かせください。","respondent":"木村報道・プロモーション担当課長","answer":"３点ございまして、多言語、音声のほうなのですけれども、実際今のところは音声のフォローについては考えておりません。","voiceIndex":46,"id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問","question":"正面玄関のところはすごく大きくて立派なものだと思ったのですが、予算のところを調べてこなかったので、予算がどのくらいかかっているのか教えてください。","respondent":"木村報道・プロモーション担当課長","answer":"今年度の予算ですが、およそ３,０００万円です。実際ランニングコストも同様ぐらいの規模感で考えておるところです。","voiceIndex":48,"id":"exchange-022"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"いろいろ区のお知らせ等が掲載されていたのですが、あれはあれで簡単なお知らせだと思うので、それ以上のことはないのかなと思うのですけれども、例えばあそこを見て、何か情報を得て、それを今度例えば自分のスマートフォンで、いわゆるデジタルサイネージの前だとその情報はわかるけれども、その後忘れてしまったらそれまでになってしまうので、できたら例えば少し詳しい詳細などがあるものに関しては。","respondent":"木村報道・プロモーション担当課長","answer":"Ｗｉ－Ｆｉですけれども、区役所で使える品川のフリーＷｉ－Ｆｉを受信しているような形になっておるので、そういう形です。それから、実際に所管への行き方であるとか、スマホとの連携につきましては、ご意見頂戴しまして、検討してまいりたいと考えています。","voiceIndex":50,"id":"exchange-023"},{"speaker":"高橋（伸）委員","kind":"質問","question":"それで、この導入場所なのですけれども、５カ所の地域センターに導入するということなのですけれども、１３カ所の地域センターがある中の５カ所ということで、これから先は全地域センターに導入するのかどうかということと、あと、この地域センターにおいては、地域行事のお知らせなどとか、町会および自治会の活動の支援と書いてあるのですけれども、第四地域センター管内だと１４町会とか。","respondent":"木村報道・プロモーション担当課長","answer":"全ての地域センターへの配置というところと、それからどのように情報を募るかという部分です。今予定では、来年度、これから予算をご審議いただいきますけれども、来年度で全地域センターに配備完了という形を考えております。","voiceIndex":52,"id":"exchange-024"},{"speaker":"吉田委員","kind":"質問","question":"１月中は試行運用で、２月１日から運用開始ということで、単純な質問ですみません。試行した結果、本格運用とどのように違うのか。だから、今みたいなご意見が取り入れられて、多少改良されて本格運用になるのか、その辺の試行と本格運用の差や違いを教えてください。","respondent":"木村報道・プロモーション担当課長","answer":"いろいろ操作をしながらそれを解消していくということもありますけれども、一番大きなところは、各課で情報を出せるような形になっているのですけれども、これから各課の研修を行いまして情報をアップする、その態勢が整って２月というような形を考えています。","voiceIndex":54,"id":"exchange-025"},{"speaker":"吉田委員","kind":"質問・要望","question":"それと併せて、これも先ほどからありましたけれども、こういうことが得意でない方たちのためには、情報提供を進めるというスタンスで言うと、アナログのほうの掲示の仕方も、こういう情報提供を進めるという機会に検討していただきたいと思います。あの辺も、こういう情報提供を進めるというこの機会に、もう一度わかりやすいような検討をしていただきたいと思います。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-026"},{"speaker":"須貝委員","kind":"質問・要望","question":"このデジタルサイネージは目にぱっと飛び込んでくる情報で、また画面もきれいですね。それも多くの方が、町会関係者、地域関係者が見られる。室内というのやはり営業時間外はほとんど見られないということですから、土曜・日曜・祭日もそうなのですが、その辺に一つ盲点があるので、ぜひ検討していただきたい。目に飛び込んでくるというものなので、すごくいいものができたのだなと感じました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-027"}]},{"id":"topic-03","title":"オープンデータ利活用による地域課題を考えるワークショップの成果発表について","agenda":"オープンデータ利活用による地域課題を考えるワークショップの成果発表について","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"私などよく保育園に関係するところ、多分保育園を利用したい方々もしょっちゅう使っているだろうなという項目が幾つかあるのですけれども、実際にこのワークショップが開かれているわけですけれども、もう一回これの目的とか、どのような方々がここに参加をして、どのような過程でこの成果物を生んでいるのか、ちょっと流れを教えていただけたらと思います。","respondent":"仁平情報推進課長","answer":"実際このワークショップとオープンデータの関係ですけれども、こちらのほうは最初から区のほうでこのテーマについて考えてみませんかというような進め方ではなくて、あくまでも皆様が集まった中で地域の課題を自由に討議していただいて、その中から課題を見つけ出して。","voiceIndex":64,"id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問","question":"こうやっていろいろデータをもとに、活用しやすい方法でアプリなどもつくっているということで、具体的にこれから見せていただくと、こういう活用の仕方があるのだなということになると思うのですけれども、このでき上がった成果物を今後どのように活用していくのかということと、今後やはりこういうワークショップを続けていきながら、いろいろな分野の拡大をしていくのかどうか。","respondent":"仁平情報推進課長","answer":"今後につきましては、また次年度の話になりますけれども、今回の取組みの成果を踏まえまして、引き続き今年の課題等に取り組むと同時に、またちょっと対象者層を変えて、さらなるオープンデータの活用のあり方、仕方を続けて。","voiceIndex":66,"id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問","question":"ぜひまた見せていただいて、区民の皆様からこういうものがあったらいいなというようなご意見をどんどん具体化していっていただけたらと思います。ここに協働と書いてありますけれども、プロの方からどのような援助を得ているのか、ちょっと教えてください。","respondent":"仁平情報推進課長","answer":"今回協働事業という形でやらせていただきました団体はＣｏｄｅ Ｆｏｒ Ｔｏｋｙｏということで、オープンデータの活用とか、いろいろなアイデアを見出すといいますか、そういうワークショップ、こういう取組みを自主的に行っている団体でありまして、会社とか企業とか。","voiceIndex":68,"id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問","question":"企業ではないということですが、ＮＰＯとかどういう団体なのでしょうか。そこだけ最後お聞きします。","respondent":"仁平情報推進課長","answer":"Ｃｏｄｅ Ｆｏｒ Ｊａｐａｎという、元々大きな全国的な組織がありまして、その中で各地区のほうでこういうオープンデータ系とか、いろいろな課題を考えるというワークショップを開催していて、そういう取組みを行っている自主的な団体の集まりという形になっております。","voiceIndex":70,"id":"exchange-031"},{"speaker":"石田（し）委員","kind":"質問","question":"こういうのがいわゆる今の時代の協働のあり方になってくるのかなと思うので、ぜひ今後も進めていっていただければと思うのですが、１点だけ、このアプリをつくられた際のいわゆる権利関係というのがどのようになっていくのかが重要になってきて、例えば区民の協働というのはすばらしいのですけれども、逆に言えば、要は区がその開発とかに携わっていなければ。","respondent":"仁平情報推進課長","answer":"今回つくられた中身自体は、あくまでも参加者の手によるアプリですので、公表等に区のほうは支援はしていきますけれども、扱い的には区のアプリではなくて、制作者のアプリという形になりますので、非公式なアプリという形です。","voiceIndex":72,"id":"exchange-032"},{"speaker":"石田（し）委員","kind":"意見","question":"非公式になっても、区が何らかの関係性を持ってのいわゆる協働作業でやられてきたものだと思いますので、何かその発信方法について、やはり区が発信すると、区民の方はそれこそこのようなものがあるのだという認識もされますし、また安心感というのもあるのかなと思うので、その辺はうまく区としてもせっかくの成果物ですので、何らかの形でそういう発信の部分に関してもその参加者の方たちと話し合いながら。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":74,"id":"exchange-033"},{"speaker":"吉田委員","kind":"質問","question":"それで公表するということは、みんなが使えるようにするということだと思うのですけれども、その辺の発信の仕方もあくまでこのワークショップの人たちが何か発信するのか、それとも区が発信するのか。今のご意見の続きみたいな質問なのですけれども、今後誰でも使えるようにするというところに、区はどのように絡むのか、お考えをお聞かせください。","respondent":"仁平情報推進課長","answer":"公表にあたりましては、発信方法なのですけれども、今回協力していただいているＣｏｄｅ Ｆｏｒ Ｔｏｋｙｏが特設のサイトをつくるというような話、計画にもなっておりますし、アプリが公開されているというところの周知。","voiceIndex":75,"id":"exchange-034"}]},{"id":"topic-04","title":"八潮地域センター複合施設非構造部材耐震化その他工事請負契約","agenda":"八潮地域センター複合施設非構造部材耐震化その他工事請負契約","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"ガラスフィルムも全ての窓ガラスに張られるのかどうか、そこを教えてください。下の関連工事のところのその他電気設備工事、その他機械設備工事というのは、具体的にどのようなものなのか教えてください。","respondent":"立川経理課長","answer":"ガラスフィルムにつきましては、全ての窓について実施するものです。その他電気、機械設備工事ですが、北棟のエレベーターの改修を実施するという内容です。","voiceIndex":82,"id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問","question":"工期が３月３０日までになっていますけれども、工事する場所でやはり閉鎖したり使えなくなったりする部分があると思うのですが、その辺がどのような手順で行われるのか、周知がどうなっているのか教えてください。","respondent":"立川経理課長","answer":"予約は３月３１日までできないです。工事が早めに終わるようでしたら、事前に周知いたしまして、いわゆる３月中にも申込みを受け付けるといった内容になってます。基本的には居抜きの工事ですが、現状、レク室と音楽室とスポーツ室については利用できないです。","voiceIndex":84,"id":"exchange-036"}]},{"id":"topic-05","title":"不動産の寄附受領について","agenda":"不動産の寄附受領について","exchanges":[{"speaker":"松澤委員","kind":"質問","question":"今、結果的に遺言書を書いてあったということで、うれしいのですけれども、この使い道なのですけれども、町会としては鈴木さんの面倒を見ていたので、ゆうゆうプラザみたいな高齢者施設にしたいという思いがあるのですけれども、これは今年一年で更地にするということなのですけれども、その後の計画なのですけれども、これは地元にやはりいろいろな説明みたいなものをされるのでしょうか。","respondent":"柏原企画調整課長","answer":"現段階で何かというところで具体的に何か決めているところではありませんので、今後検討しながらということになるかと思います。","voiceIndex":91,"id":"exchange-037"},{"speaker":"松澤委員","kind":"質問・要望","question":"地元の方たちの意見を十二分に聞いていただきたいと述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-038"},{"speaker":"須貝委員","kind":"質問","question":"ここは結構本当に閑静な、場所もいいし、実際一般に不動産価格おそらく区のほうも調べられたと思うのですけれども、相当な金額になるのかなと思ったのですが、大体どれぐらいの価値があるものなのでしょうか。参考に教えていただければありがたいです。","respondent":"立川経理課長","answer":"実勢価格は抜きにしまして、路線価等から勘案いたしますと最低２億円以上ということです。","voiceIndex":94,"id":"exchange-039"}]},{"id":"topic-06","title":"品川区原動機付自転車ご当地ナンバープレートデザインの決定について","agenda":"品川区原動機付自転車ご当地ナンバープレートデザインの決定について","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"この優秀賞２作品と特別賞というのは、例えば区広報紙などで公表されるということなのでしょうか。せっかく優秀賞と特別賞があるのだったら、拝見したいという単純な思いがあるのと、それから、このしながわ水族館のイルカは、しながわ水族館のコピーライトのマークがありますから、それで、そのコピーライトごと、このナンバープレートの権利みたいなものは品川区に帰属するということなのでしょうか。","respondent":"伊東税務課長","answer":"それと、イルカの絵ですけれども、それはこのままこのイルカ自体は、広重の絵もそうですけれども、このまま使えるという形になっていまして、著作権関係は全て区のほうにいただくという形で、本人との了解は得ているところです。","voiceIndex":101,"id":"exchange-040"},{"speaker":"吉田委員","kind":"意見","question":"優秀賞と特別賞を公表されないということなのですが、さっきの特別賞の意義から言うと、高校生の作品でもあるし区内の方ということであれば、大々的にではないにしても、せっかく応募してくださって特別賞ということであったら、何かちょっと配慮がいただけたらいいなと思います。これは意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":103,"id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2098#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":35766,"voices":109}},{"id":"h30-20180123-14","meetingId":"h30-cm01","date":"2018年1月23日","dateIso":"2018-01-23","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ５時１２分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"区有施設、公有地等活用に関すること","agenda":"区有施設、公有地等活用に関すること","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"まだ確定じゃないというところで、ぜひ、やはり障害者施設を設置していくべきだと思いますし、そういった中身を活用内容（案）にも示していただきたいなというふうにも思うのですけれども、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"こちらの施設の方向性といったところにも記載をさせていただいているところではありますけれども、大きな敷地があるというところもありますので、さまざまな方が集えるといいますか、ご利用可能な施設ということで検討しているものですので、ここにもお子様や地域の方々、高齢者。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"行政需要や優先順位を見てというふうに障害者福祉課長もおっしゃっていたのですけれども、この間も課長のほうからは行政需要等々というふうにおっしゃられて、この土地の活用の仕方というのを考えていくということだったのですけれども、行政需要というのは、どのようにして決められているのでしょうか。伺いたいと思います。","respondent":"柏原企画調整課長","answer":"こういったところをトータルで考えながら、どういったものを入れるのかというのを検討するですので、現段階でこれとこれと決めうちというよりは、先ほども申しましたが多様な面から考えながら、最終的には複合的な施設ということになろうかとは思いますけれども。","voiceIndex":7,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、これからさまざま、そして多様に、さらに複合的にというふうにおっしゃっている中に、ぜひ障害者施設、グループホームや就労継続支援Ｂ型もこれが特に足りないというふうに障害者福祉課長もおっしゃっていますし、私たちもそう思っていますので、ぜひ入れていただきたいですし、入れるべきだし、区が主導で進めていかなければ増えていかないというふうに思うのですけれども。","respondent":"柏原企画調整課長","answer":"資料にお示しをしているとおりというところではありますけれども、先ほど来申し上げているとおり、さまざまなニーズ、それから地域の実状等々ありますので、そういったところを考えながら、施設構成は考えていきたいというものです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今の段階では、そういうご答弁になると思うのですけれども、本当にここに求められている。それは、先ほども行政需要のご説明のところで、ニーズ、地域の声ということもありましたので、これは本当に今大きく声が上がっているところですので、ぜひその声を受けとめていただいて、行政需要として区が主導で進めていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ、検討に入れるべきだと思いますし、増やすという方針は区も持っているわけですから、入れるべきだというふうに意見を述べさせていただいた上で、この検討に入っているかどうか伺いたいと思います。それが１点です。それとも５,０００平米に含まれているのか、これをお伺いします。それともまだ伝えていらっしゃらないのか、伺いたいと思います。","respondent":"柏原企画調整課長","answer":"最初のところですけれども、特養という施設の名称が出ましたが、こちらに関しましては、前の議論と同様の部分がありますが、さまざまなニーズといったところ、それから地域事情、これらをトータルに考えながら、この施設というのも考えながら。","voiceIndex":13,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"調査もしていきたいと思います。それと、もう１点です。施設規模の想定というようなことでありますが、「近隣への圧迫感を考慮し３～４階建て施設を想定」とありますが、この土地の用途地域は、調べますと、第一種中高層住居専用地域ということですけれども、こういった検討をするに当たって、当然いろいろな条件は調べていらっしゃると思いますが、建築上の制限は実際どうなっているのか伺いたいと思います。","respondent":"柏原企画調整課長","answer":"この施設構成を考える際に、当然のことながら、ボリュームチェックということで、どのぐらいの施設が可能なのかということで検討はしています。","voiceIndex":15,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"私も調べてみたところ、これは南北に長い土地ということで、これが東西に長い土地ですと、かなり日影規制というのが発生してくるのですけれども、これは南北に長いということもありまして、日陰上の規制というのは、ある意味工夫次第でかなりクリアできるところもありまして、もう少し建てられるんじゃないかというふうに、今想定しているんですが、ぜひ、近隣への配慮はもちろんしつつ。","respondent":"柏原企画調整課長","answer":"それ以外の場所は、面積的には、例えば５,０００平米とかとれるにしても、その上に建物を建てたときに、なかなかボリュームをとることが難しいという。例えば東側のほうのエリアであると、そういったこともありました。","voiceIndex":17,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"状況はわかりました。近隣への配慮をしつつ、建物をどこの位置に建てるかということも含めて、最大限工夫をしていただいて、さまざまな行政需要に応えられる施設にしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-008"},{"speaker":"若林委員","kind":"質問・要望","question":"１つ、取り壊し、除却について、国のほうの予算が、平成２９年度はついていないということで、平成３０年度がどうなるかという、これから注目されるわけですけれども、こういったいわゆる不確定要素と、先ほど区の購入、取得は、平成３１年度以降になるというようなお話もあって、ここら辺はしっかり決まったスケジュールの中で、当然歩んでいかなければいけないので、ここら辺、私たち地元の区にとって。","respondent":"柏原企画調整課長","answer":"最近はこのエリア、大分耐火、準耐火の建物が増えたということで、全部が建物でなくてはいけないというふうな考えから少し東京都も若干変わってきているようですけれども、建物が必要なのは間違いありませんので、それについては、その建物の位置だとかいうのは。","voiceIndex":21,"id":"exchange-009"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6042#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":10535,"voices":26}},{"id":"h30-20180125-18","meetingId":"h30-cm01","date":"2018年1月25日","dateIso":"2018-01-25","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ４時０５分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"競技場は、基本的に東京都がやっているものなので、まさにお答えはしづらい部分かもしれないのですが、建設４団体からお話があるように、品川区内で競技が行われて、やはり品川区内の建設労働者や建設従事者というのですか、ある程度品川区もかかわり方を見ていかなければいけないのではないかという質問を私は至るところでしているのですけれども、このかかわりとしては何かあるのかどうなのか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"ただ、しかるべき手続を踏みまして、東京都といたしましては、受注者、建築工事等の会社をもう決めているところです。その辺、区の方がどうかかわるかというのは、区といたしまして、そこまで踏み込むことはできないという状況です。","voiceIndex":7,"id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"でも区としてそういう思いを伝えたということは非常に評価するべきところであって、できるのであれば、本当にこの品川区への招致が決まってから、ずっと気運醸成に努めてきて、他区と比べて本当に先を行っている区だと思っていますので、今度はそういったハード面の部分でも、しっかりかかわりの持てるような関係づくりというか、むしろ本当に。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"意見","question":"ホッケー場の人工芝について、以前、東京都オリンピック・パラリンピック準備局に行ったとき、お話をしてきました。あの芝のまま聖地としてとホッケー協会は言われている一方で、我々は多目的に利用できるようにということを言っているわけですけれども、始まるまではそのまま行くと思いますが、終わった後の話というのはいつごろまでに、結論が出るというか、どう考えておけばいいのでしょう。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"その後の芝の考え方ですが、現在、東京都のほうでも後利用の考え方が出されておりまして、そちらに記載していますが、競技場の使われ方次第によっては芝を張りかえる可能性もあるというふうに書いてございまして。","voiceIndex":11,"id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6528#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":3348,"voices":15}},{"id":"h30-20180126-10","meetingId":"h30-cm01","date":"2018年1月26日","dateIso":"2018-01-26","committee":"議会運営委員会","time":"午後 １時００分～午後 １時２５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を5件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"ＩＣＴ推進会議からの報告事項","agenda":"ＩＣＴ推進会議からの報告事項","exchanges":[{"speaker":"伊藤委員","kind":"質問・要望","question":"ＩＣＴ推進会議より３点ご報告をします。お手元に資料を配付しておりますので、ご確認ください。第１条の２行目「画像等」の部分については、動画の取扱いをどうするか、提示を可とするか否かを含めて検討を行っております。次に、第２条第２号「必要最小限」の部分については、具体的にどの程度の分量までパネルの使用を認めるべきか、また、その基準を明文化するか等の検討を行っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-001"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"たけうち委員","kind":"提案","question":"今回、ご案内のとおり５月１１日に第３回議会報告会を行わせていただきます。４月の委員会の段階ではほぼ決定したものをご提案いただく形になると思いますので、２月の委員会の終了後に、できれば各委員の皆さんで、各委員会でどういう内容を議会報告会で提案説明するかというご議論を一定程度行っていただければなと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":32,"id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"提案","question":"２６日、２７日でも当日の報告もあるわけですから、これも上げたらどうかというのをやっていただいて、２７日には決定をしていただいて、委員長が了承して、議会報告会の中で委員長が報告できるような形をとれればということで、一応２０日ぐらいを目途に日にちを決めていただいたほうがやりやすいのではないのかなと思うので、それは提案します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":34,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今の話だと、ちょっと突然だったのでよくわからないのですけれども、２月２０日までに、例えば私は厚生委員なのですけれども、厚生委員会としてこういうふうなものをやったほうが、報告の中に入れたほうがいいのではないかというのを、２月２０日までに各委員が委員長か事務局に。ちょっと細かいですけど。第１回定例会というのは結構いろいろなものが出てくるので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":39,"id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問","question":"２６日、２７日を否定するわけではないので、そこでやるので、資料は出てくるわけで、その中で意見を言えるわけですから。１回そこで２０日ぐらいまでに出してもらったほうがいいのではないかと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-005"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5262#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":8866,"voices":44}},{"id":"h30-20180220-10","meetingId":"h30-cm02","date":"2018年2月20日","dateIso":"2018-02-20","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時１２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を11件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成３０年第１回定例会","agenda":"平成３０年第１回定例会","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"議案説明会のときもちょっと質問したのですけれども、国保の条例というのはいつ頃出るかというのは、今日報告がないと思うのですけれども、条例がいつ頃かというのはまだわからないという状況でしょうか。","respondent":"久保田区議会事務局長","answer":"私どものところにはまだそういう話が来ていませんので、ちょっとわかりませんが、もしそういう話があれば、また議会運営委員会等のほうで上程の手続等のために行いたいと思ってあります。","voiceIndex":10,"id":"exchange-001"}]},{"id":"topic-02","title":"ＩＣＴ推進会議からの報告事項","agenda":"ＩＣＴ推進会議からの報告事項","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"ＩＣＴ推進会議より２点ご報告をします。再度の確認となりますが、本件はこれまで予算・決算特別委員会等で行われてきました資料やパネルなどの提示、それからタブレット端末の運用開始により新たに想定されるSidebooksを用いた画像共有等のルールについて規定するものであります。ですから、こういう基準をもとにして、携帯電話の導入を確認したですので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-002"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"議長、ご説明いただきましてありがとうございました。あそこは空けたほうが品川区としてはいいのか、有効活用ということもいろいろ議題に上がって、今いろいろ小林牧場とも話したり、競馬組合とも話したり、議長会の中でも話してきたと思うのですが、そういうことを考えると、どのような方向で地元の要望をおっしゃったのかというのだけ確認をさせていただきたい。","respondent":"松澤議長","answer":"軽いものは修理しましたけれども、あそこは旧耐震建築で耐震改修ができないということから大変に不安があるということで、今このように競馬事業が好調なうちに、ある程度直す計画を持つべきではないかということでお話をしました。","voiceIndex":32,"id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今の話はぜひ品川区議会の中でも話をしていただきたいと思います。厩舎の方々からそういう話があるのは我々も耳にしていますけれども、品川区議会としてそういう話をしたことは多分一回もないのではないかと思っておりまして、その辺のところはぜひ、もしそういう発言をされたのであれば、議会としてもそういう議論をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-004"},{"speaker":"南委員","kind":"意見","question":"実はまちの中から、この品川区議会でもいろいろと対応している東芝病院の問題についてなのですけれども、インターネットでも大分いろいろな科がなくなるというようなことだとか、病院の中でも張り出されていて患者が非常に心配しているという声を複数聞くので、議会としても、そういう状況の中で改めて実態をつかみながら、何らかの発信をしていく必要があるのではないかと思っているのですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":42,"id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"意見","question":"今、厚生委員会の話が出ましたので、今日正副委員長の打ち合わせをしました。話も出ました。その前に、私はまず議会運営委員会か議長のところの話だろうと言ったのが最初冒頭なので、今、ちょっとあれですが、議長のお考えもまず先はそちらだろうと、厚生委員会は後づけだという話をしたので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":44,"id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問","question":"南委員がどういういきさつで厚生委員会でそういう報告があるとお聞きになったのかは、副委員長が共産党の方なので、この話は私も本当に今日の今日、打ち合わせで聞いた話なので、聞いた瞬間、私は先ほど言いましたように、それは議会運営委員会か議長マターの話ではないのかと、厚生委員会一つで受ける話ではないのではないかという話をしたのだけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"しかしホームページのいろいろな資料を見てみると、かなり多岐にわたっていろいろな科が十幾つなくなるという話で、区民の皆さんが不安になるのは当然だと思うので、そこのところで、一回この品川区議会としてもアクションは起こしているけれども、やはりさらに進んだ中での情報も取って、どのように考えたらいいかという、東芝に直接とは違ってきているので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"意見","question":"それも、では今そのホームページでどう書いてあるのだといったら、ほとんどは東芝発信だというお話だった。けれども、今その東芝から出ているものも巨樹の会がどう受けとめるかなどというのは事実としてわからないのであれば、区が把握している事実をちゃんと伝えて、だからどうなるという予想は、先ほども言ったようにしないと。それは厚生委員会の委員長として、その他のその他で受けるそんな話ではない。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":49,"id":"exchange-009"},{"speaker":"南委員","kind":"質問","question":"私は、厚生委員長である石田委員が今おっしゃったようなことは、やはり違うのではないかと思うし、私が言ったことは東芝に言えというつもりで言ったわけではないし、区民のそういういろいろな心配事を品川区議会でやはり受けとめて、どのようにあったほうがいいのかというところをちょっと議論して、適切なところに必要なものがあれば言っていく必要があるのではないかという趣旨で言ったので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"意見","question":"何度も言いますが、民間の話です。だから巨樹の会が、何科減らしてどういう科を増やすなど私は知らないですが、そういうのをホームページなり、それも東芝発だとかいろいろお話はあるみたいだけれども、行政が把握している部分をその他のその他でご説明するのであれば、それは逆に言えば議会だってホームページのとおりですと言うことしかないのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":51,"id":"exchange-011"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5264#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":15077,"voices":54}},{"id":"h30-20180223-3","meetingId":"h30-c-budget","date":"2018年2月23日","dateIso":"2018-02-23","committee":"予算特別委員会","time":"午前１１時１６分～午前１１時２２分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"たけうち副委員長","kind":"意見","question":"ただいまご推挙いただきました公明党のたけうち忍です。委員長をお支えしまして、実りある委員会にしてまいりたいと思いますので、どうぞよろしくお願い申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":10,"id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1070#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":1904,"voices":17}},{"id":"h30-20180226-6","meetingId":"h30-cm02","date":"2018年2月26日","dateIso":"2018-02-26","committee":"区民委員会","time":"午前１０時００分～午前１１時０２分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第１４号議案 品川区中小企業事業資金融資あつ旋条例の一部を改正する条例","agenda":"第１４号議案 品川区中小企業事業資金融資あつ旋条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"この小規模企業特別事業資金と創業支援資金について、先ほど、国の法律との整合を図る、国が２,０００万円まで拡大したのでというご説明がありました。国の法律と今回の拡充との関係をもう少しご説明いただきたいと思います。そこにも関わりますけれども、５号認定になりにくいという事情や実態というのはどういうことなのか。その点についても補足でご説明いただきたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"緊急資金のＰＲにつきましては、先ほど説明の本来想定し得ない大震災でありますとか、経済恐慌のレベルですので、その時々に応じて、例えば利率をどうするのか、要は制度設計をどうするのかというのは、時々に応じて最適なものを。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"緊急資金のことについて、１つ伺いたいのです。今回、上限を引き上げるということだけれども、今の説明ですと、その時々の状況に応じて制度設計を対応してくるというご趣旨なのでしょうか。例えば大きい災害であったり、いわゆる不況と言うよりも恐慌と言ったほうがいいのでしょうか、となってくると、今から想定しづらいですけれども、どういうことがその時々に応じて対応できる範囲なのか。","respondent":"山崎商業・ものづくり課長","answer":"そういうことを条例では規定しておりまして、いろいろな企業活動にとって致命的な状態になれば、それに応じた資金需要に応える制度を持って、最適に適用してまいりたいと考えています。","voiceIndex":7,"id":"exchange-002"},{"speaker":"田中委員","kind":"確認","question":"今の部分と幾つか重なる部分があると思います。そして、この事業の目的は、区内企業が事業を継続させることが目的なので、必要な事業で進めてほしいという立場なのですけれども、きちんとした貸付がされるべきだと思うので、少し確認させてください。２点です。」とあります。もしそうだとしたら、区の中のどういう立場の方が審査をするのかということを伺いたいので、そこを教えてください。","respondent":"山崎商業・ものづくり課長","answer":"通常、法人の事業所税などが適正な事業活動に伴って発生して、そうした税が未納ですと、それが１つの審査要件になりますので、貸出しができませんということをチェックさせていただいている状況にあります。","voiceIndex":9,"id":"exchange-003"},{"speaker":"田中委員","kind":"質問","question":"次に第５条のあつ旋手続なのですけれども「区長は、資金の融資あつ旋の申込みを受けたときは、別に定めるところにより審査し、適当と認める者については、速やかに取扱金融機関の融資について紹介するものとする。」とありますが、紹介された後に、金融機関は金融機関として通常どおり審査があると考えていいのでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"企業は、その紹介状を持って銀行に行かれて、銀行内部の必要なチェックを受けるということになります。それから、信用保証をつける場合については、保証協会に同様のチェックなり、確認をしていただくような流れがあって、それが全て完了して、融資が実行されるです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"田中委員","kind":"質問","question":"次なのですけれども、第６条から第８条についてです。」とあります。」としています。これは、第６条の融資については、区がより踏み込んだ調査をすることを前提に、金融機関は区長との協議によって審査をせずに融資を実行するという意味なのでしょうか。」とあるのですが、区長が必要だと認めた事業について、区内在住で何年ぐらい事業を行っているかなどの審査は、誰が行うのかということを教えてください。","respondent":"山崎商業・ものづくり課長","answer":"今、委員が引用していただいたところが、緊急資金の特例の部分です。先ほど申し上げたとおり、融資の実行に時間的なものを詰めるために、区が一定のリスク、保証協会の代わりになるような意味での保証をすることができるという規定になっているところが第８条であります。","voiceIndex":13,"id":"exchange-005"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"あえて、この２,０００万円の上限という考え方は、どういうところから来ているのかというのを教えていただきたいのが１つ。それと、融資の目的、使途としては、設備と運転資金ということです。最近は、若干設備投資も伸びてきたという数字もあるようですが、その辺の使われ方として、設備と運転資金ということで、この資金の借り入れの目的としてはどんな傾向にあるのか教えていただきたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"小規模企業特別事業資金の２,０００万円の考え方です。","voiceIndex":15,"id":"exchange-006"},{"speaker":"塚本副委員長","kind":"質問","question":"そういう投資系で、資金がたくさん必要で、中には２,０００万円では足りないという話、今のお話ですとそういう企業ばかりではないということでしたけれども、中にはあったりするのではないかと思うのです。そういうときに、この融資あっ旋の様々なメニューの中で、いろいろな対応がとれるようなところがあるのかどうか、最後にお伺いします。","respondent":"山崎商業・ものづくり課長","answer":"ご質問の趣旨も含めましてしっかり対応させていただいているところではありますが、さらに今回充実させてまいりたいと考えているところです。","voiceIndex":17,"id":"exchange-007"},{"speaker":"藤原委員","kind":"質問","question":"細かい平仮名のことなのですけれども、正式には「あっ旋」なのですか、「あつ旋」なのですか。と言うのも、条例は「つ」が大きいのですけれども、パンフレットでは「つ」が小さくて、今まで「あっ旋」と言っていたのですが、正式には「あつ旋」なのですか。","respondent":"山崎商業・ものづくり課長","answer":"「つ」の大きい、小さいということでは、条例で表記している「あつ旋」です。","voiceIndex":19,"id":"exchange-008"},{"speaker":"田中委員","kind":"質問","question":"議事録で、今のあっ旋を検索するとき、私も先ほど小さい「つ」で言ってしまっていたので、小さい「つ」にしないと検索にひっかかてこないということになりますか。「あつ旋」と訂正しなければだめですか。「あっ旋」でひっかかる。訂正しなくて大丈夫ですか。","respondent":"堀越地域振興部長","answer":"公式文書としての文字の残し方の大きさの違いだけだとご理解いただければと思いますので、よろしくお願いいたします。","voiceIndex":23,"id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"事業計画を見て、きちんと区がしっかりとしたアドバイスをしていただきたいなと思います。それで賛成です、必要な事業だと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-010"}]},{"id":"topic-02","title":"品川区文化芸術振興協議会準備会","agenda":"品川区文化芸術振興協議会準備会","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"今ご説明があったことですけれども、懇話会の中でそういう要望が出されて、協議会の設置に向けて準備が進められているというところですが、１点伺いたいのは、準備会の開催についてで、事前アンケートに取り組んでいるということです。その設問や内容など、この中身についてご説明いただきたいと思います。","respondent":"鈴木文化観光課長","answer":"事前アンケートの内容ですが、回によりまして若干異なるところがありますが、基本的には、ご説明をした協議会の考え方や概要、進め方についての基本的な質問。それと、何か各団体で今取り組んでいる、もしくは、これから取り組みたいという提案についてのご意見。","voiceIndex":37,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"そういう意味では、これを機会に、住民の皆さんが様々に取り組んでいる現状を把握したり、要望を伺ったり、活動をお互いに紹介したり、そういう取組みに発展できないかなと思ったのです。まだ準備会の段階ではありますが、今後の方向性についてお伺いしたいと思います。","respondent":"鈴木文化観光課長","answer":"ご質問にありました区民の方のいろいろな分野に関する活動です。特に文化センターなどを使いまして、日頃から活動していただいているサークルなど、そういう区民の団体の方がいらっしゃることは認識しております。１つは、最初のきっかけになる提案をいただいた懇話会。","voiceIndex":39,"id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"文化芸術ということなのですけれども、私の個人的な考えかもしれないのですが、この中にアニメや漫画というものも、私は文化芸術の中に入ると思っているのです。なので、品川区の観光大使はシナモロールがしてくださっているわけです。今後の展開として、その辺はどのように考えているのか教えていただけますか。","respondent":"鈴木文化観光課長","answer":"アニメや漫画等の分野の文化がここに入るかということですが、ご指摘のとおり、区としてはそういうジャンルも当然、文化芸術の１つだと考えております。","voiceIndex":41,"id":"exchange-013"},{"speaker":"渡辺委員","kind":"質問","question":"この組織構成のところで、率直に言うと行政の立ち位置はどのような形かなと思っています。エリアもそうですし、ジャンルもそうですし、そこではすごく長けていても、全区的な盛り上げのノウハウはおそらく別物だと思うのです。やはりそれに長けている情報をお持ちで、なおかつ連携がしやすいのは行政だと思うので、おそらく事務局機能的なことになると思うのですが、行政の関わり、立ち位置を教えてください。","respondent":"鈴木文化観光課長","answer":"区の大きな役割としては、各団体の個々の活動なり協議会全体の活動の支援と、その活動のための環境整備。この辺が大きな行政の役割になるかと考えております。","voiceIndex":43,"id":"exchange-014"},{"speaker":"渡辺委員","kind":"質問・要望","question":"そうすると、おそらくここの構成団体以外の地域のニーズや要望を拾い上げるのは、各団体というよりも行政がやるべきことかなと、情報をいろいろ拾える立ち位置にいるという中で、議会も含めて行政かなと思います。少し要望的になりますが、この協議会がまとまって行事を行う、一番下の協議会主催のイベントというのは相当なインパクトを残せる可能性を持っているのではないかと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-015"}]},{"id":"topic-03","title":"今定例会の一般質問にかかる所管質問ですが、今定例会の一般質問中、区民委員会にかかわる項目","agenda":"今定例会の一般質問にかかる所管質問ですが、今定例会の一般質問中、区民委員会にかかわる項目","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"文化スポーツ振興部長が答弁した案件ではないのですけれども、一般質問のときに教育委員会が答弁しました坂本龍馬の像について、たしか出たと思うのですが、改めてそこをお伺いしたいのです。あの坂本龍馬の像は、どういう背景で、区が設置したのか、または、どこかの団体が設置したのか。その辺の背景や、行政とのかかわり。その辺についてお伺いできれば教えていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-016"},{"speaker":"藤原委員","kind":"質問・要望","question":"すみません、その他でどうしても伺いたいのですが、昨日で平昌オリンピックが閉会しまして、これも個人的ですけれども、私は本当に感動させていただきました。その閉会式のテレビを見ているときに、どうしても明日の常任委員会で伺いたいなと思ったのです。ぜひお伺いしたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2802#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":17026,"voices":56}},{"id":"h30-20180226-7","meetingId":"h30-cm02","date":"2018年2月26日","dateIso":"2018-02-26","committee":"厚生委員会","time":"午前１０時００分～午後 ４時０２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を83件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第１９号議案 品川介護福祉専門学校修学資金貸付条例の一部を改正する条例","agenda":"第１９号議案 品川介護福祉専門学校修学資金貸付条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"修学資金貸付制度をどれぐらいの学生が利用されているかということについてお聞かせいただきたいのですけれども、学生の借りている割合、どれぐらいなのかということと、授業料相当が最大１４０万円の貸し付けとなっているのですが、これは年間の貸付額ということなのか、２年間なのか、そこのところを教えていただきたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"それから医療病床についても、転換先については、例えば新しいタイプの老人保健施設になるとか、いろいろな情報も出ていますけれども、可能性としてはあり得るというふうに考えております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"８７９名中６５０名ということなので、かなりの割合でこの修学資金を借りているのだなと思うのですけれども、この６５０名の借りた方で、３年以上勤務して返済全額免除、それから２年以上従事したのちに退職したという方はどれぐらいいるのか、割合でも結構なのですが、教えていただきたいと思います。医療型の療養病床というのは、区内にはどこがあるのかというところも教えていただけたらと思います。","respondent":"寺嶋高齢者福祉課長","answer":"それから２番目の区内にある医療型の療養病床、申しわけありません、手元の資料で恐縮ですが、医療施設では５カ所、今あるということで、ベッド数にして７４０床が区内にはあるという数字です。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"これから南品川もやっていく上で、やはり職員の問題というお話も先日出ておりましたので、私も両方お邪魔してきて、先方の話ではそのようなことも出ていますので、ぜひ区のほうからもその辺、直接薦められるわけではないけれども、奨学金と別にしても、将来の就学先ということで区内を薦められるように努力していただくよう要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-003"},{"speaker":"若林委員","kind":"質問・要望","question":"すみません。それで、同じくいわゆる指定障害者施設の実態です。３点目に、この介護福祉専門学校は介護福祉ということですけれども、こういう障害のある方についての勉強というのですか、講師はどういう方が教えていらっしゃるのかとか、研修とか、そういう、いわゆる障害のある方に対しての勉強の内容というのは、今どういうふうになっているのかということをお聞きしたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"一部免除の人の人数、２年以上は勤めたけれども３年は勤めずにやめられたということになってくると思いますけれども、一部免除者は２９名ということになってあります。","voiceIndex":12,"id":"exchange-004"},{"speaker":"若林委員","kind":"確認","question":"わかりました。障害のある方の施設への勤務ということで、免除は１４名ということで確認をしました。今後２年以上３年以下の方の数字もしっかり押さえていただいて、整理すれば出てくる数字だと思いますけれども、ご答弁できるようにしておいていただければなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-005"},{"speaker":"大倉委員","kind":"質問","question":"この条例に関しては結構なのですが、介護福祉専門学校の修学資金貸付で、品川区の福祉向上に寄与するという部分で非常に重要で、これからも進めていかなければいけないところなのかなと思っているのですけれども、この貸し付け６５０名のうち、全額免除が少ないのかなと感じるのですが、この辺というのは大きく言えば介護の部分で離職率が高いとか、さまざまな理由があると思うのですけれども。","respondent":"寺嶋高齢者福祉課長","answer":"こちらとしては必ずしも本意ではないのですけれども、とりあえず職業の１つとしてチャレンジしてみるということで学校を受けてみたけれども、やはり通ってみてちょっと自分の思っていたものとは違ったと、そもそも就職しなかったという方もいらっしゃるということで。","voiceIndex":16,"id":"exchange-006"},{"speaker":"大倉委員","kind":"質問・要望","question":"そもそも就職しなかった、学校を途中でやめられた方もいるというところで、その辺の人数がわかれば教えていただきたいのと、課長の答弁にもありましたが、皆さんに貸し付けを受けてもらって、皆さんに就職してもらうのが一番だというところでいうと、やはりこの理由というか、就職したけれども品川区で全額免除にならなかった人たちがこれだけいるというところは、難しいというお話もありましたけれども。","respondent":"寺嶋高齢者福祉課長","answer":"ご指摘のとおり、最終的に全額免除に至らなかった方の理由につきましては、学校とも協力して実態の把握には努めていきたいと思います。","voiceIndex":18,"id":"exchange-007"}]},{"id":"topic-02","title":"第２０号議案 品川区介護保険制度に関する条例の一部を改正する条例","agenda":"第２０号議案 品川区介護保険制度に関する条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この介護保険料の第１号被保険者の保険料負担割合が２２％から２３％に変更になるということなのですけれども、この２２％から２３％になるというのは、どのようにして決まるのかというのを教えていただきたいのです。","respondent":"寺嶋高齢者福祉課長","answer":"いずれにいたしましても、これは厚生労働省からのこういった通知により、２３％になるといったことを踏まえて品川区としましては必要量を見込んで今回の保険料に反映させるという、そういう流れがあります。","voiceIndex":31,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先日ほかの区のところにお話を伺ってきたのですけれども、そこのところも必要なサービスをしっかりと受けていただくというのとあわせて、やはり事業者を守っていくというのも区の役割だというようなことでも言われたのですが、そういう観点からも、私はぜひ総合事業の単価引き下げはやめて、介護報酬まで戻してほしいということを改めて要望しておきたいと思います。第七期というのは。","respondent":"寺嶋高齢者福祉課長","answer":"それから総合事業に移せるものが特別給付の中にあるかどうかというところにつきましては、基本的にその他のものでできないものを市町村特別給付で行っているという認識でいますので、今のところ、現在行っているものはそのままというふうに考えていますけれども、また実際に今。","voiceIndex":33,"id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回は保険料基準額が月額５,３００円から５,６００円に上がったわけですけれども、そういう中で基金の取り崩しについて伺いたいのですが、代表質問で我が党がこれを質問したときに、基金の取り崩しは８億２,５９０万円だという答弁がありました。","respondent":"寺嶋高齢者福祉課長","answer":"１点目の減らした額なのですけれども、実際に先ほどの１０％、５％というのも比率の問題で、保険料、それからサービス料の見込みとしましては、そういったもろもろの条件設定をした上で総額として決めていきますので、決算の段階になれば実際に２割負担の方。","voiceIndex":35,"id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"どれだけ給付費を減らすことにつながるのかという、決算ではなくて予算上でいいので、その辺のところがわかったら教えていただきたいと思います。それと、一番初めの骨子案のときには、５,５００円から５,６００円というふうに見込み額を出されたと思うのですけれども、それが５,６００円となった理由はどういうことなのかということについてもお聞かせください。","respondent":"寺嶋高齢者福祉課長","answer":"実態がどうなるかというところはなかなかつかみづらいので、反映できないということで、決算にならないとある程度正確な数字が申し上げられないということで、先ほど言った１０％、５％というのは、平成３０年度予算を編成する際にそういう数値をベースにして給付額を見込んで。","voiceIndex":37,"id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１１億５,０００万円もですから。そういうことからすると、８億円ではなくて１１億５,０００万円、前と同じだけ引き下げれば５,５００円にもできたのではないかなと思うのですけれども、なぜ前回と同じようにしなかったのか、残りの残額にしても前回よりもたくさん残るということにしたのかということについてもお聞かせいただきたい。","respondent":"寺嶋高齢者福祉課長","answer":"そのあたりは見込んで、前回のときの見込みと今回の見込みでいろいろな数字がまた変わってきて、今一番新しい情報をもとに見込んだところがこういった数字になっているということで、ぜひご理解いただきたいと考えています。","voiceIndex":39,"id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"基本的に介護保険料というのは年金から天引きですよね。それで説明会について、ずっと私は求め続けているのですけれども、説明会はやらないというのが品川区の方針でずっとされないのですが、隣の港区は地域保健福祉計画と障害福祉計画とを合わせてなのですけれども、介護保険の第七期のこの計画に対しても、昼夜時間を変えて、区民が参加しやすいようにということで、１０回説明会を行っているのです。","respondent":"寺嶋高齢者福祉課長","answer":"介護保険料の段階設定がたくさん分かれていて、所得に応じて払いやすいのがいいという肯定的なご意見もいただいたのと、それから直接の制度そのものというよりは、予防とかの事業で継続してその事業に参加したかったけれども。","voiceIndex":41,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"やはりこのパブリックコメントが６件というのは、決して多い数字ではないと思うのです。私はそういう意見も吸い上げるような、そういう姿勢というものをぜひ持っていただきたいと思いますので、改めて説明会は今後ぜひ持っていただきたいということで申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-014"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"総合事業を進めることで給付費を抑えるというのが国の目的でもあったと思うので、そこはわからないのでしょうか。","respondent":"寺嶋高齢者福祉課長","answer":"給付費が抑えられたという、その記述の資料ですが、こちら側でお伝えしたかった内容としましては、総合事業に移行するときに、例えばデイサービス等々につきましても、自分で通える方は送迎が要らないであるとか、それから長時間も必要ない方が短時間でおさまったとかいうことで。","voiceIndex":45,"id":"exchange-015"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"ではそういう趣旨であれば、どれだけ抑えられたかというのはわかるということなのでしょうか。","respondent":"寺嶋高齢者福祉課長","answer":"利用者数であるとか、そういったものについてはあれですが、今幾ら金額が変わったかという、総合事業を実施したときとしないときとの比較、そこまでの数字というのは、申しわけありませんが、持ち合わせておりません。","voiceIndex":47,"id":"exchange-016"},{"speaker":"若林委員","kind":"質問","question":"(2)の所得指標の見直しの部分は、これは今回東日本大震災等に関連して、この租税特別措置法に規定される内容によってということで保険料が算定をされるということで、品川区民にとっての影響はどのように予想、押さえておられるかということをお聞きしたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"この特別控除による区内、区民の方への影響ということですが、これについてはなかなか実績が出てきた段階でないとわかりにくいのですけれども、対象となり得る数字ということで、２０１７年１２月末現在の数字を出してみたのですが、被保険者数が８万２,０００名を超える中で。","voiceIndex":50,"id":"exchange-017"},{"speaker":"若林委員","kind":"質問・要望","question":"この説明書と条例で、本当にこういう金額になりましたということを示す、ある意味ではだけのお話ですので、その辺はちょっとご説明いただきたいと思います。介護保険事業の制度推進委員会というものがありますけれども、あのようなところとこの保険料決定についての関係、関連性というのは何かあるのかないのかということも確認をしておきたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"あの数字から最後の細かな詰めは当然この後も、今もずっとやってきたところではありますが、ご指摘のとおりそこが１つのご説明のポイントだと認識しています。","voiceIndex":52,"id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"確認","question":"もし聞き漏らしていたら申しわけありません。他区の状況とか、他市町村、その辺の状況をちょっと確認だけさせてください。","respondent":"寺嶋高齢者福祉課長","answer":"ちなみに第六期も安いほうから３番目だったのですが、上位区の入れ替わりは若干あるようですけれども、結果的に今、最新情報では３番目におさまっているです。それから軒並み６,０００円を超える自治体がかなり出てきているという情報も聞いております。","voiceIndex":55,"id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"反対です。本当に高齢者の皆さんも大変な中でやっていて、保険料の値上げに対してはこれ以上大変な実態というようなところがあると思いますので、反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":60,"id":"exchange-020"}]},{"id":"topic-03","title":"第２２号議案 品川区指定地域密着型介護予防サービスの事業の人員、設備および運営ならびに指定地域密着型介護予防サービスに係る介護予防のための効果的な支援の方法の基","agenda":"第２２号議案 品川区指定地域密着型介護予防サービスの事業の人員、設備および運営ならびに指定地域密着型介護予防サービスに係る介護予防のための効果的な支援の方法の基","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この条例が本当に複雑で、理解するまでに本当に大変だったのですけれども、ちょっとまだ理解も正確かということもあるのですが、改めてさらにきちんと理解するためにも教えていただきたいところが何点かあります。この共生型サービスで、どのようなサービスがどのように変わるのかというところをまず教えていただきたい。","respondent":"寺嶋高齢者福祉課長、中山障害者福祉課長","answer":"共生型、どういったものがということですけれども、まず考え方としましては、今現在障害福祉制度の生活介護等を受けている方が６５歳になったときに、介護保険適用ということで高齢者のサービスのほうに移ってくださいといった。そのほか民間の事業所も今は増えておりますので、合わせますと児童発達支援が１２カ所、放課後等デイサービスが１２カ所というような状況です。","voiceIndex":67,"id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、生活介護や自立訓練は、６５歳を過ぎてもその障害者の施設に通い続けることができるように共生型サービスの指定を受けるということなのですけれども、現在、生活介護、また自立訓練で６５歳を過ぎた方というのはどうなっているのか、デイサービスに機械的に移るという状況になっているのか、それが移らなくても済むというようになるのか、その辺のところ。","respondent":"中山障害者福祉課長","answer":"ただし、就労継続支援Ａ型だけは雇用契約を結ぶ関係があるので、６５歳までということにさせていただいているのですが、ほかの通所のサービスについては、６５歳を過ぎてもその方の状態像に応じて通い続けていただいている現状があります。","voiceIndex":70,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、生活介護ですとか、自立訓練というのは何となく想像がつくのですが、児童発達支援とか、放課後等デイサービスが、この共生型サービスを受けたことでどう変わっていくのかというあたりが、いま一つ想像がつかないので、共生型サービスをこの２つが受けることで、サービスそのものがどう変わってくるのかということについてもお聞かせいただきたいと思います。","respondent":"中山障害者福祉課長","answer":"それから自己負担が変わるということになります。これは介護保険の適用になれば１割負担になることは、この間もご説明をさせていただいておりました。","voiceIndex":72,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうしますと、多分ホームヘルプなどだったら、６５歳になったら介護保険優先ということで、介護保険のほうに移ると思うのです。生活介護とデイサービスとでは、多分基準もそれぞれ違うと思うのですけれども、そういうものが共生型サービスをとることによって、基本的には今までの障害者の同じ基準のまま、平米数も人員配置もそのままで、共生型サービスをとるということになるのでしょうか。","respondent":"中山障害者福祉課長、寺嶋高齢者福祉課長","answer":"今私、障害福祉サービスのほうの報酬の改正を見ているのですが、例えば生活介護であれば、その支援区分によって１日当たりの単位数が違うのですけれども、この共生型サービスというのは１型、２型という２種類しかないので。障害者サービスのほうから共生型の介護保険適用の事業者の指定を受けた場合の報酬ですけれども、今示されている内容として、やはり設備基準が圧倒的に介護保険側のデイサービスのほうが厳しいというところを踏まえてだと思われますが。","voiceIndex":74,"id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区として考えられる課題というものがあったら、その点についてもお聞かせいただきたいと思います。１割負担の償還払いなのですけれども、一定の基準を満たすと、ということで言われていると思うのですが、要支援の、特に軽度の方はここの対象にもならないというふうにも聞いたのですけれども、その辺のところもわかったら教えてください。","respondent":"中山障害者福祉課長","answer":"それで、まだ償還のほうの話については具体的なものが見えていないので、この一定程度以上の障害支援区分というところがどの程度かということで、その要支援の方が対象になるかどうかというのは今後見えてくると考えています。","voiceIndex":77,"id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう本当にこの制度、すごく理解するまでに私難しくて、いろいろ見てみたのですけれども、社会保障審議会の障害者部会でもずっとこの件についても話し合いがされていて、その中でもいろいろな委員の方が、すごく心配というか、障害の方は一人ひとり個別性が高いではないですか。個別性も強いし、障害の種別もある。","respondent":"寺嶋高齢者福祉課長","answer":"ただ、今度指定地域密着型のほうは品川区が指定をするという権限がありますので、いかなるタイミングで相談にいらっしゃったときでもきちんと対応できるように、今私をはじめスタッフ、職員のほうは情報収集に努めて、そういった動きについても注視しているといった状況です。","voiceIndex":79,"id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それから２(1)3)の定期巡回のところで確認なのですけれども、資料を見ていると定期巡回の地域へのサービス提供のところで、地域の利用者に対してもサービス提供を行わなければならないと明確化すると。前のときは行うよう努めなければならないとなっていたところが変わってくるのですが、これ現状では、やはり今までもこの辺はサービスはされていたのかどうかという点が１点です。","respondent":"寺嶋高齢者福祉課長","answer":"それから身体拘束につきましては、それぞれ取り扱いについては、基本的にほとんどの入居施設において取り扱い方針を定めておりますけれども、その辺も全国統一で、やっていないところもあればということも含めてだと思うのですが。","voiceIndex":82,"id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"質問","question":"指針はどのように捉えたらいいですか。区としては直接何かチェックするということではなくて、決まっているもの、でき上がっているものをつくれというだけでその内容に関してはタッチしていかないという感じなのですか。","respondent":"寺嶋高齢者福祉課長","answer":"実際には今あるものということなのですけれども、区としてのかかわりとしては、当然指定権限、それから調査の権限等がありますので、それぞれの施設で余りにも差がついているということは望ましいと思っておりませんから、この指定事業者の指導等の際には。","voiceIndex":84,"id":"exchange-028"},{"speaker":"若林委員","kind":"質問・要望","question":"今度条文の意味、条例ですのでちょっと聞いておきたいと思います。第５９条の２０の２の一番下、ページでいうと６ページのほうです。それから(2)の、「利用者に対して適切なサービスを提供するため、指定地域密着型通所介護事業所その他の関係施設から必要な技術的支援を受けていること」というのは、どういう規定なのか、どういうことを意味しているのか、内容を確認します。","respondent":"寺嶋高齢者福祉課長、中山障害者福祉課長","answer":"１番目のご質問の定期巡回の部分、規制緩和ということですけれども、こちらは現在１社が対応しているといった形にはなっているのですが、特にこの(1)番の定期巡回には訪問看護という機能も備わっておりまして。そういう中での指導ですとか、連携のあり方というのは、これからもう１度つくっていかなければいけないところだとは思っているのですけれども、それぞれ所管がありますので、まずは所管の連携を密にして。","voiceIndex":87,"id":"exchange-029"},{"speaker":"浅野委員","kind":"質問・要望","question":"私のほうからは２点ほどお伺いできればと思いますが、１つは(5)認知症対応型共同生活介護というところですけれども、身体的拘束についての項目が出ているのですが、保護するための緊急的なものであって、そうでない場合を除いて禁止をされているというふうに出ています。","respondent":"寺嶋高齢者福祉課長","answer":"福祉カレッジもありますので、改めて区のほうもどういった形で、何か寄与できるものがあるかということについて、前向きにというか、積極的に検討していく必要があろうかと考えているところです。","voiceIndex":91,"id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この論点も、さまざまな心配事が解消されるというところまでいっていないのではないかと思いますし、障害者自立支援法の国との和解の基本合意からしても、応益負担の廃止というようなことを約束したわけですから、利用料ゼロがなし崩し的になくされていくという一歩にもなっていくのではないかなと思っていますので、今回のこの条例に対しては、２本とも反対ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-031"}]},{"id":"topic-04","title":"第２３号議案 品川区指定介護予防支援等の事業の人員および運営ならびに指定介護予防支援等に係る介護予防のための効果的な支援の方法の基準等に関する条例の一部を改正す","agenda":"第２３号議案 品川区指定介護予防支援等の事業の人員および運営ならびに指定介護予防支援等に係る介護予防のための効果的な支援の方法の基準等に関する条例の一部を改正す","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"初めに、指定介護予防支援等となっているのですけれども、ここの指定介護予防支援等というところは具体的にどういう事業者なのかということをお聞かせいただきたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"こちらの指定介護予防支援等というのは、いわゆる居宅介護支援の予防に関する部分ということで、居宅介護支援事業者の予防部分、いわゆる要支援等に関するケアマネジメントを行う事業所が対象となっております。","voiceIndex":106,"id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"居宅介護支援事業所の予防をやるというところということだと、具体的なところでは在宅介護支援センターのほかにも、民間の居宅介護支援事業所でも予防介護、予防のケアプランをつくっているということになっていくのか、もしもそういうことであれば、予防のケアプランをつくっている民間のところというのは何カ所ぐらいあるのか、そこの点についてもお聞かせください。","respondent":"寺嶋高齢者福祉課長","answer":"は２０の在宅介護支援センター以外に、民間の居宅介護支援事業者はありますけれども、いわゆる介護予防については地域包括支援センターの機能ということなので、予防のプランをつくっているのは２０の在宅介護支援センターということになります。","voiceIndex":108,"id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この品川区の指定介護予防支援等の、もともとの条例を見たのですけれども、第２章の「人員に関する基準」というところで、「従事者の員数」というところがあるのですが、そこに「指定介護予防支援事業者は、当該指定に係る事業所ごとに１以上の員数の指定介護予防支援の提供に当たる必要な数の保健師その他の指定介護予防支援に関する知識を有する職員を置かなければならない」と書いてあるのですけれども。","respondent":"寺嶋高齢者福祉課長","answer":"品川区に関しましては、指定自体は１カ所、品川区が指定を受けているということなので、この規定はそういった形になります。先ほど申し上げた２０の在宅介護支援センターは、機能を地域に分担しているということなので、品川区内での指定事業者は１ということになります。","voiceIndex":110,"id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"この第４条の指定介護予防支援事業者というのは、品川区の地域包括支援センターということで捉えていいのかということの確認をお願いしたいのと、それからあと(3)の障害福祉制度の相談支援専門員との密接な連携というのは、「ケアマネジャーと障害福祉制度の相談支援専門員との密接な連携を促進するため、事業者間での連携に努める必要がある旨を明確にする」ということなのですけれども。","respondent":"寺嶋高齢者福祉課長","answer":"それから(3)の障害福祉制度の相談支援専門員との密接な連携というのが今回明文化されたということは、従来までは、先ほど申し上げたとおり連携先として医療機関や介護事業者等が条文上列挙されていたのですけれども。","voiceIndex":112,"id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"こうやって地域包括で高齢者のケアプランも障害者のケアプランも一緒につくっていくという意味合いというのも、ここにはあるのでしょうか。そういうような方向も、多分いろいろなところで言われていると思うのですけれども、この中には、その意味合いでこのように出されているのか、そこの点についてお聞かせください。","respondent":"中山障害者福祉課長","answer":"ただ、やはりなかなか双方の法の理解がないと、例えば介護保険のケアマネジャーは障害のサービスがわからない、障害のほうも介護保険のサービスがわからないということになってしまいますと、そこの連携がうまくいかないためにサービスの調整であったり。","voiceIndex":114,"id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"地域包括でケアプランをつくるときに、高齢者、介護保険のほうでもすごい複雑な仕組みですけれども、それに加えて障害者のほうのケアプランもつくるとなると、障害者の仕組みそのものもまた複雑で、両方というのはすごい大変だという意見はお聞きしているところなのですが、ここのところはとりあえずそういう地域包括でケアプランも全部受け入れますよということではなくて。","respondent":"寺嶋高齢者福祉課長","answer":"あくまでも地域包括でつくのは介護保険上の予防のケアプランということになっております。","voiceIndex":116,"id":"exchange-037"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"今の質問のところの指定介護予防支援等というところは、居宅の介護予防支援事業所、要は在宅介護支援センターということで、それでこの指定を受けているのは品川区の庁舎内の地域包括支援センターだとおっしゃったのですけれども、そうすると在宅介護支援センターはこの指定を受けていないということなのですか。そこをちょっとお願いします。","respondent":"寺嶋高齢者福祉課長","answer":"地域包括支援センターの指定を受けているのは、まず品川区が１カ所ということで、従来基幹型、統括型の在宅介護支援センターと、それからあと２０の在宅介護支援センターということで１つの連携を持ってやっていたのですけれども、指定が１カ所で。","voiceIndex":119,"id":"exchange-038"}]},{"id":"topic-05","title":"第２４号議案 品川区指定居宅介護支援等の事業の人員および運営の基準等に関する条例","agenda":"第２４号議案 品川区指定居宅介護支援等の事業の人員および運営の基準等に関する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは品川区が指定することになるということで、今まで都がやっていたものが横引きされてきたというものだと思うのですけれども、改めて先ほどの第２章の人員に関する基準というところで、１人のケアマネジャーが何人くらいのケアプランをつくっているのかというところで、もう１回基準を教えていただきたいのと、それから在宅介護支援センターで今多分７５％ぐらい作成していると思うのですけれども。","respondent":"寺嶋高齢者福祉課長","answer":"品川区の在宅介護支援センターも同基準に応じてやっているところです。","voiceIndex":131,"id":"exchange-039"}]},{"id":"topic-06","title":"第２５号議案 品川区立高齢者多世代交流支援施設条例の一部を改正する条例","agenda":"第２５号議案 品川区立高齢者多世代交流支援施設条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それからこれの図面を見ると、屋上のところに太陽光パネル６キロワットとあるのですけれども、これは蓄電池もあるということで、停電時にいろいろ使えるというのはとてもいいなと思ったのですけれども、このように太陽光パネルと蓄電池をセットで設置するというのは初めてだったでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":145,"id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ゆうゆうプラザは、これで４カ所目ですよね。今までのゆうゆうプラザというのは、委託ではなかったですか。指定管理者だったのでしょうか。今までが委託だったのか、指定管理者だったのか、そこを教えてください。","respondent":"松山高齢者地域支援課長","answer":"これまで指定管理者で運営しているところは、平塚橋のゆうゆうプラザで三徳会が運営しております。そのほかのところは委託になっております。","voiceIndex":148,"id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"だからそういうようなところは指定管理者というのはあるかなと思ったのですけれども、でも今までのほかのところは、大崎にしても、大井にしても、委託というところで、今回指定管理者で公募する、私はこのやり方のほうがいいのではないかと思いますけれども、そのように指定管理者で公募するという方針に変えたのはなぜかということと。","respondent":"松山高齢者地域支援課長","answer":"今後シルバーセンターが老朽化により改築、建て替えなどをする際にはゆうゆうプラザへの転換を図っていくのですが、その際の施設運営につきましても、どういった機能をゆうゆうプラザに持たせるかという時点で、指定管理者にするか。","voiceIndex":150,"id":"exchange-042"},{"speaker":"若林委員","kind":"質問・要望","question":"何点か。２方向避難が１階部分で見てとれると思うのですが、ここはたしか民地に出るようなところなので、近隣の方とのご理解、ご協力はどのような話し合いになっているのかということを１つ。動線についても、高齢者と保育の施設が、別々にされているということで、多世代交流とこういうしつらえの考え方というのですか、合理性というのか、整合性というのか、その考え方をお聞かせいただきたいと思います。","respondent":"松山高齢者地域支援課長","answer":"近隣のほうにはご理解いただけるよう、直接お伺いをして説明しています。それから２点目の多世代交流の部分ですけれども、構造上、こちら狭い敷地の中での複合施設ということなので、入り口をどうしても別々にせざるを得なかったのです。","voiceIndex":153,"id":"exchange-043"}]},{"id":"topic-07","title":"第２６号議案 品川区立高齢者住宅条例の一部を改正する条例","agenda":"第２６号議案 品川区立高齢者住宅条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この賃貸借契約なのですが、３０年の契約が終わったということでしたか。何年契約だったのかと、今回新たな契約というものが何年の契約になるかということをお聞かせください。そのところというのは区が決めるわけですよね。そこのところは区がそういうように決めればできることなのか、そしてそれであればぜひやっていただけないかなと思うのですけれども、いかがでしょうか。","respondent":"松山高齢者地域支援課長","answer":"これまでのカガミハイツの契約期間は１０年でございました。今後、新たに結ぶ締結はまた引き続き１０年ということで考えております。","voiceIndex":165,"id":"exchange-044"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"高齢者住宅はシルバーピアというのはわかるのですけれども、その住民税非課税の方の減免されたときの部屋代というのは、区として決めることができるのかということを教えていただきたいです。そのようなことでできるのであれば、本当に高齢者の大変な状況というのがあると思うので、そこに半分でも回していただくというふうなことは可能なのかどうなのかということでお聞きしたいです。","respondent":"松山高齢者地域支援課長","answer":"それぞれの方々については、先ほども申し上げましたとおり福祉的な意味合いから前年の所得に応じて減額を図っておりますので、今のところ特にこれ以上ということは考えておりません。","voiceIndex":167,"id":"exchange-045"}]},{"id":"topic-08","title":"第２８号議案 品川区後期高齢者医療に関する条例の一部を改正する条例","agenda":"第２８号議案 品川区後期高齢者医療に関する条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今までは住所地特例ではなく所在地の後期高齢者医療広域連合に加入していたということだと思うのですが、なぜ今までそうだったのかということをお聞かせください。","respondent":"三ッ橋国保医療年金課長","answer":"ただ国保の方が後期に移った場合の住所地特例が引き継がれていなかったという状況がございましたので、今回はそれを引き継ぐということで法律の改正がされたという趣旨です。","voiceIndex":188,"id":"exchange-046"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"国保から後期高齢に移った人だけが、所在地の後期高齢者医療広域連合の方に行ってしまうということになっていて、もともと後期高齢だったら、そのまま引き継がれていたと。今回、国保の人が他道府県の住所地特例施設等に行って、後期高齢になったときに住所地特例となるということですね。わかりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":190,"id":"exchange-047"}]},{"id":"topic-09","title":"第２９号議案 品川区住宅宿泊事業の適正な運営の確保に関する条例","agenda":"第２９号議案 品川区住宅宿泊事業の適正な運営の確保に関する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"提案","question":"は多分自治体によっては、ずっと検討委員会などをつくって検討を重ねた上で提案をするだとか、そういう形にして議会のほうにも随時報告をしながらというところが多いのではないかなと思うのですが、そんな中で今日突然このような重要な条例が、厚生委員会の中で初めて出されたという進め方は問題なのではないかと思うのですけれども、その点が１点です。","respondent":"井浦品川区保健所生活衛生課長","answer":"この法律が昨年の６月に成立いたしましたが、そのほとんどの内容的な部分が政省令、さらに細目を定める要領に委任されているという仕組みの中で、最終的な実態が明確になったのが昨年の１２月末であるという形で、私ども地方公共団体の担当が受ける情報量。","voiceIndex":201,"id":"exchange-048"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"そういう点では条例を決めるのはこの厚生委員会であることがわかっていたのですから、少なくとも、総務委員会で議論した、そういう時期に、私は厚生委員会の中でもぜひ提案していただきたかったなと思っています。その点お聞かせください。つかんでいるのでしたら何件ぐらいあるのか、それに対して苦情、品川区に対して苦情があるのかないのか、その点についてもお聞かせいただきたいと思います。","respondent":"井浦品川区保健所生活衛生課長","answer":"それから民泊のサイト、Ａｉｒｂｎｂ等々の、いわゆる無許可民泊の件数のお尋ねですが、こちらもＡｉｒｂｎｂのサイトについてはご承知かもしれないのですけれども、利用者として正式に登録してログインをしないと住所等がわからないというような仕組みになってございまして。","voiceIndex":203,"id":"exchange-049"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"カード払いが確認されるまでは詳細な住所や鍵の受け渡し方法はわからない。マンションの規約で自分たちのマンションで民泊はやりませんということをマンション全体で決めることができれば、区としてはそのマンションは民泊としては登録しないとお聞きしたのですけれども、少し今の説明ではどこの条文にどうあるのかというのがよくわからなかったので、そこのところもお聞かせいただきたいと思います。","respondent":"井浦品川区保健所生活衛生課長","answer":"１点目の警察と連携をした違法是正の件数は何件かですが、件数的には三、四件です。","voiceIndex":205,"id":"exchange-050"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"多分、台東区は区の条例で従事者の営業時間中の施設への常駐というのを定めているということで見たのですけれども、本当にこのような、どのような人が来るかわからないというところで、誰もチェックする仕組みがないという状況については、ぜひ区でやはり厳しく規制するためにも、従事者の営業時間中の施設への常駐。","respondent":"井浦品川区保健所生活衛生課長","answer":"民泊サイトで宿泊客を募集するには、区の窓口で適法に届出を行い、届出番号を取得するという形で運営することになりますので、その関係で届出がされていないものについては現行の民泊サイトから次々に削除されると見込んでいるところです。","voiceIndex":207,"id":"exchange-051"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そのようなことだったら、何かあったときにどうにもならないのではないのかなと思ったのですが、品川区の場合は、東京都のガイドラインとは違って、常駐というふうになっているのでしょうか。それから今、近隣商業地域と商業地域は１８０日ですよね。私は住居専用地域は民泊ゼロ地域ということにぜひしていただきたいと思うのですが、その点についてもお願いいたします。","respondent":"井浦品川区保健所生活衛生課長","answer":"それから３点目の住居専用地域については、ご指摘のとおり旅館業は建てられませんけれども、品川区ではこちらの条例の提案のとおり規制しますと、土日以外は民泊ができませんので、土日だけの宿泊というところで。","voiceIndex":209,"id":"exchange-052"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"利益目的の民泊ではないとなると、何目的になるのですか。それはどのような形でされるのかということと、それからあと、７日以上の連泊になった場合には定期的に面会するということですけれども、これ誰がどのような形で面会するということになるのでしょうか。マンション全体に貼るわけにはいかないし、部屋に貼ったらわからないし、そのようなところはどう考えているのかについてもお聞かせください。","respondent":"井浦品川区保健所生活衛生課長","answer":"それから２点目の衛生管理については、私ども保健所の本来の仕事ですので、定期的な清掃、換気、寝具貸与等々については、まず届け出を受け付けるときにガイドラインを説明いたしまして、宿泊者が変わるごとに変えてもらわなくてはいけないものですとか、さまざまな細かいところ。","voiceIndex":211,"id":"exchange-053"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"まだマンションではそういう規約を決めていないけれども、民泊は始まってしまって、その後、マンションで民泊禁止にしようと多数決で規約が決まったら、そのときまで民泊をやっていたところを禁止するというふうなことも可能なのでしょうか。その辺のところの手続がどうなるのかということについてお聞かせください。","respondent":"井浦品川区保健所生活衛生課長","answer":"それから万一、一度マンションの規約で民泊を了承した後に、やはり改めたいということについては、管理規約の変更の決定をしていただく、あるいはそれが間に合わないのであれば、総会や理事会等で協議をしていただくというような形でプロセスを経れば。","voiceIndex":213,"id":"exchange-054"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"ということは、マンションでまだ決めていないから了承できないと言われたときには、民泊を区のほうで認めるということにはならなくて、マンションで規約としても民泊を了承している。それがない限りは民泊は認められないということで考えていいということでしょうか。確認をお願いします。","respondent":"井浦品川区保健所生活衛生課長","answer":"その前段として、品川区内には１,６００ほど分譲のマンションがございまして、１月末に管理規約でしっかりとお定めくださいというような趣旨の文書を郵便で全管理組合にお送りしていますので、まだ定めていないところについては。","voiceIndex":215,"id":"exchange-055"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今の質疑の中で、苦情がたしか２２件あるとおっしゃったのですけれども、その主なものをちょっと教えていただきたいと思います。","respondent":"井浦品川区保健所生活衛生課長","answer":"警察とも連携しまして現地に立ち入る、あるいは警察を通して事実関係を確認するというような形で対応しまして、私ども保健所サイドとしましては、まずマンションのオーナーに連絡をしまして、賃貸人が無断でそのようなことを行っているということになると契約違反になりますので。","voiceIndex":218,"id":"exchange-056"},{"speaker":"鈴木（真）委員","kind":"質問","question":"民泊をやっているというだけではなくて、具体例としてのクレーム、はっきり言うと自分も何件か、何回も聞いたことがあるのです。ごみの問題というのが一番大きな問題で。ですから地域の方はいつもそういうものを見ていると思うので、もうちょっと具体例として、それをどう対応していったかということをもう１回教えていただけますか。","respondent":"井浦品川区保健所生活衛生課長","answer":"先ほどの苦情の内容の中で、私ども保健所に一番多い件数が、民泊をやめさせたいという相談で十数件ございました。ごみ出しについては３件ございまして、清掃事務所とも連携し、しっかりと巡回指導等も含めて行っていただき、是正に取り組んでいるというようなところです。","voiceIndex":220,"id":"exchange-057"},{"speaker":"鈴木（真）委員","kind":"質問","question":"もちろんこの条例の中で見てはいるのでしょうけれども、もっと細かいところがこれから出てくると思うのですが、その辺の課題があったら教えてください。","respondent":"井浦品川区保健所生活衛生課長","answer":"今後の課題というところにつきましては、やはり現地への、訪問指導、あるいは立ち入りケースというようなところがまず一番大事なところですので、どれだけ件数が出てきて、私どもの職員体制でやっていけるのか、あるいは一定の、権限の行使は私どもが行いますが。","voiceIndex":222,"id":"exchange-058"},{"speaker":"鈴木（真）委員","kind":"意見","question":"今お話あった指導体制、訪問指導とか立ち入りという話も課題だなと思って、区としてどこまでそれが権限を持って、またその違法なものに対して指導だけで済んでしまうのか、それ以上のものはないのか。それと言ったきりではなく、取り消しをすることがそこでできるのかどうか、そこまでこの規定、条例に入ってくるのかどうか、それが見えなかったのでそこを。","respondent":"井浦品川区保健所生活衛生課長","answer":"それから２つ目としましては、違法な民泊については旅館業法の刑罰規定が適用されるという仕組みになってありますので、こちらも警察が場合によっては逮捕、勾留をして刑事手続、刑罰の手続で対処するというような最終的な手段も整備されてまいりましたので。","voiceIndex":224,"id":"exchange-059"},{"speaker":"鈴木（真）委員","kind":"確認","question":"わかりました。それと最近簡易宿所の申請、看板がかかっているのを何カ所か見かけています。確認なのですが、あれは届け出して何か表示がされるのでしたか。というのは、地域の方からすると、そこに宿泊者が入っているのと民泊の部分の区別がつかないというか、余り歓迎されない部分の中で、その辺をどう見ていったらいいのかと。","respondent":"井浦品川区保健所生活衛生課長","answer":"営業者に対しては私どもこの標識というのは地域に説明をするための標識なので、問い合わせ等については誠実に対応していただくようにというようなことを、要綱に基づいて指導しています。","voiceIndex":226,"id":"exchange-060"},{"speaker":"鈴木（真）委員","kind":"質問","question":"事前看板は出ているのはわかるのですけれども、その事前看板が終わってというか、立ち上がって、その後に簡易宿所ですという表示が出てくるのかどうかということです。ここにいう周知というのはどういう形の周知をすればいいのか、それも教えてください。","respondent":"井浦品川区保健所生活衛生課長","answer":"こちらについては、やはり民泊を行おうとする届出住宅の近隣の一定のエリアの地域につきましては、例えばポスティングによる説明資料の戸別配付を行う等、周辺の地域の方に対して意見の申し出方法ですとか。","voiceIndex":228,"id":"exchange-061"},{"speaker":"鈴木（真）委員","kind":"確認","question":"それからもう１点、今１０メートルと聞いたけれども、その１０メートル範囲の説明会、本当に近くですが、やったかどうかという確認もその申請のときに、これには記録を作成するということは書いてあるのだけれども、その辺の本当にやったかのチェック、やはり後々そういうことでクレームが相当ついてくるのがこの辺にあるのではないかなと思うのですが、そこの点をもう１回お願いします。","respondent":"井浦品川区保健所生活衛生課長","answer":"事前周知についてのお尋ねですが、具体的には周知内容として施設の名称や所在地、あるいは緊急時の連絡先、周辺住民からの問い合わせ方法等を周知の必須項目というところで現在考えてございまして、このあたりをしっかりと周辺の地域の住民の方に説明をし、案内をしていただいて。","voiceIndex":230,"id":"exchange-062"},{"speaker":"鈴木（真）委員","kind":"質問","question":"では最後にお聞きします。そこでクレームが起きたときに、もしなくなってしまったら区のほうに対してその辺の請求をすれば、話があったときにすぐしていただけるのかどうか。それと区の中に、これからいろいろな苦情がまた出てくると思うのですけれども、そういったときの区内の連携体制というのはもうできているのでしょうか。","respondent":"井浦品川区保健所生活衛生課長","answer":"そして住宅課が主にマンション管理組合とのパイプがありますので、住宅課を通じてしっかりとマンション管理組合とも連携をとっていただくというような形で、１０課ほど関係する課がありますので、庁内での連絡会を設けているです。","voiceIndex":232,"id":"exchange-063"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今のご答弁聞いてわかりました。ただ、やはり１個だけ気になるのがごみの問題です。管理人がいなくて、１日なら１日泊まった人が、結局そのごみをどうすればいいのかわからない。現状でもそういうところが１カ所片づいたのだけれども、今度また別のところにずっと置かれているというのも現実、今の段階では聞いているのです。","respondent":"井浦品川区保健所生活衛生課長","answer":"このあたりの情報も清掃事務所と連携を密にしまして、実態に即した形で状況を見させていただきながら、ベストな対応というような形でやっていくことになろうかと考えています。","voiceIndex":234,"id":"exchange-064"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"なぜこの民泊という、まだまだちょっと不安も多いもので、しかも国も都も、見れば見るほど不安になるガイドラインの中で、この住宅地で土日可にする理由というものを伺いたいと思います。","respondent":"井浦品川区保健所生活衛生課長","answer":"それから２点目のワンルーム等での１棟ワンオーナーというところについては、当然ワンオーナーの選択で民泊の届出というものも、要件を満たしていれば可能になるですので、しっかりとガイドラインにより、あるいは事例を積み重ねて対応していく中で。","voiceIndex":237,"id":"exchange-065"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"本当に隣の家がとなると、今回もちょっと大阪市のほうで事件なんかも起きていますけれども、もう不安でたまらないと思うのです。そこへのこうしてほしい、こうすべきだといういろいろな意見もまた、私たち含めて出てくると思うのですけれども、そういったものは柔軟にどんどん改善させていけるものなのか伺いたいと思います。","respondent":"井浦品川区保健所生活衛生課長","answer":"こちらについては、やはりゼロ日規制という形は法律の解釈上難しいというところで、大田区は特区民泊をやっている関係で、特区民泊をしていないところについてはゼロ日という形で条例を策定しましたけれども。","voiceIndex":239,"id":"exchange-066"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"すみません。品川区のガイドラインはいつ出るのですか。","respondent":"井浦品川区保健所生活衛生課長","answer":"国の法律の施行が３月１５日となってございまして、事前の相談というような形でお願いするというところもありますので、３月を過ぎて、そして条例のこちらの議決の日程等もありますが、そのようなもろもろの状況を勘案したところで。","voiceIndex":241,"id":"exchange-067"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"では３月１５日以降になってくるのか、もうちょっとかかるということなのでしょうか。やはりガイドラインなので、こういった条例がもう出ている状況でガイドライン、今資料では出していただいていますけれども、ここからは全然わからないことばかりですし、ちょっとガイドラインを早目に出しても別に構わないものなのですよね。それをやるのは保健所なのかということもちょっと伺いたいと思います。","respondent":"井浦品川区保健所生活衛生課長","answer":"それから２点目の衛生管理のところにつきましては、保健所としてしっかりと監督指導していくです。","voiceIndex":243,"id":"exchange-068"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"日ごろの任務として。それでもう月に１回も見回りができていないという、旅館も含めて、公衆浴場とか、理容所とか、美容院とか、クリーニング、こういうものを合わせるととてもとても見回れないというふうに言っているのですけれども、品川区でいうと、これは人員体制とかを強化するのか、それで民泊の衛生管理というものが監視できていくのかを伺いたいと思います。","respondent":"井浦品川区保健所生活衛生課長","answer":"環境監視というところにつきましては、年間の監視計画を策定して、きめ細かく適切な節目、節目で監視していくというような体制をとってありますので、新たに住宅宿泊事業が監視計画の中にこれから入ってまいりまして。","voiceIndex":245,"id":"exchange-069"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"そういったところでも適正な民泊が行われるのか。先ほども違法の察知、是正方法等々もありましたけれども、それを察知するのがおくれると蔓延していくということにもなりかねませんので、ぜひ厳しい対応をさらに、国や都よりもしていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":247,"id":"exchange-070"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"周知の件なのですけれども、地域に対してポスティングということなのですが、もう絶対これはだめだと思うのです。マンションの建築紛争だって予防条例の中で説明会を義務づけているではないですか。そういう中で、この民泊をやることによって、どれぐらいの宿泊客の需要を見込むのかという、そのような予想というのを立てている部分というのはあるのでしょうか。その点、２点お願いします。","respondent":"井浦品川区保健所生活衛生課長","answer":"現時点では、１点目の事前周知というところでは、私どもくれぐれも事前説明、丁寧にやっていただきたいという形で指導していくつもりですが、また今後の事例等、問題状況等も見ていきながら。","voiceIndex":249,"id":"exchange-071"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"８０％ということであれば、今の旅館やホテルでもうどうにもならないという状況ではなくて、まだまだゆとりはある、そこに民泊をさらに入れていくという感じなのでしょうか。","respondent":"井浦品川区保健所生活衛生課長","answer":"あくまでもホテル、あるいは旅館、ホテルの中にもビジネス系のものですとか、品川区はないのかもしれないのですけれども、リゾート系ですとか、幾つか区分がありまして、それぞれ固有のニーズといいますか、需要というのがある中で。","voiceIndex":251,"id":"exchange-072"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうことであれば、１回もう規制緩和したところに規制をつくっていくというのはなかなか難しいと思うのです。だから、とにかく住居専用地域は民泊ゼロ地域ということで始めるということに、ぜひしていただきたいということで要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":253,"id":"exchange-073"},{"speaker":"大倉委員","kind":"質問・要望","question":"もういろいろお話があったので、私から２つ、第５条の宿泊者の責務というところで、国や都では宿泊者の責務というところはなかったと思うのですが、この「宿泊者は、届出住宅の周辺地域の区民の生活環境に悪影響を及ぼさないようにしなければならない」というふうに条例で明記したところというものの思いだったり、意味だったり、意義だったりを教えていただきたいと思います。","respondent":"井浦品川区保健所生活衛生課長","answer":"チラシが不明になってしまった、あるいはここのあたりはどうなのかというようなところで声をお寄せいただければ、私ども持っている情報を踏まえまして、皆様の不安の声に丁寧誠実に対応してまいりたいというふうに考えているところです。","voiceIndex":255,"id":"exchange-074"},{"speaker":"大倉委員","kind":"質問・要望","question":"この宿泊者、まさに泊まっている人にもきちんと周辺の人たちに気をつけ、環境に影響を及ぼさないようにというのは、こちら側からしたらそうなのですけれども、泊まる側からしたら、なかなかそこに意識を持っていくというのは難しい中で、一体どうやって周知をしながら、これを守ってもらうやり方があるのかなと、これを見たときに思ったので、その辺を教えていただきたいです。お願いします。","respondent":"井浦品川区保健所生活衛生課長","answer":"それから２点目の相談窓口で、私どもが対応するとお答えしましたけれども、３月１日からは全国共通のワンストップサービスということで、国がコールセンターを開設する予定になってございまして、３月については平日の昼間、４月になりますと８時半から２２時まで。","voiceIndex":257,"id":"exchange-075"},{"speaker":"大倉委員","kind":"質問・要望","question":"宿泊者の責務については、そうやって丁寧に細かくやっていくことで守っていただきたいと、それはよくわかるのですが、なかなか実際難しいと思います。しっかりその辺はどう相手に伝えていくかとか、どう対応してもらうかというのは本当に難しいところではあると思いますが、ここの第５条に書いてあるので、しっかりやっていただきたいなと思います。地域の方とか。","respondent":"井浦品川区保健所生活衛生課長","answer":"騒音等については、やはりこちら現在でもそうですけれども、まず１１０番等々で対応していただきまして、それが民泊であれば情報が、翌営業日に保健所に来る、あるいは国を通じて保健所に届くというぐあいに連携していくのかなというふうに見てあります。","voiceIndex":259,"id":"exchange-076"},{"speaker":"若林委員","kind":"確認","question":"もう細かい話が出てきましたので、条例というか、ガイドラインの話になっていて、それは後で聞きますけれども、そもそものこの住宅宿泊事業の今回の条例、いわゆる民泊について品川区はどういうふうに向き合おうとして、このような規制の内容、また規制をしないということも含めて、どのような姿勢でこの条例をつくられたのかということを、基本姿勢として確認だけしておきたいと思います。","respondent":"井浦品川区保健所生活衛生課長","answer":"民泊についての基本的な姿勢ですが、２つございまして、やはり一方ではにぎわいの創出というところで、新しい営業形態ですので、そういう観点から商業地域、近隣商業地域に限って、条例での規制の対象から外すというようなところで、にぎわいの振興というところを図る。","voiceIndex":262,"id":"exchange-077"},{"speaker":"若林委員","kind":"質問・要望","question":"区民から苦情が来たり、不安があったり、何か事故があったりするようなことは、これはもう厳に区として認めませんよという強いメッセージを、ガイドラインなり、またいろいろな周知、アナウンスなり、広報なりで、やはり品川区の姿勢というものをこれからやろうとしている方、また不安に思っている区民にも、区の姿勢がきちんと伝わるよう、しっかりとまずは示していった上で。","respondent":"井浦品川区保健所生活衛生課長","answer":"やはり法律というものが前提としてはありますので、区でしっかりと品川区独自の規制をしていきながら、守っていただくべきところはしっかりと守っていただくというところは揺るぎない形で進めていきたいというふうに考えてあります。","voiceIndex":264,"id":"exchange-078"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"反対です。ちょっと規制が余りにも緩過ぎて、住民に対しても説明会や協定書の義務づけもなく、周知はポスティング、そしてまた常駐者についても、原則ということで例外も認めてしまう、また、旅館業法でも住居専用地域はつくれない状況になっているにもかかわらず、民泊をつくっていくという、こういうところでは本当に不安がますます増えていくという、規制が余りにも緩過ぎるということで反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":269,"id":"exchange-079"}]},{"id":"topic-10","title":"第３８号議案 東京都後期高齢者医療広域連合規約の変更","agenda":"第３８号議案 東京都後期高齢者医療広域連合規約の変更","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その決定はいつされるのかということと、それから前回の平成２６・２７年度と比べて平成２８・２９年度というのは、均等割は全く上がっていないという状況だったのですけれども、今回は均等割が上がって所得割が下がっているという状況になっていて、なぜ均等割を上げて所得割を下げたのかというところをちょっと教えていただきたいと思います。","respondent":"三ッ橋国保医療年金課長","answer":"東京都の広域連合といたしましても、制度発足以来、この４項目の特別対策や所得割独自軽減は継続しておりまして、この剰余金も１８０億円ということもありますので、引き続き保険料が値上がりしないように対応しています。","voiceIndex":277,"id":"exchange-080"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひそのような希望をしていただきたいと思うのですけれどもいかがでしょうかということと、私先ほど伺ったのは、均等割と所得割の割り率というのはいつも、国保などでもあると思うのですが、そういうところで均等割が上がって所得割が下がったという、その考え方ですか。その辺のところをお聞かせいただきたいなと思ったのです。それを決めるのはいつなのかということもお聞かせください。","respondent":"三ッ橋国保医療年金課長","answer":"この間、最初は３項目の特例対策がございまして、その後４項目に増え、そして最終的には今の東京都の広域連合の所得割額の部分がありますので、５項目という形になっておりまして、今回の保険料改定に当たっても、保険料の大幅な上昇が見込まれたため。","voiceIndex":279,"id":"exchange-081"}]},{"id":"topic-11","title":"今定例会の代表・一般質問に係る所管質問ですが、今定例会の代表・一般質問中、厚生委員会に係る項目","agenda":"今定例会の代表・一般質問に係る所管質問ですが、今定例会の代表・一般質問中、厚生委員会に係る項目","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"確認","question":"分娩再開まで時間がかかるということでのご報告だったのですけれども、ということは、産婦人科は廃止ということではなくて、体制ができ次第また再開するということで確認させていただいていいでしょうか。その再開のめどというのは、いつぐらいなどというのはわからないものなのか、その点お願いします。","respondent":"川島健康課長","answer":"ですので、少しお時間がかかるという話でして、そのまま廃止にするということは当然言っておりません。ただ少しお時間をくださいというような説明を、現行の東芝病院のほうでもそういう説明を今しているところですので、私どものほうでわかるところはそこまでだです。","voiceIndex":294,"id":"exchange-082"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"こういうものを見ると、なくなってしまうのかという、病院として存続させてくれるというか、緑野会が引き受けてくれたというところは一安心したのですけれども、その後がやはりどうなってしまうのだろうということで、今の課長の話だと、そうするとその産科に限らず、各診療科も再開に向けて鋭意努力がされているということなのでしょうか。","respondent":"川島健康課長","answer":"今副委員長がおっしゃったとおり、努力している最中だということ、それから引き継ぎに伴う医師の確保の関係でというようなところですけれども、そのままなくなってしまうというような形ではなくて、努力を今続けている最中だというふうに話を聞いてあります。","voiceIndex":297,"id":"exchange-083"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3498#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":86333,"voices":300}}]);
